window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0231", [{"word":"vary","ipa_uk":"/ˈveəri/","ipa_us":"/ˈveri/","definition_zh":"变化；变动；相异；使多样化；随……而变；调节","definition_en":"to change or differ, or to make something change in form, level or amount","core_image":"一排同样的零件摆在检测台上，卡尺一量，尺寸读数一个比一个差一点","scene":"同一批零件摆上检测台，读数一份份报出来，最大与最小差了半毫米。Test results vary slightly from one batch to the next.","sceneCN":"这里指不同批次之间的读数存在差异（第 2 个义项：彼此不同、有差异）；句意为检测结果在批次之间略有出入。图中可辨识物件：检测台、卡尺、并排摆放的零件。","pos":[{"tag":"v.","zh":"变化；使多样化；随……而变"}],"collocations":[{"phrase":"vary widely","zh":"差别很大"},{"phrase":"vary considerably","zh":"有相当大的变化"},{"phrase":"vary from place to place","zh":"因地而异"},{"phrase":"vary with","zh":"随……而变化"},{"phrase":"vary in size","zh":"大小不一"},{"phrase":"vary the routine","zh":"变换日常安排"},{"phrase":"vary the pace","zh":"调整节奏"}],"forms":[{"label":"动词原形","form":"vary"},{"label":"第三人称单数","form":"varies"},{"label":"过去式","form":"varied"},{"label":"过去分词","form":"varied"},{"label":"现在分词","form":"varying"},{"label":"名词","form":"variation"},{"label":"形容词","form":"variable"}],"derivatives":[{"word":"variation","pos":"n.","zh":"由该动词加表示动作结果的名词尾构成，义为「变化；变异」"},{"word":"variety","pos":"n.","zh":"由同一拉丁词干经法语而来，义为「多样性；种类」"},{"word":"variable","pos":"adj./n.","zh":"由该动词加「可……的」形容词尾构成，义为「可变的；变量」"},{"word":"variability","pos":"n.","zh":"由形容词加表示性质的名词尾构成，义为「可变性」"},{"word":"various","pos":"adj.","zh":"由同一拉丁词干加「充满……」的形容词尾构成，义为「各种各样的」"},{"word":"varied","pos":"adj.","zh":"由该动词加已然词尾构成，义为「多变化的；各式各样的」"},{"word":"invariable","pos":"adj.","zh":"由否定前缀加形容词构成，义为「不变的」"}],"senses":[{"no":"01","title":"To change over time","titleCN":"随时间发生变化","definition":"to become different in form, level or amount as conditions change","definitionCN":"随着条件改变，在形态、水平或数量上变得不同","example":"Water pressure varies along the pipe as the flow speed changes.","exampleCN":"随着流速变化，管道各处的压力也不同。","why":"The Latin verb meant to alter or alternate, and its first English use was simply to undergo change.","whyCN":"拉丁动词本义是改变、轮换，英语最早就是「发生变化」这个用法。"},{"no":"02","title":"To differ from one another","titleCN":"彼此不同；有差异","definition":"to be different in size, quality or amount when two or more things are compared","definitionCN":"两个或多个事物在大小、质量或数量上互相不同","example":"Prices vary from store to store in the same district.","exampleCN":"同一个区里各家商店的价格并不相同。","why":"Once two things are placed side by side, the same verb reports the difference between them rather than a change in one.","whyCN":"两样东西一并排，这个动词就转而报告它们之间的差别，而不是单方的改变。"},{"no":"03","title":"To make something diverse","titleCN":"使某物多样化","definition":"to introduce differences into something so that it is not uniform","definitionCN":"在某物中引入差异，使它不再千篇一律","example":"The teacher varies the tasks so that every learner stays engaged.","exampleCN":"老师变换任务形式，让每个学生都保持投入。","why":"Adding variety to a thing is the transitive mirror of the intransitive sense: instead of differing, you cause the difference.","whyCN":"给事物增加变化，是「自身不同」这一不及物义的反身镜像：不是有别，而是使之有别。"},{"no":"04","title":"To change according to a factor","titleCN":"随某因素而变化","definition":"to rise or fall in line with another quantity or condition","definitionCN":"随另一数量或条件一同升降","example":"Crop yields vary with rainfall across the region.","exampleCN":"该地区的作物产量随降雨量而变化。","why":"The preposition with marks the factor that drives the change, a pattern already common in the Latin verb.","whyCN":"介词随同标出驱动变化的因素，这一搭配在拉丁动词里已很常见。"},{"no":"05","title":"To adjust a setting","titleCN":"调节某一设定","definition":"to alter a speed, level or setting deliberately within a range","definitionCN":"在一定范围内有意改动速度、强度或设置","example":"The technician varied the fan speed to test the bearing.","exampleCN":"技术员调了风扇转速来测试轴承。","why":"Deliberate adjustment is change under control, so the verb moves from what happens to what a person does.","whyCN":"有意的调整是受控的改变，于是这个动词从「发生了什么」转向「人做了什么」。"},{"no":"06","title":"To fluctuate around a level","titleCN":"上下波动；时高时低","definition":"to move repeatedly up and down around a general level rather than in one direction","definitionCN":"围绕某一总体水平反复起落，而不是单向变化","example":"Demand varies through the year, peaking before the holidays.","exampleCN":"需求全年起落，节前达到高峰。","why":"The word covers repeated small shifts, not a single permanent change, and that rhythmic reading comes from its root meaning of alternation.","whyCN":"这个词涵盖反复的小幅移动，而非一次永久改变，这种节律感来自词根的「轮换」义。"},{"no":"07","title":"To change in proportion","titleCN":"按比例变化","definition":"to change together with another quantity at a fixed or inverse ratio","definitionCN":"与另一数量按固定比例或反比例一同变化","example":"In this experiment, pressure varies directly with temperature.","exampleCN":"在这个实验里，压力与温度成正比变化。","why":"Science borrowed the everyday verb for its exact mathematical reading of two quantities moving together.","whyCN":"科学借用了这个日常动词，用来精确表达两个量同步变动的数学关系。"},{"no":"08","title":"To rotate or ring the changes","titleCN":"轮换；变换花样","definition":"to alternate routes, methods or items so that no single one is used all the time","definitionCN":"在路线、方法或物件之间轮换，使任何一项都不被一直使用","example":"The crew varies its route to avoid the morning congestion.","exampleCN":"这个班组轮换路线，以避开早高峰。","why":"Alternating is the oldest kernel of the word, and rotating a routine is simply alternation made practical.","whyCN":"轮换是这个词最古老的内核，而把日常安排轮着来，只是轮换落到实用层面。"}],"etymology":{"intro":{"en":"Vary comes from Latin varius, meaning spotted or diverse, through the verb variare, to change. French carried it into English, where it first described things changing and later things differing.","cn":"这个词来自拉丁语 varius「杂色的、多样的」，经动词 variare「使变化」、再经法语进入英语；最初说事物发生变化，后来也说事物彼此不同。"},"items":[{"era":"LATIN VARIUS","en":"Varius described something mottled or spotted, and from that picture of mixed patches came the meaning diverse or changeable.","cn":"这个词形容带斑点的、杂色的东西；正是从「杂色拼在一起」的画面生出「多样、易变」的意思。"},{"era":"LATIN VARIARE","en":"The verb variare meant to change, alternate or diversify, and it was used of colours, seasons and opinions alike.","cn":"动词意为改变、轮换、使多样，颜色、季节、意见都可以用它。"},{"era":"OLD FRENCH VARIER","en":"Old French and Anglo-Norman passed the verb to English, keeping both the change and the differ readings.","cn":"古法语与盎格鲁诺曼语把这个动词传给英语，同时保留了「变化」与「相异」两条读法。"},{"era":"ENGLISH, 14TH CENTURY","en":"The verb is recorded in English from the fourteenth century; the exact first date is uncertain and is usually given only as that century.","cn":"这个动词在英语中自十四世纪有记录，确切首见年代不确定，通常只给「十四世纪」这一约数。"},{"era":"THE VARIUS FAMILY","en":"Variety, various, variable and variation all descend from the same Latin stem, which is why the family feels so uniform.","cn":"多样性、各种各样的、可变的、变化都出自同一拉丁词干，所以这一族词看起来高度统一。"},{"era":"MODERN TECHNICAL USE","en":"Statistics and physics adopted the verb for measured quantities, giving fixed phrases such as vary directly and vary inversely.","cn":"统计学与物理学把这个动词用于可测量的量，形成「成正比变化」「成反比变化」等固定说法。"}]},"similar":{"note":{"en":"The first group shares the Latin stem or merely looks close; the second group names nearby ideas of change and difference.","cn":"第一组与「vary」共享拉丁词干或只是形近；第二组是与「变化、差异」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"variety","ipa":"/vəˈraɪəti/","tag":"same root","definition":"The noun for diversity or a kind, from the same Latin stem but with a different ending.","definitionCN":"指多样性或种类，同出拉丁词干，只是词尾不同。"},{"word":"various","ipa":"/ˈveəriəs/","tag":"same root","definition":"An adjective meaning several and different, built on the same stem.","definitionCN":"形容词，指多种多样的、不同的，词干相同。"},{"word":"variable","ipa":"/ˈveəriəbl/","tag":"same root","definition":"Something that can change, or a quantity that may take different values.","definitionCN":"指可变的，或指可取不同值的变量。"},{"word":"very","ipa":"/ˈveri/","tag":"different root","definition":"An intensifier from Old French verai, true; it looks close but belongs to a different word.","definitionCN":"程度副词，来自古法语「真实的」；形近但属另一个词。"},{"word":"varied","ipa":"/ˈveəriːd/","tag":"same root","definition":"The adjective meaning of several different kinds, built on the same stem.","definitionCN":"形容词，指多种多样的，同出同一词干。"}]},{"heading":"NEAR MEANING","entries":[{"word":"change","ipa":"/tʃeɪndʒ/","tag":"near meaning","definition":"To become or make different, the broadest verb of alteration.","definitionCN":"指变得不同或使不同，是最宽泛的改变动词。"},{"word":"differ","ipa":"/ˈdɪfə/","tag":"near meaning","definition":"To be unlike another thing, with no idea of change over time.","definitionCN":"指与另一事物不同，不含随时间变化的意思。"},{"word":"fluctuate","ipa":"/ˈflʌktʃueɪt/","tag":"near meaning","definition":"To rise and fall irregularly around a level.","definitionCN":"指围绕某一水平不规则地起落。"},{"word":"alternate","ipa":"/ˈɔːltəneɪt/","tag":"near meaning","definition":"To take turns one after the other, the oldest core of vary.","definitionCN":"指两者轮流交替，是这个词最古老的内核。"},{"word":"diversify","ipa":"/daɪˈvɜːsɪfaɪ/","tag":"near meaning","definition":"To add variety to something, especially in business or farming.","definitionCN":"指使多样化，多用于经营或农业。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the spotted root, the real word family and the fixed patterns vary with and vary from.","cn":"正常联想使用「杂色」这一词根画面、真实同族词，以及「随……变化」「因地而异」这些固定搭配。"},"normal":[{"en":"Latin varius meant spotted, so the first picture is a coat of many patches.","cn":"拉丁语 varius 是「带斑点的」，最初的画面就是一件补丁斑驳的外衣。"},{"en":"Vary, variety, various, variable and variation are one family with one stem.","cn":"变化、多样性、各种各样的、可变的、名词形式都是同词干的一族。"},{"en":"Vary with marks the factor, as in vary with rainfall.","cn":"「随……变化」的搭配标出因素，例如「随降雨量变化」。"},{"en":"Vary from place to place is a fixed phrase for regional difference.","cn":"「因地而异」是表示地区差异的固定说法。"},{"en":"A varied diet is the adjective form used in health writing.","cn":"「多样的饮食」用的是它的形容词形式，健康类文章常见。"}],"abstract":[{"en":"To vary is to refuse to be the same twice, which is how living things survive.","cn":"变化就是拒绝两次一模一样，生命正是这样存续的。"},{"en":"Difference is variation seen from the outside; change is variation seen from the inside.","cn":"差异是站在外面看到的变化，变化是站在里面看到的差异。"},{"en":"A measured quantity that never varies is either dead or badly instrumented.","cn":"一个从不波动的测量值，要么是死的，要么是仪器坏了。"}]},"examples":[{"en":"The colour of the leaves varies with the season.","cn":"叶子的颜色随季节变化。"},{"en":"Prices vary widely between the two markets.","cn":"两个市场的价格差别很大。"},{"en":"The coach varies the training plan to keep the players fresh.","cn":"教练变换训练计划，让队员保持新鲜感。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「外瑞」——同一批货，这回一个样，下回另一个样：变化、相异","word":"vary"},"root":"拉丁语 varius「杂色的、多样的」→ variare「使变化」→ 法语 varier；更早词源属重构形式。英语十四世纪引入，首见年代不确定，通常只给约数。","sensesIntro":{"en":"Eight senses move from a single thing changing to two things differing, then to deliberate adjustment, fluctuation, ratio and rotation.","cn":"八个义项从「一物自身变化」走到「两物彼此不同」，再到有意调节、波动、比例与轮换。"},"semanticMap":{"core":{"en":"CORE IMAGE: one row of parts is measured again and again, and no two readings match exactly.","cn":"核心意象：同一排零件反复测量，没有两次读数完全相同。"},"chain":["SAME OBJECT","DIFFERENT STATES","TWO OBJECTS COMPARED","CONTROLLED ADJUSTMENT","RHYTHMIC FLUCTUATION","FIXED RATIO"],"branches":[{"senses":"01","en":"THE OBJECT CHANGES: a single thing takes on a new form or level.","cn":"自身改变：同一事物呈现出新的形态或水平。"},{"senses":"02 · 08","en":"THE DIFFERENCE APPEARS: two things fail to match, or a routine is rotated to avoid sameness.","cn":"差异显现：两物对不上，或把安排轮着来以免千篇一律。"},{"senses":"04","en":"THE DEPENDENCE: change follows a named factor such as rainfall or temperature.","cn":"依附关系：变化跟着某个被点名的因素走，如降雨或温度。"},{"senses":"03 · 05","en":"THE HAND ON THE DIAL: someone deliberately adjusts a setting, or deliberately makes a set more varied.","cn":"手放在旋钮上：有人在范围内调整设定，也有人有意把一组东西变得多样。"},{"senses":"06 · 07","en":"THE PATTERN: repeated ups and downs, or two quantities moving at a fixed ratio.","cn":"规律形态：反复起落，或两个量按固定比例同步移动。"}]},"affixes":{"intro":{"en":"Vary is a Latin verb whose stem also supplies the whole English family of variety, various and variable.","cn":"这是一个拉丁动词，其词干还供应了英语里表示多样性、各种各样、可变的整族词。"},"latinIntro":{"en":"Latin supplies varius, variare, varietas and variatio; the deeper origin behind them is reconstructed rather than recorded.","cn":"拉丁语提供了「杂色的」「使变化」「多样性」「变化」四个词；它们更早的来源属重构而非有记录的形式。"},"items":[{"word":"varius","structure":"Latin adjective","meaning":"spotted; diverse; changeable","meaningCN":"杂色的；多样的；易变的","example":"The adjective described a coat of many colours.","exampleCN":"这个形容词形容一件多色的外衣。"},{"word":"variare","structure":"Latin verb from varius","meaning":"to change; to alternate","meaningCN":"改变；轮换","example":"The verb named the act of altering.","exampleCN":"这个动词指改变这一动作。"},{"word":"varietas","structure":"Latin noun from varius","meaning":"diversity; a kind","meaningCN":"多样性；种类","example":"The noun named the state of being mixed.","exampleCN":"这个名词指混杂的状态。"},{"word":"variatio","structure":"Latin noun from variare","meaning":"a change; variation","meaningCN":"变化；变动","example":"The noun named the result of changing.","exampleCN":"这个名词指改变后的结果。"},{"word":"-are","structure":"Latin verb ending","meaning":"to make or do","meaningCN":"做；使","example":"The ending marks the infinitive of the verb.","exampleCN":"这个词尾标明动词不定式。"},{"word":"-ety","structure":"noun ending through French","meaning":"state or quality","meaningCN":"性质；状态","example":"It forms the noun of diversity.","exampleCN":"它构成表示多样性的名词。"},{"word":"-able","structure":"adjective ending","meaning":"capable of being","meaningCN":"可……的","example":"It forms the word for what can change.","exampleCN":"它构成表示「可变化的」的词。"},{"word":"-ation","structure":"action-result noun ending","meaning":"the act or result of changing","meaningCN":"变化的动作或结果","example":"It forms the noun of a change.","exampleCN":"它构成表示一次变化的名词。"},{"word":"-ous","structure":"adjective ending","meaning":"full of, characterized by","meaningCN":"充满……的","example":"It forms the word for many different kinds.","exampleCN":"它构成表示「多种多样」的词。"}],"latinEntries":[{"word":"varius","structure":"Latin adjective","meaning":"spotted, diverse","meaningCN":"杂色的；多样的"},{"word":"variare","structure":"Latin verb","meaning":"to change, alternate","meaningCN":"改变；轮换"},{"word":"varietas","structure":"Latin noun","meaning":"diversity, kind","meaningCN":"多样性；种类"},{"word":"variatio","structure":"Latin noun","meaning":"a change","meaningCN":"变化"}],"derivatives":[{"word":"variation","pos":"n.","zh":"由该动词加表示动作结果的名词尾构成，义为「变化；变异」"},{"word":"variable","pos":"adj./n.","zh":"由该动词加「可……的」形容词尾构成，义为「可变的；变量」"},{"word":"variety","pos":"n.","zh":"由同一拉丁词干经法语而来，义为「多样性；种类」"},{"word":"various","pos":"adj.","zh":"由同一拉丁词干加「充满……」的形容词尾构成，义为「各种各样的」"},{"word":"varied","pos":"adj.","zh":"由该动词加已然词尾构成，义为「多变化的；各式各样的」"}]}},{"word":"withstand","ipa_uk":"/wɪðˈstænd/","ipa_us":"/wɪθˈstænd/","definition_zh":"承受；抵挡；经受住；抗住","definition_en":"to bear or resist pressure, force, attack or difficult conditions without giving way","core_image":"桥面在重卡与强风同时压来，梁体微微下沉却始终没有裂开","scene":"这座桥按百年一遇的标准设计，重卡与强风同时压来也不变形。The bridge is built to withstand heavy trucks and strong winds.","sceneCN":"这里指结构承受住外力而不损坏（第 1 个义项：承受住压力或重量）；句意为这座桥就是按承受重卡与强风来建造的。图中可辨识物件：桥墩、货车、侧向风线。","pos":[{"tag":"v.","zh":"承受；抵挡；经受住"}],"collocations":[{"phrase":"withstand pressure","zh":"承受压力"},{"phrase":"withstand the impact","zh":"抵挡冲击"},{"phrase":"withstand extreme heat","zh":"耐高温"},{"phrase":"withstand corrosion","zh":"抗腐蚀"},{"phrase":"withstand scrutiny","zh":"经得起审视"},{"phrase":"withstand temptation","zh":"抵住诱惑"}],"forms":[{"label":"动词原形","form":"withstand"},{"label":"第三人称单数","form":"withstands"},{"label":"过去式","form":"withstood"},{"label":"过去分词","form":"withstood"},{"label":"现在分词","form":"withstanding"},{"label":"名词","form":"withstanding"}],"derivatives":[{"word":"withstanding","pos":"n./adj.","zh":"由该动词加表示进行或性质的后缀构成，义为「承受；经得住的」"},{"word":"withstood","pos":"adj.","zh":"由该动词的不规则过去分词转作形容词，义为「经受住了的」"},{"word":"withstander","pos":"n.","zh":"由该动词加表示施动者的名词尾构成，义为「承受者」（少用）"},{"word":"notwithstanding","pos":"prep./conj.","zh":"由否定词与「经受、让步」形式合成，义为「尽管；虽然」"}],"senses":[{"no":"01","title":"To bear a physical load","titleCN":"承受物理负荷","definition":"to hold up under the weight or pressure of something without breaking or deforming","definitionCN":"在重物或压力的作用下支撑住，而不破裂或变形","example":"The alloy can withstand pressure above two hundred atmospheres.","exampleCN":"这种合金能承受两百多个大气压。","why":"The oldest sense is a structure standing its ground while a load presses on it.","whyCN":"最古老的义项就是结构在负荷压来时站住不退。"},{"no":"02","title":"To resist an attack","titleCN":"抵挡攻击","definition":"to defend against a blow, assault or military action without yielding","definitionCN":"抵御打击、袭击或军事行动而不退让","example":"The walls withstood three days of bombardment.","exampleCN":"这些城墙顶住了三天的炮击。","why":"The prefix means against, so resisting an active attack is the same word standing firm against a force.","whyCN":"前缀的意思是「对着」，因此抵挡主动攻击仍是同一个「顶住力量」的画面。"},{"no":"03","title":"To endure the test of time","titleCN":"经受时间的考验","definition":"to remain in good condition or valid over a long period","definitionCN":"在很长一段时间里保持良好状态或依然成立","example":"The treaty withstood decades of political change.","exampleCN":"这份条约经受住了数十年的政治变迁。","why":"Time is treated as a force that presses, and surviving it is the same verb applied to duration.","whyCN":"时间被当作一种施压的力量，熬过它就是这个动词用在「时长」上。"},{"no":"04","title":"To resist weather or the elements","titleCN":"抗住自然环境","definition":"to remain intact under heat, cold, wind, water or salt","definitionCN":"在高温、严寒、强风、水或盐的作用下保持完好","example":"These panels withstand salt spray on the coast.","exampleCN":"这些板材在海边能抗住盐雾。","why":"Material science inherited the verb for the weather, because weather acts on a surface much as a load acts on a beam.","whyCN":"材料科学沿用了这个动词来谈气候，因为气候作用于表面，就像负荷作用于梁。"},{"no":"05","title":"To resist temptation","titleCN":"抵住诱惑","definition":"to keep oneself from yielding to a strong desire or pressure of a personal kind","definitionCN":"克制自己，不向强烈的欲望或人情压力让步","example":"She withstood the offer long enough to read the contract.","exampleCN":"她抵住那份报价的诱惑，先把合同读完。","why":"The physical picture becomes moral: what presses now is desire, and standing firm is still the same act.","whyCN":"物理画面转向道德：此时施压的是欲望，而站住不退仍是同一个动作。"},{"no":"06","title":"To survive close examination","titleCN":"经得起审视","definition":"to remain credible when checked, questioned or challenged in detail","definitionCN":"在被逐条核查、质疑或追问时依然站得住","example":"The claim withstood every check the reviewers made.","exampleCN":"这个说法经受住了审稿人的每一项核查。","why":"Scrutiny is pressure applied to a statement, and the word treats a weak argument as a structure that may crack.","whyCN":"审视是对说法施加的压力，这个词把脆弱的论证当作可能开裂的结构。"},{"no":"07","title":"To hold against competition","titleCN":"顶住竞争压力","definition":"to keep one's position against a stronger rival or market force","definitionCN":"在更强的对手或市场力量面前保住位置","example":"Small shops withstood the arrival of the chain store.","exampleCN":"小店顶住了连锁店进驻的冲击。","why":"Commercial pressure is another load, and the verb lets a firm stand like a pier in a current.","whyCN":"商业压力是另一种负荷，这个词让企业像急流里的桥墩一样立住。"},{"no":"08","title":"To resist corrosion or disease","titleCN":"抗腐蚀；抵抗病害","definition":"to be immune or highly resistant to a chemical or biological agent","definitionCN":"对某种化学或生物因子具有免疫或很强的抵抗力","example":"Some varieties withstand the fungus better than others.","exampleCN":"有些品种抗这种真菌的能力更强。","why":"Biological resistance is the newest extension: an agent attacks, and the organism stands against it.","whyCN":"生物抗性是这一层最新的延伸：因子来攻，生物体对着它站住。"}],"etymology":{"intro":{"en":"Withstand is an Old English compound of with, meaning against, and standan, to stand. It has meant to stand against a force since before the Norman conquest.","cn":"这是古英语的合成词，由表示「对着」的 with 与 standan「站立」构成；早在诺曼征服之前就表示「对着力量站住」。"},"items":[{"era":"OLD ENGLISH WITH","en":"The Old English prefix with did not mean together as it often does today; in compounds it meant against or away.","cn":"古英语的前缀 with 并不像今天常表示的「一起」，在复合词里意思是「对着」或「离开」。"},{"era":"OLD ENGLISH STANDAN","en":"Standan meant to stand, and it is the same verb that gives modern stand and the whole stand family.","cn":"这个词意为站立，也是现代 stand 与整个 stand 词族的来源。"},{"era":"THE COMPOUND","en":"Wiðstandan joined the two into one verb meaning to stand against, and it already covered both physical and moral resistance.","cn":"两个词合为一词，义为「对着站住」，当时已兼指身体与道义上的抵抗。"},{"era":"MIDDLE ENGLISH SPELLING","en":"The spelling settled as withstand, and the past tense withstood followed the strong pattern of stand and stood.","cn":"拼写后来固定为 withstand，过去式 withstood 沿用 stand、stood 的强变化。"},{"era":"GERMANIC BACKGROUND","en":"The two parts are Germanic rather than Latin; the deeper prehistoric root is a reconstruction rather than a recorded form.","cn":"两部分属日耳曼语而非拉丁语；更早的史前词根是重构形式，不是有记录的词。"},{"era":"MODERN ENGINEERING","en":"Engineering standards gave the verb new fixed objects such as pressure, corrosion and seismic load.","cn":"工程标准又给这个动词添了压力、腐蚀、地震荷载等新的固定宾语。"}]},"similar":{"note":{"en":"The first group shares the stand root or merely looks close; the second group names neighbouring ideas of endurance and defence.","cn":"第一组与「withstand」共享 stand 词根或只是形近；第二组是与「承受、防御」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"withstood","ipa":"/wɪðˈstʊd/","tag":"same root","definition":"The past tense and past participle, formed on the strong verb pattern.","definitionCN":"过去式与过去分词，按强变化构成。"},{"word":"withstanding","ipa":"/wɪðˈstændɪŋ/","tag":"same root","definition":"The present participle, also used in the fixed word notwithstanding.","definitionCN":"现在分词，也出现在固定词 notwithstanding 中。"},{"word":"stand","ipa":"/stænd/","tag":"same root","definition":"The base verb, which supplies the second half of the compound.","definitionCN":"基础动词，提供这个复合词的后半部分。"},{"word":"hinder","ipa":"/ˈhɪndə/","tag":"different root","definition":"To obstruct or slow something; it looks like a fellow verb of resistance but has its own root.","definitionCN":"指阻碍、拖慢；看着像同一类抵抗动词，其实另有词根。"},{"word":"withdraw","ipa":"/wɪðˈdrɔː/","tag":"different root","definition":"To pull back or remove; it shares the prefix but not the stand root.","definitionCN":"指撤回、取出；前缀相同，但没有 stand 词根。"}]},{"heading":"NEAR MEANING","entries":[{"word":"endure","ipa":"/ɪnˈdjʊə/","tag":"near meaning","definition":"To suffer or last through something difficult, with an emphasis on time.","definitionCN":"指忍受或持续熬过困难，侧重时间。"},{"word":"resist","ipa":"/rɪˈzɪst/","tag":"near meaning","definition":"To oppose a force actively, often from outside.","definitionCN":"指主动对抗某种力量，常从外部施加。"},{"word":"bear","ipa":"/beə/","tag":"near meaning","definition":"To carry a weight or put up with a burden.","definitionCN":"指承载重量或忍受负担。"},{"word":"tolerate","ipa":"/ˈtɒləreɪt/","tag":"near meaning","definition":"To allow or put up with something without protest.","definitionCN":"指容许或默默忍受。"},{"word":"survive","ipa":"/səˈvaɪv/","tag":"near meaning","definition":"To continue to exist after a threat has passed.","definitionCN":"指在威胁过去之后仍然存在。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the two halves of the compound, its strong past tense and its engineering phrases.","cn":"正常联想使用这个合成词的两个部分、它的强变化过去式以及工程搭配。"},"normal":[{"en":"With here means against, not together, so withstand is literally stand against.","cn":"这里的 with 是「对着」而非「一起」，所以这个词字面就是「对着站」。"},{"en":"Stand and stood give the whole paradigm; the past is withstood, never withstanded.","cn":"stand 与 stood 决定了整个变化，过去式是 withstood，不是 withstanded。"},{"en":"Engineers say a material withstands heat, pressure or corrosion.","cn":"工程师说材料能承受热、压力或腐蚀。"},{"en":"Withstand scrutiny is the fixed phrase for an argument that survives checking.","cn":"「经得起审视」是「论证经得起核查」的固定说法。"},{"en":"The word has no regular -ed form, so the old strong pattern is the memory hook.","cn":"这个词没有规则的 -ed 形式，古老强变化本身就成了记忆钩子。"}],"abstract":[{"en":"To withstand is to let the force pass through you without letting it change your shape.","cn":"承受，就是让力量穿过自己，却不让它改变自己的形状。"},{"en":"Every structure that stands is a decision to hold a shape against a push.","cn":"每一个立着的结构，都是「在推力下守住形状」的决定。"},{"en":"What a person can withstand is less about hardness than about how well the load is distributed.","cn":"人能承受多少，与其说取决于硬度，不如说取决于负荷被分散得好不好。"}]},"examples":[{"en":"The shelter is designed to withstand winds of up to two hundred kilometres an hour.","cn":"这个避难所按抵御每小时两百公里强风来设计。"},{"en":"Her argument withstood every question the panel raised.","cn":"她的论证经受了评审提出的每一个问题。"},{"en":"Few crops can withstand such a long dry spell.","cn":"很少有作物能扛住这么长的干旱期。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「威兹斯坦德」——对着风站住，风再大也不挪位：承受、抵挡","word":"withstand"},"root":"古英语 wiðstandan = wið「对着」+ standan「站立」；属日耳曼语复合词，更早词根为重构形式。过去式 withstood 沿用强变化。","sensesIntro":{"en":"Eight senses apply one picture, standing against a force, to load, attack, time, weather, desire, scrutiny, competition and corrosion.","cn":"八个义项把「对着力量站住」这一画面分别用于负荷、攻击、时间、气候、欲望、审视、竞争与腐蚀。"},"semanticMap":{"core":{"en":"CORE IMAGE: a pier holds its shape while trucks and wind press on the deck above.","cn":"核心意象：货车与强风压在上方，桥墩仍守住自己的形状。"},"chain":["AGAINST","PHYSICAL LOAD","ACTIVE ATTACK","LONG DURATION","PERSONAL PRESSURE","CHECKING FORCE"],"branches":[{"senses":"01 · 04","en":"THE BEAM HOLDS: weight, heat, salt and wind press, and the material does not yield.","cn":"梁体守住：重量、高温、盐雾与风压来，材料不让步。"},{"senses":"02","en":"THE WALL FACES THE BLOW: an active attack arrives and is turned back.","cn":"墙迎击打：主动的攻击到来，被挡回去。"},{"senses":"03 · 07","en":"THE LONG SIEGE: decades of change or a stronger rival, and the position is kept.","cn":"长期围困：数十年的变迁或更强的对手，位置仍保住。"},{"senses":"05","en":"THE INWARD PUSH: desire or pressure acts on a person, who still declines.","cn":"向内施压：欲望或压力作用于人，人仍然拒绝。"},{"senses":"06 · 08","en":"THE CLOSE CHECK: questions, or a fungus, press against a claim or a plant, and it holds.","cn":"近距离核查：问题或真菌压向一个说法或一株植物，它仍站得住。"}]},"affixes":{"intro":{"en":"Withstand is a Germanic compound, so its two halves are ordinary English words rather than Latin affixes.","cn":"这是一个日耳曼语复合词，两部分都是普通英语词，而不是拉丁词缀。"},"latinIntro":{"en":"There is no Latin source for this compound; the Latin column stays empty rather than being filled with unrelated forms.","cn":"这个复合词没有拉丁语来源，因此拉丁部分留空，不拿无关形式来凑。"},"items":[{"word":"with-","structure":"Old English prefix","meaning":"against, away","meaningCN":"对着；离开","example":"In compounds it marks opposition, not company.","exampleCN":"在复合词里它标出对立，而不是陪伴。"},{"word":"stand","structure":"Old English verb","meaning":"to stand, to remain upright","meaningCN":"站立；保持直立","example":"The verb supplies the physical picture.","exampleCN":"这个动词提供物理画面。"},{"word":"-stand","structure":"compound second element","meaning":"to hold a position","meaningCN":"守住位置","example":"It carries the sense of not moving under pressure.","exampleCN":"它承载「受压而不移动」的意思。"},{"word":"stood","structure":"strong past form","meaning":"stood, has stood","meaningCN":"站住了；已站住","example":"The old pattern replaces the regular ending.","exampleCN":"古老的变化取代了规则词尾。"},{"word":"-ing","structure":"verbal noun ending","meaning":"the act of holding","meaningCN":"承受这一动作","example":"It forms withstanding, also seen in notwithstanding.","exampleCN":"它构成 withstanding，也见于 notwithstanding。"},{"word":"notwithstanding","structure":"compound preposition","meaning":"in spite of","meaningCN":"尽管；虽然","example":"It grew from the same stand core with a negative in front.","exampleCN":"它由同一 stand 核心前加否定词长成。"},{"word":"withstander","structure":"agent noun","meaning":"one who withstands","meaningCN":"承受者","example":"The ending is regular but the noun is rare.","exampleCN":"词尾规则，但这个名词很少用。"},{"word":"load-bearing","structure":"related compound","meaning":"carrying a structural load","meaningCN":"承重的","example":"It names the same engineering idea from the load side.","exampleCN":"它从负荷一侧命名同一工程概念。"}],"latinEntries":[],"derivatives":[{"word":"withstanding","pos":"n./adj.","zh":"由该动词加表示进行或性质的后缀构成，义为「承受；经得住的」"},{"word":"withstood","pos":"adj.","zh":"由不规则过去分词转作形容词，义为「经受住了的」"},{"word":"withstander","pos":"n.","zh":"由该动词加表示施动者的名词尾构成，义为「承受者」（少用）"},{"word":"notwithstanding","pos":"prep./conj.","zh":"由否定词与「经受、让步」形式合成，义为「尽管；虽然」"}]}},{"word":"aggravate","ipa_uk":"/ˈæɡrəveɪt/","ipa_us":"/ˈæɡrəveɪt/","definition_zh":"加重；使恶化；加剧；激怒；使恼火","definition_en":"to make a bad situation, illness or feeling worse, or to annoy someone deliberately","core_image":"本已裂开的木梁上又压了一袋沙，裂缝沿着纹理继续向下走","scene":"伤员本该静养，他却提前下地干活，伤口又裂开了。Skipping the follow-up visit may aggravate the injury.","sceneCN":"这里指让本已受伤的身体状况变得更糟（第 1 个义项：使病情或伤势加重）；句意为不做复诊可能让伤势加重。图中可辨识物件：绷带、裂缝的木梁、压在梁上的沙袋。","pos":[{"tag":"v.","zh":"加重；使恶化；激怒"}],"collocations":[{"phrase":"aggravate a problem","zh":"使问题恶化"},{"phrase":"aggravate the injury","zh":"使伤势加重"},{"phrase":"aggravate a condition","zh":"使病情加重"},{"phrase":"aggravate tensions","zh":"加剧紧张局势"},{"phrase":"aggravate the burden","zh":"加重负担"},{"phrase":"aggravating circumstances","zh":"加重情节"},{"phrase":"be aggravated by","zh":"因……而加重"}],"forms":[{"label":"动词原形","form":"aggravate"},{"label":"第三人称单数","form":"aggravates"},{"label":"过去式","form":"aggravated"},{"label":"过去分词","form":"aggravated"},{"label":"现在分词","form":"aggravating"},{"label":"名词","form":"aggravation"}],"derivatives":[{"word":"aggravation","pos":"n.","zh":"由该动词加表示动作结果的名词尾构成，义为「加重；恶化；恼怒」"},{"word":"aggravating","pos":"adj.","zh":"由该动词加形容词后缀构成，义为「使人心烦的；加重的」"},{"word":"aggravated","pos":"adj.","zh":"由该动词加已然词尾构成，义为「加重的；被激怒的」，法律中指加重情节"},{"word":"aggravatingly","pos":"adv.","zh":"由形容词加副词词尾构成，义为「令人恼火地」"},{"word":"aggravated damages","pos":"n.","zh":"法律用语，指因情节恶劣而加重的赔偿"}],"senses":[{"no":"01","title":"To make an illness worse","titleCN":"使病情或伤势加重","definition":"to make a disease or injury more serious than it already is","definitionCN":"让疾病或伤势比原来更严重","example":"Walking on the sprained ankle aggravated the swelling.","exampleCN":"带着扭伤的脚踝走路，使肿胀更严重了。","why":"The Latin word meant to make heavier, and an illness is pictured as a weight already pressing on the body.","whyCN":"拉丁词本义是「使更重」，疾病被想象成本已压在身体上的一份重量。"},{"no":"02","title":"To worsen a problem","titleCN":"使问题恶化","definition":"to make an existing difficulty larger or harder to solve","definitionCN":"让已经存在的困难变大或更难解决","example":"Cutting the budget would aggravate the housing shortage.","exampleCN":"削减预算会让住房短缺更加严重。","why":"A problem is a load, so adding to it is literally adding weight to the same beam.","whyCN":"问题就是负荷，往上加就是给同一根梁再加重量。"},{"no":"03","title":"To add to a burden","titleCN":"加重负担","definition":"to increase the cost, effort or strain that someone must carry","definitionCN":"增加某人必须承担的成本、工作量或压力","example":"The new reporting rule aggravated the workload of small clinics.","exampleCN":"新的申报规定加重了小诊所的工作量。","why":"Here the metaphor is at its plainest: a burden grows heavier, and the verb says so directly.","whyCN":"这里的比喻最直白：负担变重了，这个动词就字面地这么说。"},{"no":"04","title":"To annoy someone","titleCN":"激怒；使恼火","definition":"to irritate a person, especially by repeated or deliberate behaviour","definitionCN":"尤指以反复或故意的行为惹恼某人","example":"He aggravated the guard by asking the same question four times.","exampleCN":"他同一个问题问了四遍，把门卫惹恼了。","why":"The modern colloquial sense treats irritation as a weight on the mind; most usage guides still keep it informal.","whyCN":"现代口语义把恼怒当作压在心头的一份重量；多数用法指南仍视其为非正式说法。"},{"no":"05","title":"To intensify a conflict","titleCN":"加剧冲突或紧张","definition":"to make a dispute or tension sharper and more likely to break out","definitionCN":"使争端或紧张关系更尖锐、更易爆发","example":"The patrols only aggravated the tension along the border.","exampleCN":"巡逻反而加剧了边境的紧张。","why":"Conflict is a pressure that rises, and the verb supplies the increase.","whyCN":"冲突是一种上升的压力，这个词提供了那股增量。"},{"no":"06","title":"To make an offence more serious","titleCN":"使罪行或过失更重","definition":"to add circumstances that make a legal offence more serious and punishable","definitionCN":"增加情节，使一项违法行为更严重、更应受罚","example":"Concealing the record aggravated the original offence.","exampleCN":"隐瞒记录使原本的违法行为更重。","why":"Law adopted the physical sense literally: certain facts add weight to the charge.","whyCN":"法律直接把物理义搬来：某些事实给罪名加上了重量。"},{"no":"07","title":"To make a bad outcome worse","titleCN":"使不利结果雪上加霜","definition":"to make an already damaging result more damaging","definitionCN":"让本已有害的结果变得更有害","example":"The delay aggravated the losses for every supplier involved.","exampleCN":"延误让每个相关供应商的损失都更重。","why":"Losses accumulate like weight, and aggravate marks the moment more is added.","whyCN":"损失像重量一样累积，这个词标出又添上去的那一刻。"},{"no":"08","title":"To sour a relationship","titleCN":"使关系恶化","definition":"to make relations between people or groups more hostile","definitionCN":"使人际或群体之间的关系更敌对","example":"The public argument aggravated relations between the two departments.","exampleCN":"这场公开争吵使两个部门的关系更僵。","why":"Relations are a structure under strain, and the verb names the extra load that cracks it.","whyCN":"关系是受力中的结构，这个词指那份额外负荷把它压裂。"}],"etymology":{"intro":{"en":"Aggravate comes from Latin aggravare, to make heavier, from ad, toward, and gravis, heavy. French brought it to English, where the medical and the irritating senses both grew from that weight.","cn":"这个词来自拉丁语 aggravare「使更重」，由 ad「向」与 gravis「重」构成；经法语进入英语，医学义与「惹恼」义都从这份重量长出。"},"items":[{"era":"LATIN GRAVIS","en":"Gravis meant heavy in body and serious in consequence, and it is the source of grave, gravity and grief as well.","cn":"这个词既指身体上的重，也指后果严重；表示「严重的」「重力」「悲伤」的词也出自它。"},{"era":"LATIN AD-","en":"The prefix ad- meant toward, and before a g it assimilated into ag-, the form seen in aggravare.","cn":"前缀 ad- 意为「向」，在 g 前同化成 ag-，即 aggravare 中的形式。"},{"era":"LATIN AGGRAVARE","en":"The verb meant to add weight to something, and it was used of burdens, taxes, illness and wrongdoing.","cn":"这个动词指给某物加重，用于负担、税负、疾病与过错。"},{"era":"OLD FRENCH AGGRAVER","en":"Old French carried the verb into English with the sense of making a condition worse.","cn":"古法语把这个动词带进英语，义为让状况变坏。"},{"era":"ENGLISH, 16TH CENTURY","en":"English records the verb from the sixteenth century; the exact first date is uncertain and is usually given only as that century.","cn":"英语自十六世纪有记录；确切首见年代不确定，通常只给「十六世纪」。"},{"era":"THE COLLOQUIAL TURN","en":"The sense to annoy is nineteenth-century informal usage; it is not the original meaning, though it is now very common.","cn":"「惹恼」是十九世纪的非正式用法，并非本义，但今天已十分常见。"}]},"similar":{"note":{"en":"The first group shares the heavy root or looks close; the second group names nearby ideas of worsening and irritation.","cn":"第一组与「aggravate」共享「重」的词根或只是形近；第二组是与「恶化、激怒」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"aggravation","ipa":"/ˌæɡrəˈveɪʃn/","tag":"same root","definition":"The noun for the act of worsening and, informally, for annoyance.","definitionCN":"指加重这一行为，口语中也指恼人的事。"},{"word":"aggravating","ipa":"/ˈæɡrəveɪtɪŋ/","tag":"same root","definition":"The adjective for something that makes a situation worse or irritates.","definitionCN":"形容词，指使情况变坏或令人恼火的。"},{"word":"gravity","ipa":"/ˈɡrævəti/","tag":"same root","definition":"The noun from gravis, naming weight and seriousness.","definitionCN":"出自「重」的名词，指重力与严重性。"},{"word":"grave","ipa":"/ɡreɪv/","tag":"same root","definition":"As an adjective it means serious; the same heavy root, a different branch.","definitionCN":"作形容词指严重的；同出「重」词根，属另一分支。"},{"word":"aggregate","ipa":"/ˈæɡrɪɡət/","tag":"different root","definition":"To collect into a whole, from grex, a flock; it looks close but is not the heavy root.","definitionCN":"指聚合成整体，出自「群」，形近但不是「重」词根。"}]},{"heading":"NEAR MEANING","entries":[{"word":"worsen","ipa":"/ˈwɜːsn/","tag":"near meaning","definition":"To become or make worse, the plainest verb of the group.","definitionCN":"指变坏或使变坏，是本组最朴素的动词。"},{"word":"exacerbate","ipa":"/ɪɡˈzæsəbeɪt/","tag":"near meaning","definition":"To make a problem or feeling more intense, often used in formal writing.","definitionCN":"指使问题或情绪更强烈，多用于正式文体。"},{"word":"intensify","ipa":"/ɪnˈtensɪfaɪ/","tag":"near meaning","definition":"To increase strength or force, not necessarily in a bad direction.","definitionCN":"指加强力度，不一定朝坏的方向。"},{"word":"compound","ipa":"/kəmˈpaʊnd/","tag":"near meaning","definition":"To make a problem harder by adding another difficulty.","definitionCN":"指再添一层困难而使问题更难。"},{"word":"irritate","ipa":"/ˈɪrɪteɪt/","tag":"near meaning","definition":"To annoy or provoke mildly, the colloquial core of aggravate.","definitionCN":"指轻度惹恼，正是本词口语义的核心。"},{"word":"provoke","ipa":"/prəˈvəʊk/","tag":"near meaning","definition":"To stir someone into anger or into a reaction.","definitionCN":"指激怒某人或引出反应。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the heavy root, the medical and legal phrases, and the split between worsen and annoy.","cn":"正常联想使用「重」的词根、医学与法律搭配，以及「恶化」与「惹恼」的分裂。"},"normal":[{"en":"Gravis is heavy, so aggravate is literally to add weight to something already sinking.","cn":"gravis 是「重」，所以这个词字面就是给已经下沉的东西再加重量。"},{"en":"Gravity, grave and grief belong to the same heavy family.","cn":"gravity、grave、grief 同属「重」这一族。"},{"en":"Doctors say a movement or an infection aggravates a condition.","cn":"医生会说某个动作或感染使病情加重。"},{"en":"Law uses aggravating circumstances for facts that make an offence worse.","cn":"法律用「加重情节」指使罪行更重的事实。"},{"en":"The sense to annoy is informal; formal writing prefers worsen or irritate.","cn":"「惹恼」义属非正式，正式写作多用「使恶化」或「惹恼」这类说法。"}],"abstract":[{"en":"Aggravate is never neutral: it always adds to something already bad.","cn":"这个词从不中性：它总是往已经不好的东西上再加一层。"},{"en":"A small weight placed at the right point can break a beam that held for years.","cn":"在正确的位置加一点重量，就能压断撑了多年的梁。"},{"en":"Irritation is aggravation moved from the beam to the mind.","cn":"恼怒不过是从梁上挪到心上的加重。"}]},"examples":[{"en":"Running too soon aggravated the ligament injury.","cn":"过早跑步使韧带伤更重了。"},{"en":"The delay aggravated the shortage of parts across the plant.","cn":"延误加剧了全厂的零件短缺。"},{"en":"Constant reminders aggravated rather than helped the new worker.","cn":"反复提醒不但没帮上新工人，反而让他更烦躁。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「阿格瑞维特」——梁上再压一袋沙，裂缝更深：加重、激怒","word":"aggravate"},"root":"拉丁语 gravis「重」→ aggravare「使更重」（ad-「向」+ gravare「加重」）→ 古法语 aggraver；英语十六世纪引入，首见年代不确定。","sensesIntro":{"en":"Eight senses carry the image of added weight through illness, problems, burdens, temper, conflict, law, losses and relationships.","cn":"八个义项把「再加一份重量」的画面贯穿病情、问题、负担、脾气、冲突、法律、损失与关系。"},"semanticMap":{"core":{"en":"CORE IMAGE: sand is piled onto a beam that has already begun to crack, and the crack runs deeper.","cn":"核心意象：沙袋被压上已经开裂的梁，裂缝随之更深。"},"chain":["WEIGHT","ILLNESS","PROBLEM","BURDEN","ANGER","CONFLICT"],"branches":[{"senses":"01","en":"THE BODY UNDER LOAD: an illness or injury is made heavier by what is done to it.","cn":"身体承重：疾病或伤势被加诸其上的行为压得更重。"},{"senses":"02 · 07","en":"THE FAILING STRUCTURE: a problem or a loss receives an extra share of weight.","cn":"失效的结构：问题或损失又分到额外的一份重量。"},{"senses":"03","en":"THE CARRYING PERSON: cost and effort grow heavier on whoever must bear them.","cn":"负重的人：成本与工作量压在承担者身上，越来越重。"},{"senses":"04","en":"THE MIND PRESSED: repeated behaviour puts weight on someone's temper.","cn":"被压的心：反复的行为把重量压到人的脾气上。"},{"senses":"05 · 06 · 08","en":"THE SHARPENED EDGE: tension, a legal charge or a relationship becomes more dangerous under the added load.","cn":"磨尖的刃：紧张、罪名或关系在额外负荷下更危险。"}]},"affixes":{"intro":{"en":"Aggravate is a Latin verb built from a prefix and a heavy root, and the same pieces recur across English.","cn":"这是一个由前缀与「重」词根构成的拉丁动词，同一批部件在英语里反复出现。"},"latinIntro":{"en":"Latin supplies gravis, gravare and aggravare; the family is well recorded, so only the deeper origin is a reconstruction.","cn":"拉丁语提供了 gravis、gravare、aggravare；这一族有清楚记录，只有更早的来源属重构。"},"items":[{"word":"gravis","structure":"Latin adjective","meaning":"heavy; serious","meaningCN":"重的；严重的","example":"The adjective covered both weight and consequence.","exampleCN":"这个形容词兼指重量与后果。"},{"word":"gravare","structure":"Latin verb from gravis","meaning":"to weigh down; to burden","meaningCN":"压重；使负担","example":"The verb named the act of adding weight.","exampleCN":"这个动词指加重这一动作。"},{"word":"ag-","structure":"assimilated form of ad-","meaning":"toward; added to","meaningCN":"向；加于","example":"The prefix marks weight added to something.","exampleCN":"前缀标出加在某物上的重量。"},{"word":"aggravare","structure":"Latin verb","meaning":"to make heavier, worsen","meaningCN":"使更重；使恶化","example":"The verb combined the prefix and the root.","exampleCN":"这个动词把前缀与词根合在一起。"},{"word":"gravitas","structure":"Latin noun","meaning":"weight; seriousness","meaningCN":"重量；庄重","example":"The noun gave English gravity.","exampleCN":"这个名词给出了英语的 gravity。"},{"word":"-ate","structure":"Latin verb ending","meaning":"to make or cause","meaningCN":"使……；做……","example":"It marks the English verb of action.","exampleCN":"它标明英语的动作动词。"},{"word":"-ion","structure":"action-result noun ending","meaning":"the act or result","meaningCN":"动作或结果","example":"It forms aggravation.","exampleCN":"它构成 aggravation。"},{"word":"-ing","structure":"adjective ending","meaning":"causing the quality","meaningCN":"致使……的","example":"It forms aggravating.","exampleCN":"它构成 aggravating。"},{"word":"-ly","structure":"adverb ending","meaning":"in a given manner","meaningCN":"以……方式","example":"It forms aggravatingly.","exampleCN":"它构成 aggravatingly。"}],"latinEntries":[{"word":"gravis","structure":"Latin adjective","meaning":"heavy, serious","meaningCN":"重的；严重的"},{"word":"gravare","structure":"Latin verb","meaning":"to weigh down","meaningCN":"压重；使负担"},{"word":"aggravare","structure":"Latin verb","meaning":"to make heavier","meaningCN":"使更重"},{"word":"gravitas","structure":"Latin noun","meaning":"weight, seriousness","meaningCN":"重量；庄重"}],"derivatives":[{"word":"aggravation","pos":"n.","zh":"由该动词加表示动作结果的名词尾构成，义为「加重；恶化；恼怒」"},{"word":"aggravating","pos":"adj.","zh":"由该动词加形容词后缀构成，义为「使人心烦的；加重的」"},{"word":"aggravated","pos":"adj.","zh":"由该动词加已然词尾构成，义为「加重的；被激怒的」"},{"word":"aggravatingly","pos":"adv.","zh":"由形容词加副词词尾构成，义为「令人恼火地」"},{"word":"gravity","pos":"n.","zh":"由同一拉丁词干「重」加名词尾构成，义为「重力；严重性」"}]}},{"word":"alleviate","ipa_uk":"/əˈliːvieɪt/","ipa_us":"/əˈliːvieɪt/","definition_zh":"减轻；缓解；缓和；使缓和","definition_en":"to make pain, difficulty or a bad feeling less severe without removing its cause","core_image":"压在人肩上的石袋被一只只手卸下一半，肩线慢慢回正","scene":"换药时最疼，护士引导病人慢慢呼吸，疼痛就退了一些。The clinic uses guided breathing to alleviate pain during dressing changes.","sceneCN":"这里指让疼痛变轻（第 1 个义项：减轻疼痛或症状）；句意为诊所靠引导呼吸来缓解换药时的疼痛。图中可辨识物件：病床、绷带、被卸下一半的石袋。","pos":[{"tag":"v.","zh":"减轻；缓解；缓和"}],"collocations":[{"phrase":"alleviate pain","zh":"减轻疼痛"},{"phrase":"alleviate stress","zh":"缓解压力"},{"phrase":"alleviate poverty","zh":"缓解贫困"},{"phrase":"alleviate pressure","zh":"减轻压力"},{"phrase":"alleviate congestion","zh":"缓解拥堵"},{"phrase":"alleviate symptoms","zh":"缓解症状"},{"phrase":"alleviate the burden","zh":"减轻负担"}],"forms":[{"label":"动词原形","form":"alleviate"},{"label":"第三人称单数","form":"alleviates"},{"label":"过去式","form":"alleviated"},{"label":"过去分词","form":"alleviated"},{"label":"现在分词","form":"alleviating"},{"label":"名词","form":"alleviation"}],"derivatives":[{"word":"alleviation","pos":"n.","zh":"由该动词加表示动作结果的名词尾构成，义为「减轻；缓解」"},{"word":"alleviating","pos":"adj.","zh":"由该动词加形容词后缀构成，义为「缓解性的」"},{"word":"alleviative","pos":"adj./n.","zh":"由该动词加表示倾向的形容词尾构成，义为「缓解的；缓和剂」"},{"word":"alleviator","pos":"n.","zh":"由该动词加表示施动者的名词尾构成，义为「缓解者；缓解手段」"},{"word":"alleviated","pos":"adj.","zh":"由该动词加已然词尾构成，义为「已减轻的」"}],"senses":[{"no":"01","title":"To ease pain","titleCN":"减轻疼痛","definition":"to reduce the intensity of physical pain without curing its cause","definitionCN":"降低身体疼痛的强度，但不消除病因","example":"The drug alleviates pain but does not repair the joint.","exampleCN":"这种药能减轻疼痛，却修不好关节。","why":"Alleviate comes from a word for light, and pain is treated as a weight that can be made lighter.","whyCN":"这个词出自「轻」义，疼痛被当作一份可以变轻的重量。"},{"no":"02","title":"To ease pressure or strain","titleCN":"缓解压力或紧张","definition":"to reduce the level of stress, workload or tension that people or systems carry","definitionCN":"降低人或系统所承受的压力、工作量或紧张程度","example":"Extra staff alleviated the pressure on the night shift.","exampleCN":"增加人手缓解了夜班的压力。","why":"Pressure is a load, so making it lighter is the same physical move applied to work.","whyCN":"压力是负荷，让它变轻就是把同一物理动作用到工作上。"},{"no":"03","title":"To reduce poverty or hardship","titleCN":"缓解贫困与困苦","definition":"to lessen the severity of material hardship, usually by policy rather than by cure","definitionCN":"减轻物质困苦的严重程度，通常靠政策而非根治","example":"The subsidy alleviated hardship among the poorest households.","exampleCN":"这项补贴缓解了最贫困家庭的困苦。","why":"Social policy speaks of lightening a burden that cannot yet be removed.","whyCN":"社会政策谈的是先把卸不掉的负担弄轻。"},{"no":"04","title":"To relieve congestion","titleCN":"缓解拥堵","definition":"to make traffic, queues or demand less dense","definitionCN":"使交通、排队或需求不再那么密集","example":"A second entrance alleviated congestion at the main gate.","exampleCN":"增加第二个入口缓解了正门的拥堵。","why":"Congestion is pressure concentrated at one point, and the verb spreads or lowers it.","whyCN":"拥堵是集中在一处的压力，这个动词把它摊开或降低。"},{"no":"05","title":"To soothe anxiety","titleCN":"缓解焦虑","definition":"to make fear or worry less intense, often temporarily","definitionCN":"使恐惧或担忧不那么强烈，常常只是暂时","example":"A clear explanation alleviated her anxiety about the results.","exampleCN":"清楚的解释缓解了她对结果的焦虑。","why":"Emotional weight is lightened much as physical weight is, which is why the same verb serves both.","whyCN":"情绪的重量与身体的重量一样可以被减轻，所以同一个动词两者都管。"},{"no":"06","title":"To soften an impact","titleCN":"缓和冲击或影响","definition":"to reduce how hard an event, change or policy hits those affected","definitionCN":"降低某个事件、变化或政策对受影响者的打击力度","example":"The fund alleviated the impact of the sudden price rise.","exampleCN":"这笔基金缓和了价格骤涨带来的冲击。","why":"An impact lands as force, and lightening it is to take part of the blow away.","whyCN":"冲击以力量的形式落下，减轻它就是卸掉一部分打击。"},{"no":"07","title":"To provide relief measures","titleCN":"提供缓解性措施","definition":"to supply practical help that makes a difficult situation easier to bear","definitionCN":"提供实际帮助，使困难处境更容易承受","example":"The city alleviated the water shortage with temporary deliveries.","exampleCN":"市里用临时送水缓解了缺水。","why":"Here the verb shifts from the feeling to the measure that produces the feeling.","whyCN":"这里动词从「感受」转向「产生该感受的措施」。"},{"no":"08","title":"To treat symptoms only","titleCN":"只对症缓解","definition":"to give symptomatic relief while leaving the underlying condition untreated","definitionCN":"只提供症状层面的缓解，不处理根本病因","example":"Hospice care alleviated her symptoms without treating the disease itself.","exampleCN":"临终照护缓解了她的症状，却没有治疗疾病本身。","why":"Medicine distinguishes cure from relief, and alleviate belongs firmly to the second.","whyCN":"医学区分「治愈」与「缓解」，这个词稳稳属于后者。"}],"etymology":{"intro":{"en":"Alleviate comes from Latin alleviare, to lighten, from ad, toward, and levare, to raise or lighten, from levis, light in weight. It is not related to the Latin verb for raising or nourishing.","cn":"这个词来自拉丁语 alleviare「使轻」，由 ad「向」与 levare「举起、减轻」构成，而 levare 出自 levis「轻」；它与拉丁语中表示「举起、养育」的另一个动词无关。"},"items":[{"era":"LATIN LEVIS","en":"Levis meant light in weight, and the same root gives levity, elevate and relief through related verbs.","cn":"这个词指重量轻；同一词根经相关动词还给出「轻快」「举起」与「缓解」等词。"},{"era":"LATIN LEVARE","en":"Levare meant to lighten or to raise, and the two readings share the picture of something becoming easier to lift.","cn":"这个词意为使轻或举起，两种读法共享「东西变得容易举起」的画面。"},{"era":"LATIN AD-","en":"The prefix ad- meant toward, and it marks the direction in which the lightening is applied.","cn":"前缀 ad- 意为「向」，标出减轻作用的方向。"},{"era":"LATIN ALLEVIARE","en":"Alleviare meant to lighten, relieve or comfort, and it was used of pain, grief and burdens.","cn":"这个词意为使轻、缓解、安慰，用于疼痛、悲伤与负担。"},{"era":"LATIN CONFUSION","en":"It is often confused with allevare, to raise or feed, but the two verbs differ in root and meaning.","cn":"它常与表示「举起、喂养」的 allevare 混淆，但两者词根与词义都不同。"},{"era":"ENGLISH, 16TH CENTURY","en":"English took the verb directly from Latin in the sixteenth century; the exact first date is uncertain.","cn":"英语十六世纪直接从拉丁语引入这个动词，确切首见年代不确定。"}]},"similar":{"note":{"en":"The first group shares the light root or looks close; the second group names neighbouring ideas of relief and reduction.","cn":"第一组与「alleviate」共享「轻」的词根或只是形近；第二组是与「缓解、减少」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"alleviation","ipa":"/əˌliːviˈeɪʃn/","tag":"same root","definition":"The noun for the act of making something less severe.","definitionCN":"指减轻、缓解这一行为的名词。"},{"word":"alleviating","ipa":"/əˈliːvieɪtɪŋ/","tag":"same root","definition":"The adjective for something that relieves.","definitionCN":"形容词，指起缓解作用的。"},{"word":"elevate","ipa":"/ˈelɪveɪt/","tag":"same root","definition":"To raise something, from the same light root through a different prefix path.","definitionCN":"指举起、抬高；同出「轻」词根，经不同前缀路径。"},{"word":"levity","ipa":"/ˈlevəti/","tag":"same root","definition":"Lightness of mood, literally lightness of weight.","definitionCN":"指情绪轻快，字面就是「重量轻」。"},{"word":"relief","ipa":"/rɪˈliːf/","tag":"same root","definition":"The noun for easing a burden, from a related Latin verb.","definitionCN":"指负担的减轻，出自相关的拉丁动词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"relieve","ipa":"/rɪˈliːv/","tag":"near meaning","definition":"To take a burden or pain away, often more completely than alleviate.","definitionCN":"指卸去负担或疼痛，程度常比 alleviate 更彻底。"},{"word":"ease","ipa":"/iːz/","tag":"near meaning","definition":"To make something less painful or difficult, in plain everyday language.","definitionCN":"指使不那么痛苦或困难，是日常说法。"},{"word":"mitigate","ipa":"/ˈmɪtɪɡeɪt/","tag":"near meaning","definition":"To make something bad less severe, especially damage or risk.","definitionCN":"指使坏事不那么严重，尤指损害或风险。"},{"word":"soothe","ipa":"/suːð/","tag":"near meaning","definition":"To calm a feeling or a surface, with a comforting tone.","definitionCN":"指安抚情绪或舒缓表面，带安慰色彩。"},{"word":"lessen","ipa":"/ˈlesn/","tag":"near meaning","definition":"To make or become smaller in amount.","definitionCN":"指在数量上减少。"},{"word":"reduce","ipa":"/rɪˈdjuːs/","tag":"near meaning","definition":"To bring down a size, amount or level, the broad neutral verb.","definitionCN":"指降低大小、数量或水平，是宽泛中性的说法。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the light root, the false twin allevare, and the medical phrases that keep the word in use.","cn":"正常联想使用「轻」的词根、容易混淆的近形动词 allevare，以及让这个词保持活力的医学搭配。"},"normal":[{"en":"Levis is light, so alleviate is to put something on a scale and watch the reading drop.","cn":"levis 是「轻」，所以这个词就是把东西放上秤，看读数往下走。"},{"en":"Elevate and alleviate look alike and are related, but one raises and the other lightens.","cn":"elevate 与 alleviate 形近且同源，但一个往上举，一个往轻里减。"},{"en":"Do not confuse it with allevare, which meant to raise or feed.","cn":"不要与 allevare 混淆，那个词是「举起、喂养」。"},{"en":"Clinics alleviate pain, cities alleviate congestion, and policy alleviates poverty.","cn":"诊所缓解疼痛，城市缓解拥堵，政策缓解贫困。"},{"en":"Alleviate treats the symptom; cure treats the cause.","cn":"这个词处理症状，「治愈」处理病因。"}],"abstract":[{"en":"To alleviate is to admit you cannot remove the weight, and still take some of it off.","cn":"减轻，就是承认重量卸不掉，却仍然拿走一部分。"},{"en":"Relief is not cure: the stone is lighter, but it is still on the shoulder.","cn":"缓解不是治愈：石头变轻了，可还在肩上。"},{"en":"Every soothing act is a small redistribution of weight from the weak to the strong.","cn":"每一次安抚，都是把重量从弱者身上往强者身上挪一点。"}]},"examples":[{"en":"Cool compresses alleviate the itching for about an hour.","cn":"冷敷能缓解瘙痒大约一小时。"},{"en":"The new lane alleviated congestion on the western approach.","cn":"新车道缓解了西侧入口的拥堵。"},{"en":"Cash transfers alleviated hardship but did not end it.","cn":"现金补助缓解了困苦，却没有终结它。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「阿利维特」——肩上的石袋被卸下一半：减轻、缓解","word":"alleviate"},"root":"拉丁语 levis「轻」→ levare「使轻、举起」→ alleviare「使轻、缓解」（ad-「向」）；英语十六世纪直接引入。与表示「举起、养育」的 allevare 无关。","sensesIntro":{"en":"Eight senses all lighten something: pain, pressure, poverty, congestion, anxiety, impact, shortage and symptoms.","cn":"八个义项都在给某物减重：疼痛、压力、贫困、拥堵、焦虑、冲击、短缺与症状。"},"semanticMap":{"core":{"en":"CORE IMAGE: half the stones are lifted off a shoulder, and the shoulder slowly straightens.","cn":"核心意象：肩上的石袋被卸下一半，肩线慢慢回正。"},"chain":["LIGHT","PAIN","PRESSURE","HARDSHIP","EMOTION","IMPACT"],"branches":[{"senses":"01 · 08","en":"THE BODY IS LIGHTENED: pain or a symptom loses intensity, though the cause may remain.","cn":"身体变轻：疼痛或症状减弱，病因却可能还在。"},{"senses":"02","en":"THE LOAD IS SHARED: stress and workload are lowered for those carrying them.","cn":"负荷被分担：承受者的压力与工作量降下来。"},{"senses":"03 · 05","en":"THE INWARD WEIGHT: hardship and anxiety become easier to bear.","cn":"内心的重量：困苦与焦虑变得较易承受。"},{"senses":"04","en":"THE CROWD IS SPREAD: congestion loses its concentration at one point.","cn":"人群被摊开：拥堵失去那一点上的集中。"},{"senses":"06 · 07","en":"THE BLOW IS SOFTENED: an impact or a shortage meets a measure that takes part of its force.","cn":"打击被软化：冲击或短缺遇上一项卸去部分力度的措施。"}]},"affixes":{"intro":{"en":"Alleviate is a Latin verb built from a light root, and the same root runs through elevate, levity and relief.","cn":"这是一个由「轻」词根构成的拉丁动词，同一词根贯穿 elevate、levity 与 relief。"},"latinIntro":{"en":"Latin supplies levis, levare and alleviare; the deeper origin of the root is reconstructed rather than recorded.","cn":"拉丁语提供了 levis、levare、alleviare；词根更早的来源属重构而非有记录的形式。"},"items":[{"word":"levis","structure":"Latin adjective","meaning":"light in weight","meaningCN":"重量轻的","example":"The adjective named what is easy to carry.","exampleCN":"这个形容词指容易携带的东西。"},{"word":"levare","structure":"Latin verb from levis","meaning":"to lighten; to raise","meaningCN":"使轻；举起","example":"The two readings meet in the idea of making something easier to lift.","exampleCN":"两种读法在「让东西更容易举起」处汇合。"},{"word":"ad-","structure":"Latin prefix","meaning":"toward; added to","meaningCN":"向；加于","example":"Before l it assimilates to al-, as in alleviate.","exampleCN":"在 l 前同化为 al-，即 alleviate 的形式。"},{"word":"alleviare","structure":"Latin verb","meaning":"to lighten, relieve","meaningCN":"使轻；缓解","example":"The verb was used of pain and grief.","exampleCN":"这个动词用于疼痛与悲伤。"},{"word":"-ate","structure":"Latin verb ending","meaning":"to make or cause","meaningCN":"使……；做……","example":"It marks the English verb.","exampleCN":"它标明英语动词。"},{"word":"-ion","structure":"action-result noun ending","meaning":"the act or result","meaningCN":"动作或结果","example":"It forms alleviation.","exampleCN":"它构成 alleviation。"},{"word":"-ive","structure":"adjective ending","meaning":"having the quality of","meaningCN":"有……性质的","example":"It forms alleviative.","exampleCN":"它构成 alleviative。"},{"word":"-or","structure":"agent noun ending","meaning":"the one who acts","meaningCN":"施动者","example":"It forms alleviator.","exampleCN":"它构成 alleviator。"},{"word":"levity","structure":"Latin-derived noun","meaning":"lightness of mood","meaningCN":"情绪轻快","example":"The same root, moved from weight to temperament.","exampleCN":"同一词根，从重量移到性情。"}],"latinEntries":[{"word":"levis","structure":"Latin adjective","meaning":"light in weight","meaningCN":"重量轻的"},{"word":"levare","structure":"Latin verb","meaning":"to lighten, raise","meaningCN":"使轻；举起"},{"word":"alleviare","structure":"Latin verb","meaning":"to lighten, relieve","meaningCN":"使轻；缓解"},{"word":"levitas","structure":"Latin noun","meaning":"lightness","meaningCN":"轻"}],"derivatives":[{"word":"alleviation","pos":"n.","zh":"由该动词加表示动作结果的名词尾构成，义为「减轻；缓解」"},{"word":"alleviating","pos":"adj.","zh":"由该动词加形容词后缀构成，义为「缓解性的」"},{"word":"alleviative","pos":"adj./n.","zh":"由该动词加表示倾向的形容词尾构成，义为「缓解的；缓和剂」"},{"word":"alleviator","pos":"n.","zh":"由该动词加表示施动者的名词尾构成，义为「缓解者」"},{"word":"elevate","pos":"v.","zh":"由同一「轻」词根加表示「向外」的前缀构成，义为「举起；提升」"}]}},{"word":"circumvent","ipa_uk":"/ˌsɜːkəmˈvent/","ipa_us":"/ˌsɜːrkəmˈvent/","definition_zh":"绕过；规避；回避；设法避开","definition_en":"to go around a place, rule or difficulty instead of facing it directly","core_image":"一道封锁线横在路口，车队拐进旁边的小路，从侧面绕过了检查点","scene":"出口禁令下来后，这家公司把货先运到第三个国家再转运。The firm routed its shipments through a third country to circumvent the export ban.","sceneCN":"这里指绕开一条法规的限制（第 2 个义项：规避法律或规则）；句意为这家公司借第三国转运来规避出口禁令。图中可辨识物件：封锁线、岔出的小路、绕行的货车。","pos":[{"tag":"v.","zh":"绕过；规避；回避"}],"collocations":[{"phrase":"circumvent the law","zh":"规避法律"},{"phrase":"circumvent restrictions","zh":"绕开限制"},{"phrase":"circumvent sanctions","zh":"规避制裁"},{"phrase":"circumvent the system","zh":"绕过系统"},{"phrase":"circumvent a problem","zh":"回避问题"},{"phrase":"circumvent security","zh":"绕过安全防护"}],"forms":[{"label":"动词原形","form":"circumvent"},{"label":"第三人称单数","form":"circumvents"},{"label":"过去式","form":"circumvented"},{"label":"过去分词","form":"circumvented"},{"label":"现在分词","form":"circumventing"},{"label":"名词","form":"circumvention"}],"derivatives":[{"word":"circumvention","pos":"n.","zh":"由该动词加表示动作结果的名词尾构成，义为「规避；绕行」"},{"word":"circumvented","pos":"adj.","zh":"由该动词加已然词尾构成，义为「被绕过的；被规避的」"},{"word":"circumventing","pos":"adj.","zh":"由该动词加形容词后缀构成，义为「规避性的」"},{"word":"circumventive","pos":"adj.","zh":"由该动词加表示倾向的形容词尾构成，义为「倾向于规避的」（少用）"},{"word":"circumventer","pos":"n.","zh":"由该动词加表示施动者的名词尾构成，义为「规避者」（少用）"}],"senses":[{"no":"01","title":"To go around a place","titleCN":"绕行某地","definition":"to travel around a town, barrier or defended area rather than through it","definitionCN":"不走某座城镇、障碍或防区的正面，而是从外围过去","example":"The convoy circumvented the flooded valley by the eastern road.","exampleCN":"车队走东边的路绕过了被淹的河谷。","why":"The Latin verb meant to come around, and the physical circle around a place is the oldest sense.","whyCN":"拉丁动词本义是「绕到周围」，绕着地方走一圈是最古老的义项。"},{"no":"02","title":"To evade a rule","titleCN":"规避法规","definition":"to avoid the effect of a law or regulation by using a route it did not cover","definitionCN":"利用法规没有覆盖的路径，避开它的效力","example":"Some importers circumvent the quota by splitting the shipment.","exampleCN":"一些进口商把货拆单，以规避配额。","why":"A rule draws a line; going around it is the same geometry applied to law.","whyCN":"规则画了一条线，绕过去就是把同一几何关系用到法律上。"},{"no":"03","title":"To sidestep a difficulty","titleCN":"回避困难","definition":"to avoid dealing with a hard question or obstacle directly","definitionCN":"不正面处理难题或障碍","example":"The report circumvented the central question of cost.","exampleCN":"报告绕开了成本这个核心问题。","why":"A difficulty stands in the road, and the verb chooses the path that leaves it untouched.","whyCN":"困难立在路中，这个动词选了那条不去碰它的路。"},{"no":"04","title":"To get around a control","titleCN":"绕过管控","definition":"to defeat a check, filter or supervisory mechanism without formally breaking it","definitionCN":"在不正式违反的前提下让核查、过滤或监管失效","example":"The app circumvented the parental lock with a hidden menu.","exampleCN":"这款应用用隐藏菜单绕过了家长锁。","why":"Control systems are walls with gates, and the word describes finding the part with no gate.","whyCN":"管控系统是有门的墙，这个词描述的是找到没有门的那一段。"},{"no":"05","title":"To avoid an opponent","titleCN":"避开对手","definition":"to avoid meeting an opposing force by moving around its position","definitionCN":"通过绕过对方的阵地而不与其正面交战","example":"The unit circumvented the patrol and reached the bridge.","exampleCN":"这支部队绕过巡逻队抵达桥头。","why":"Military usage keeps the spatial core: avoid the strong point, reach the objective.","whyCN":"军事用法保留空间内核：避开强点，抵达目标。"},{"no":"06","title":"To avoid a fee or tax","titleCN":"规避费用或税款","definition":"to arrange affairs so that a charge legally applies to someone else or not at all","definitionCN":"通过安排使某项收费依法落到别人头上或干脆不产生","example":"The trust was set up to circumvent the inheritance tax.","exampleCN":"这个信托就是为规避遗产税设立的。","why":"Money follows routes, and the word supplies the route that misses the toll booth.","whyCN":"钱走路线，这个词提供了那条错过收费亭的路线。"},{"no":"07","title":"To work around a problem","titleCN":"迂回解决","definition":"to reach a goal by an indirect method when the direct one is blocked","definitionCN":"在直接方法行不通时，用间接办法达到目的","example":"The engineers circumvented the faulty sensor with a manual override.","exampleCN":"工程师用手动接管绕过了失灵的传感器。","why":"This is the constructive side of the word: the obstacle stays, but it is no longer on the path.","whyCN":"这是这个词的建设性一面：障碍还在，只是不再挡在路上。"},{"no":"08","title":"To bypass a system limit","titleCN":"绕过系统限制","definition":"to get past a technical restriction, lock or limit without disabling it","definitionCN":"在不关掉技术限制的情况下越过它","example":"A crafted request circumvents the rate limit on the server.","exampleCN":"一个构造的请求绕过了服务器上的速率限制。","why":"Digital systems reproduce walls and gates, so the old verb fits them exactly.","whyCN":"数字系统复制了墙与门，这个古老的动词正好合身。"}],"etymology":{"intro":{"en":"Circumvent comes from Latin circumvenire, to come around or surround, from circum, around, and venire, to come. English extended the physical circle to rules and controls.","cn":"这个词来自拉丁语 circumvenire「绕到周围、包围」，由 circum「周围」与 venire「来」构成；英语把这一圈从空间扩展到规则与管控。"},"items":[{"era":"LATIN CIRCUM","en":"Circum meant around on all sides, and it is the same element in circle, circuit and circumference.","cn":"这个词意为「四周环绕」，也是 circle、circuit、circumference 中的同一成分。"},{"era":"LATIN VENIRE","en":"Venire meant to come or go, and it supplies the second half of words such as intervene and prevent.","cn":"这个词意为「来、去」，提供 intervene、prevent 等词的后半部分。"},{"era":"LATIN CIRCUMVENIRE","en":"The compound meant to come around, to surround, and in military writing to encircle an enemy.","cn":"这个复合词意为「绕到周围、包围」，在军事文献中指包抄敌军。"},{"era":"THE DECEPTIVE SHADE","en":"Latin also used the verb for getting around a person by trickery, which prepared the English sense of evasion.","cn":"拉丁语也用这个动词指以手段绕开某人，这为英语的「规避」义做了准备。"},{"era":"ENGLISH, 15TH CENTURY","en":"English adopted the verb in the fifteenth century; the exact first date is uncertain and is usually given only as that century.","cn":"英语十五世纪采用这个动词，确切首见年代不确定，通常只给「十五世纪」。"},{"era":"MODERN LEGAL AND TECHNICAL USE","en":"Law and computing both needed a word for going around a barrier, and the old verb filled both roles.","cn":"法律与计算机都需要一个表示「绕过屏障」的词，这个古老动词同时补上了两个位置。"}]},"similar":{"note":{"en":"The first group shares the circum prefix or looks close; the second group names neighbouring ideas of avoidance and bypass.","cn":"第一组与「circumvent」共享 circum 前缀或只是形近；第二组是与「回避、绕过」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"circumvention","ipa":"/ˌsɜːkəmˈvenʃn/","tag":"same root","definition":"The noun for the act of going around a rule or barrier.","definitionCN":"指绕过规则或屏障这一行为的名词。"},{"word":"circumference","ipa":"/səˈkʌmfərəns/","tag":"same prefix","definition":"The distance around a circle; the prefix matches but the root is to carry.","definitionCN":"指圆周长度；前缀相同，但词根是「携带」。"},{"word":"circumstance","ipa":"/ˈsɜːkəmstəns/","tag":"same prefix","definition":"A condition around an event; the prefix matches but the root is to stand.","definitionCN":"指事件周围的条件；前缀相同，词根是「站立」。"},{"word":"circumspect","ipa":"/ˈsɜːkəmspəkt/","tag":"same prefix","definition":"Cautious, literally looking around; the prefix matches but the root is to look.","definitionCN":"指谨慎，字面是「环顾」；前缀相同，词根是「看」。"},{"word":"circuit","ipa":"/ˈsɜːkɪt/","tag":"different root","definition":"A closed path or a loop, related in meaning but formed on a different stem.","definitionCN":"指闭合路径或回路，意义相关但词干不同。"}]},{"heading":"NEAR MEANING","entries":[{"word":"bypass","ipa":"/ˈbaɪpɑːs/","tag":"near meaning","definition":"To go around a town or a rule, the plainest equivalent.","definitionCN":"指绕开城镇或规则，是最直白的对应说法。"},{"word":"evade","ipa":"/ɪˈveɪd/","tag":"near meaning","definition":"To escape something by cleverness, with a stronger note of avoidance of duty.","definitionCN":"指以巧计逃脱，更强调逃避责任。"},{"word":"avoid","ipa":"/əˈvɔɪd/","tag":"near meaning","definition":"To keep away from something, with no route image.","definitionCN":"指远离某物，不含路线画面。"},{"word":"sidestep","ipa":"/ˈsaɪdstep/","tag":"near meaning","definition":"To step to one side, literally or figuratively.","definitionCN":"指侧身避开，字面或比喻皆可。"},{"word":"skirt","ipa":"/skɜːt/","tag":"near meaning","definition":"To pass along the edge of something rather than through it.","definitionCN":"指沿着边缘经过而不穿越。"},{"word":"dodge","ipa":"/dɒdʒ/","tag":"near meaning","definition":"To move quickly out of the way, often of a blow or a question.","definitionCN":"指迅速闪开，多用于打击或问题。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the circle prefix, the come root, and the legal and technical phrases that keep the word current.","cn":"正常联想使用「圈」前缀、「来」词根，以及让这个词保持活跃的法律与技术搭配。"},"normal":[{"en":"Circum is around, so the word begins with a circle drawn around a barrier.","cn":"circum 是「周围」，所以这个词从围绕障碍画的一个圈开始。"},{"en":"Venire is to come, the same root as intervene and prevent.","cn":"venire 是「来」，与 intervene、prevent 同根。"},{"en":"Law says circumvent a rule; computing says circumvent a limit.","cn":"法律说规避规则，计算机说绕过限制。"},{"en":"Circumvent is not the same as break: the rule still stands, you simply avoid its reach.","cn":"这个词不等于违反：规则仍在，只是避开它的触及范围。"},{"en":"The old military sense was to encircle, which is why the word still feels like a manoeuvre.","cn":"古代军事义是包抄，所以这个词至今带有调动的感觉。"}],"abstract":[{"en":"To circumvent is to accept the wall and refuse the gate.","cn":"绕过，就是承认墙的存在，却拒绝走那扇门。"},{"en":"Every rule draws a line; every line has a place where it stops being watched.","cn":"每条规则都画一条线，而每条线都有不再被盯着的一段。"},{"en":"The shortest path is not always direct, and the word lives in that gap.","cn":"最短的路未必是直路，这个词就活在这个缝隙里。"}]},"examples":[{"en":"The supplier circumvented the ban by relabelling the goods.","cn":"供应商改换货物标签以规避禁令。"},{"en":"Drivers circumvent the closed bridge by a narrow riverside road.","cn":"司机沿一条狭窄的江边路绕开封闭的桥。"},{"en":"The team circumvented the broken sensor with a manual control.","cn":"团队用手动控制绕过了失灵的传感器。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「瑟肯姆文特」——封锁线在前，车队拐进小路：绕过、规避","word":"circumvent"},"root":"拉丁语 circum「周围」+ venire「来」→ circumvenire「绕到周围、包围」；英语十五世纪引入，先指空间绕行，后指规避规则，首见年代不确定。","sensesIntro":{"en":"Eight senses take one geometry, the circle around a barrier, through roads, laws, questions, controls, opponents, taxes, technical fixes and system limits.","cn":"八个义项把「绕障一圈」这一几何用到道路、法规、难题、管控、对手、税费、技术补救与系统限制上。"},"semanticMap":{"core":{"en":"CORE IMAGE: a truck turns off the main road and slips past the checkpoint on a side track.","cn":"核心意象：货车拐离主路，沿侧道滑过检查点。"},"chain":["AROUND","PLACE","RULE","DIFFICULTY","CONTROL","SYSTEM"],"branches":[{"senses":"01","en":"THE PHYSICAL DETOUR: a barrier stands on the road and the route bends around it.","cn":"空间绕行：障碍立在路上，路线在它外侧弯过去。"},{"senses":"02 · 06","en":"THE RULE DODGED: a law or a charge has an edge that the arrangement never touches.","cn":"规则被闪开：法规或收费有一道边缘，安排从不触碰。"},{"senses":"03 · 07","en":"THE OBSTACLE LEFT ALONE: a hard question is skipped, or a faulty part is worked around.","cn":"障碍被搁在一边：难题被跳过，或失灵部件被绕开。"},{"senses":"04","en":"THE WATCHED LINE: a filter or a supervisor is defeated without being switched off.","cn":"被盯的线：过滤或监管没有被关掉，却失效了。"},{"senses":"05 · 08","en":"THE STRONG POINT AVOIDED: an opponent's position or a technical limit is passed on the side.","cn":"强点被避开：对手的阵地或技术的限制从侧边过去。"}]},"affixes":{"intro":{"en":"Circumvent is a Latin compound of a prefix meaning around and a verb meaning to come, and both pieces recur across English.","cn":"这是一个拉丁复合词，由表示「周围」的前缀与表示「来」的动词构成，两部分在英语里都反复出现。"},"latinIntro":{"en":"Latin supplies circum, venire and circumvenire; the pieces are well recorded, so no part of this word is marked uncertain.","cn":"拉丁语提供了 circum、venire、circumvenire；这些部件有清楚记录，因此这个词没有哪一部分标为存疑。"},"items":[{"word":"circum","structure":"Latin prefix","meaning":"around, on all sides","meaningCN":"周围；四围","example":"It draws a circle around the obstacle.","exampleCN":"它围绕障碍画一个圈。"},{"word":"venire","structure":"Latin verb","meaning":"to come, to go","meaningCN":"来；去","example":"It supplies the movement half of the word.","exampleCN":"它提供这个词「移动」的那一半。"},{"word":"circumvenire","structure":"Latin verb","meaning":"to come around, surround","meaningCN":"绕到周围；包围","example":"The compound carried both the spatial and the deceptive shades.","exampleCN":"这个复合词兼有空间与欺瞒两种色彩。"},{"word":"circumventus","structure":"Latin participle","meaning":"having been encircled","meaningCN":"已被绕住","example":"The participle supplied the English adjective stem.","exampleCN":"这个分词提供了英语形容词词干。"},{"word":"-ion","structure":"action-result noun ending","meaning":"the act or result","meaningCN":"动作或结果","example":"It forms circumvention.","exampleCN":"它构成 circumvention。"},{"word":"-ive","structure":"adjective ending","meaning":"tending toward","meaningCN":"倾向于……的","example":"It forms circumventive.","exampleCN":"它构成 circumventive。"},{"word":"-er","structure":"agent noun ending","meaning":"the one who acts","meaningCN":"施动者","example":"It forms the rare noun for a person who goes around.","exampleCN":"它构成表示「绕行者」的少用名词。"},{"word":"-ed","structure":"past participle ending","meaning":"having undergone","meaningCN":"已……的","example":"It forms the adjective for what has been bypassed.","exampleCN":"它构成表示「已被绕过」的形容词。"}],"latinEntries":[{"word":"circum","structure":"Latin prefix","meaning":"around","meaningCN":"周围"},{"word":"venire","structure":"Latin verb","meaning":"to come","meaningCN":"来"},{"word":"circumvenire","structure":"Latin verb","meaning":"to come around, surround","meaningCN":"绕到周围；包围"},{"word":"circumventus","structure":"Latin participle","meaning":"encircled","meaningCN":"被绕住"}],"derivatives":[{"word":"circumvention","pos":"n.","zh":"由该动词加表示动作结果的名词尾构成，义为「规避；绕行」"},{"word":"circumvented","pos":"adj.","zh":"由该动词加已然词尾构成，义为「被绕过的」"},{"word":"circumventive","pos":"adj.","zh":"由该动词加表示倾向的形容词尾构成，义为「倾向于规避的」（少用）"},{"word":"circumventer","pos":"n.","zh":"由该动词加表示施动者的名词尾构成，义为「规避者」（少用）"}]}},{"word":"deteriorate","ipa_uk":"/dɪˈtɪəriəreɪt/","ipa_us":"/dɪˈteriəreɪt/","definition_zh":"恶化；变坏；退化；变质；衰减","definition_en":"to become progressively worse in quality, condition or state","core_image":"一面旧墙的抹灰从角上起皮，裂缝一天比一天宽，落下的粉末堆在墙脚","scene":"这栋楼长期没人维护，墙面起皮，管道也开始漏。Without maintenance the building will deteriorate within a few years.","sceneCN":"这里指建筑物状况逐渐变坏（第 3 个义项：环境或设施条件退化）；句意为若不维护，这栋楼几年内就会衰败。图中可辨识物件：起皮的墙面、裂缝、墙脚的粉末。","pos":[{"tag":"v.","zh":"恶化；变坏；退化；变质"}],"collocations":[{"phrase":"deteriorate rapidly","zh":"迅速恶化"},{"phrase":"deteriorate significantly","zh":"明显恶化"},{"phrase":"health deteriorates","zh":"健康状况恶化"},{"phrase":"conditions deteriorate","zh":"条件恶化"},{"phrase":"relations deteriorate","zh":"关系恶化"},{"phrase":"deteriorating situation","zh":"不断恶化的局势"},{"phrase":"deteriorate over time","zh":"随时间退化"}],"forms":[{"label":"动词原形","form":"deteriorate"},{"label":"第三人称单数","form":"deteriorates"},{"label":"过去式","form":"deteriorated"},{"label":"过去分词","form":"deteriorated"},{"label":"现在分词","form":"deteriorating"},{"label":"名词","form":"deterioration"}],"derivatives":[{"word":"deterioration","pos":"n.","zh":"由该动词加表示动作结果的名词尾构成，义为「恶化；退化；变质」"},{"word":"deteriorating","pos":"adj.","zh":"由该动词加形容词后缀构成，义为「不断恶化的」"},{"word":"deteriorated","pos":"adj.","zh":"由该动词加已然词尾构成，义为「已恶化的」"},{"word":"deteriorative","pos":"adj.","zh":"由该动词加表示倾向的形容词尾构成，义为「趋于恶化的」（少用）"}],"senses":[{"no":"01","title":"For health to worsen","titleCN":"健康状况恶化","definition":"for a person's physical or mental condition to decline steadily","definitionCN":"人的身体或精神状况持续下滑","example":"His hearing deteriorated after years of noise exposure.","exampleCN":"多年暴露在噪声中之后，他的听力变差了。","why":"The word describes a slide down a scale, and health is read on such a scale.","whyCN":"这个词描述的是一路下滑，而健康状况正是按这样的刻度来读的。"},{"no":"02","title":"For relations to sour","titleCN":"关系变坏","definition":"for ties between people, groups or states to become less friendly over time","definitionCN":"人与人、群体与群体或国与国之间的关系随时间变得不友好","example":"Relations between the two offices deteriorated after the dispute.","exampleCN":"争执之后，两个办事处的关系变差了。","why":"A relationship is a standing structure, and deteriorate records its slow loss of strength.","whyCN":"关系是一种立着的结构，这个词记录它缓慢失去强度。"},{"no":"03","title":"For conditions to degrade","titleCN":"环境或设施条件退化","definition":"for the physical state of a place, building or system to get progressively worse","definitionCN":"场所、建筑或系统的物理状态逐步变差","example":"The housing stock deteriorated faster than the city could repair it.","exampleCN":"住房状况恶化的速度超过了城市的修缮能力。","why":"Materials and places wear down in one direction, and the verb names that one-way drift.","whyCN":"材料与场所只朝一个方向磨损，这个词命名那种单向漂移。"},{"no":"04","title":"For quality to decline","titleCN":"质量下降；变质","definition":"for the quality of a product or material to fall below an earlier standard","definitionCN":"产品或材料的质量降到早先标准之下","example":"The stored grain deteriorated because the silo was damp.","exampleCN":"因为粮仓潮湿，储存的谷物变质了。","why":"Quality is a level, and the verb says the level keeps dropping.","whyCN":"质量是一个水平线，这个词说这条线一直在往下掉。"},{"no":"05","title":"For performance to decay","titleCN":"性能衰减","definition":"for a machine or system to work less well than before","definitionCN":"机器或系统的运转效果不如从前","example":"Battery performance deteriorates in freezing weather.","exampleCN":"电池性能在严寒天气里会衰减。","why":"Engineering treats wear as a predictable curve, and deteriorate is the verb for the downward part.","whyCN":"工程把磨损看作一条可预测的曲线，这个词专指向下的那一段。"},{"no":"06","title":"For economic indicators to weaken","titleCN":"经济指标走弱","definition":"for trade, output or confidence to move towards a worse position","definitionCN":"贸易、产出或信心朝更差的方向移动","example":"The trade balance deteriorated for the third quarter running.","exampleCN":"贸易差额连续第三个季度恶化。","why":"Economists read a falling line as a worsening, and the verb carries no other emotion.","whyCN":"经济学家把下行的曲线读作恶化，这个词不带别的情绪。"},{"no":"07","title":"For a medical condition to progress badly","titleCN":"病情加重","definition":"for a disease or a patient's state to move towards a worse stage","definitionCN":"疾病或病人的状态走向更差的阶段","example":"The patient deteriorated overnight and was moved to intensive care.","exampleCN":"病人一夜之间恶化，被转入重症监护。","why":"Clinical writing uses the verb for the direction of a course, not for its speed.","whyCN":"临床记录用这个动词说明病程方向，而不说明速度。"},{"no":"08","title":"For order or safety to decline","titleCN":"秩序或安全形势变差","definition":"for public order, security or discipline to become weaker or more dangerous","definitionCN":"公共秩序、安全或纪律变得薄弱或更危险","example":"Security in the district deteriorated after the patrols stopped.","exampleCN":"巡逻停止后，该区的治安恶化了。","why":"Order is a structure held by many hands, and the verb marks the strain that loosens it.","whyCN":"秩序是许多只手撑着的结构，这个词标出把它松开的那些拉力。"}],"etymology":{"intro":{"en":"Deteriorate comes from Late Latin deteriorare, to make worse, from deterior, worse, a comparative whose positive form is not attested. French and English adopted the verb in the sixteenth century.","cn":"这个词来自晚期拉丁语 deteriorare「使变坏」，出自比较级 deterior「更坏」，而其原级形式并无记录；法语与英语在十六世纪采用它。"},"items":[{"era":"LATIN DETERIOR","en":"Deterior was the comparative of an older adjective meaning lower or inferior, and that positive form survives only as a reconstruction.","cn":"这是较古形容词「较低、较差」的比较级，而那个原级只以重构形式存在，没有实际记录。"},{"era":"LATE LATIN DETERIORARE","en":"The verb meant to make worse or to become worse, and it appears mainly in later technical and medical writing.","cn":"这个动词意为使变坏或变坏，主要见于较晚的技术与医学文献。"},{"era":"FRENCH DÉTÉRIORER","en":"French formed its own verb from the same Latin comparative and passed it to English.","cn":"法语由同一拉丁比较级造出自己的动词，再传给英语。"},{"era":"ENGLISH, 16TH CENTURY","en":"English records the verb from the sixteenth century; the exact first date is uncertain.","cn":"英语自十六世纪有记录，确切首见年代不确定。"},{"era":"THE MISSING POSITIVE","en":"The base adjective behind deterior cannot be recovered from any surviving text, so its source is uncertain.","cn":"deterior 背后的原级形容词无法从任何传世文本中复原，因此标记为来源不确定。"},{"era":"MODERN MEDICAL AND ECONOMIC USE","en":"Medicine and economics gave the verb fixed subjects such as condition, patient and balance.","cn":"医学与经济学给这个动词添了固定主语，如状况、病人与收支。"}]},"similar":{"note":{"en":"The first group looks close or shares the deteriorating stem; the second group names neighbouring ideas of decline.","cn":"第一组与「deteriorate」形近或共享「恶化」词干；第二组是与「下滑」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"deterioration","ipa":"/dɪˌtɪəriəˈreɪʃn/","tag":"same root","definition":"The noun for the process of becoming worse.","definitionCN":"指变坏这一过程的名词。"},{"word":"deteriorating","ipa":"/dɪˈtɪəriəreɪtɪŋ/","tag":"same root","definition":"The adjective for something in the middle of getting worse.","definitionCN":"形容词，指正处在恶化过程中的。"},{"word":"determine","ipa":"/dɪˈtɜːmɪn/","tag":"different root","definition":"To settle or decide, from terminus, a boundary; it looks close but is unrelated.","definitionCN":"指确定、决定，出自「边界」；形近但无亲缘。"},{"word":"deterrent","ipa":"/dɪˈterənt/","tag":"different root","definition":"Something that discourages an action, from a verb meaning to frighten away.","definitionCN":"指起威慑作用的事物，出自「吓退」的动词。"},{"word":"detriment","ipa":"/ˈdetrɪmənt/","tag":"different root","definition":"Harm or damage, from a different Latin stem.","definitionCN":"指损害，出自另一拉丁词干。"}]},{"heading":"NEAR MEANING","entries":[{"word":"worsen","ipa":"/ˈwɜːsn/","tag":"near meaning","definition":"To become or make worse, the plainest verb of the group.","definitionCN":"指变坏或使变坏，是本组最朴素的说法。"},{"word":"decline","ipa":"/dɪˈklaɪn/","tag":"near meaning","definition":"To go down in amount or quality, often neutral in tone.","definitionCN":"指数量或质量下降，语气常较中性。"},{"word":"degrade","ipa":"/dɪˈɡreɪd/","tag":"near meaning","definition":"To lower in quality, rank or condition.","definitionCN":"指质量、等级或状况降低。"},{"word":"decay","ipa":"/dɪˈkeɪ/","tag":"near meaning","definition":"To rot or break down slowly through natural processes.","definitionCN":"指经自然过程缓慢腐烂或分解。"},{"word":"erode","ipa":"/ɪˈrəʊd/","tag":"near meaning","definition":"To wear away gradually, literally by wind or water.","definitionCN":"指逐渐磨损，字面多指风水侵蚀。"},{"word":"slump","ipa":"/slʌmp/","tag":"near meaning","definition":"To fall suddenly in value or performance.","definitionCN":"指价值或表现突然下跌。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the worse comparative, its missing base, and the fixed subjects medicine and economics give it.","cn":"正常联想使用「更坏」这一比较级、它缺失的原级，以及医学与经济学给它的固定主语。"},"normal":[{"en":"Deterior is already a comparative, so the word starts from the idea of worse, not bad.","cn":"deterior 本身是比较级，所以这个词从「更坏」而不是「坏」起步。"},{"en":"The positive adjective behind it never survived, which is the honest reason for marking its origin uncertain.","cn":"它背后的原级形容词没有传下来，这正是把来源标为存疑的诚实理由。"},{"en":"Doctors write that a patient deteriorated overnight.","cn":"医生会写病人一夜之间恶化。"},{"en":"Economists write that the trade balance deteriorated.","cn":"经济学家会写贸易差额恶化。"},{"en":"Deterioration is the noun, and deteriorating is the adjective used before situation.","cn":"名词是 deterioration，形容词 deteriorating 常用于 situation 之前。"}],"abstract":[{"en":"To deteriorate is to lose strength without any single blow, which is the hardest kind of damage to notice.","cn":"恶化是没有一次重击却不断失去强度，这是最难察觉的一种损坏。"},{"en":"Every system has a downward curve, and the word simply names the slope.","cn":"每个系统都有一条下行曲线，这个词只是给那道坡命名。"},{"en":"Things do not usually collapse; they first become slightly worse than yesterday.","cn":"事物通常不是突然崩塌的，而是先比昨天差一点。"}]},"examples":[{"en":"The road surface deteriorated quickly after the winter frosts.","cn":"冬季霜冻之后，路面很快恶化了。"},{"en":"Their working relationship deteriorated after the failed merger.","cn":"合并失败后，他们的工作关系变差了。"},{"en":"Air quality deteriorates whenever the wind drops.","cn":"风一停，空气质量就恶化。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「迪提里奥瑞特」——旧墙起皮，裂缝一天比一天宽：恶化、变坏","word":"deteriorate"},"root":"拉丁语 deterior「更坏」（比较级，原级无传世记录，直接来源不确定）→ 晚期拉丁语 deteriorare「使变坏」→ 法语 détériorer；英语十六世纪引入。","sensesIntro":{"en":"Eight senses follow one downward slope through health, relations, places, quality, machinery, economy, illness and public order.","cn":"八个义项沿同一条下坡走过健康、关系、场所、质量、机器、经济、病情与治安。"},"semanticMap":{"core":{"en":"CORE IMAGE: plaster flakes off an old wall and the crack widens a little every day.","cn":"核心意象：旧墙抹灰一片片起皮，裂缝每天宽一点。"},"chain":["WORSE","HEALTH","RELATIONS","MATERIAL STATE","PERFORMANCE","SYSTEM"],"branches":[{"senses":"01 · 07","en":"THE BODY SLIDES: a person's condition or a disease course moves to a worse stage.","cn":"身体下滑：人的状况或病程走向更差的阶段。"},{"senses":"02","en":"THE TIE LOOSENS: relations lose their friendliness without any single break.","cn":"纽带松了：关系失去友好，却不是一次断裂。"},{"senses":"03 · 04","en":"THE MATERIAL WEARS: buildings and stored goods fall below an earlier standard.","cn":"材料磨损：建筑与存粮降到早先标准之下。"},{"senses":"05","en":"THE MACHINE LOSES EDGE: output falls as parts age or conditions harden.","cn":"机器失锋：部件老化或条件变严，输出随之下降。"},{"senses":"06 · 08","en":"THE SYSTEM SAGS: balances weaken and public order grows more dangerous.","cn":"系统下沉：收支走弱，治安变得更危险。"}]},"affixes":{"intro":{"en":"Deteriorate is a Late Latin verb built on a comparative adjective, so its affixes are the endings of comparison and of verb formation.","cn":"这是一个建立在比较级形容词上的晚期拉丁动词，其词缀是比较级与动词构成用的词尾。"},"latinIntro":{"en":"Latin supplies deterior and deteriorare; the positive adjective behind deterior is not attested, so the base is marked uncertain rather than invented.","cn":"拉丁语提供了 deterior 与 deteriorare；deterior 背后的原级形容词没有记录，因此只标存疑，不作编造。"},"items":[{"word":"deterior","structure":"Latin comparative adjective","meaning":"worse, inferior","meaningCN":"更坏的；较差的","example":"The comparative already carries the direction of the word.","exampleCN":"这个比较级已经带上了这个词的方向。"},{"word":"-ior","structure":"Latin comparative ending","meaning":"more than","meaningCN":"更……","example":"It marks the form as a comparison, not a positive quality.","exampleCN":"它标明该形式是比较级，而非原级性质。"},{"word":"deteriorare","structure":"Late Latin verb","meaning":"to make or become worse","meaningCN":"使变坏；变坏","example":"The verb turns the comparison into a process.","exampleCN":"这个动词把比较变成过程。"},{"word":"-ate","structure":"Latin verb ending","meaning":"to make or cause","meaningCN":"使……；做……","example":"It marks the English verb.","exampleCN":"它标明英语动词。"},{"word":"-ion","structure":"action-result noun ending","meaning":"the act or result","meaningCN":"动作或结果","example":"It forms deterioration.","exampleCN":"它构成 deterioration。"},{"word":"-ing","structure":"adjective ending","meaning":"in the course of","meaningCN":"正在……的","example":"It forms deteriorating.","exampleCN":"它构成 deteriorating。"},{"word":"-ive","structure":"adjective ending","meaning":"tending toward","meaningCN":"倾向于……的","example":"It forms the rare deteriorative.","exampleCN":"它构成少用的 deteriorative。"},{"word":"-ed","structure":"past participle ending","meaning":"having undergone","meaningCN":"已……的","example":"It forms the adjective for what has already worsened.","exampleCN":"它构成表示「已恶化」的形容词。"}],"latinEntries":[{"word":"deterior","structure":"Latin comparative adjective","meaning":"worse, inferior","meaningCN":"更坏的；较差的"},{"word":"deteriorare","structure":"Late Latin verb","meaning":"to make worse","meaningCN":"使变坏"},{"word":"deterius","structure":"Latin adverb","meaning":"more badly","meaningCN":"更糟地"}],"derivatives":[{"word":"deterioration","pos":"n.","zh":"由该动词加表示动作结果的名词尾构成，义为「恶化；退化」"},{"word":"deteriorating","pos":"adj.","zh":"由该动词加形容词后缀构成，义为「不断恶化的」"},{"word":"deteriorative","pos":"adj.","zh":"由该动词加表示倾向的形容词尾构成，义为「趋于恶化的」（少用）"},{"word":"deteriorated","pos":"adj.","zh":"由该动词加已然词尾构成，义为「已恶化的」"}]}},{"word":"eradicate","ipa_uk":"/ɪˈrædɪkeɪt/","ipa_us":"/ˌerəˈdɪkeɪt/","definition_zh":"根除；消灭；杜绝；连根拔除","definition_en":"to remove something harmful completely, including its source or roots","core_image":"田里一株病草被连根拔出，根须完整地带出土，地面上只留下一个干净的坑","scene":"防疫队把最后一批病例追踪到位，之后三年没有再出现新发。The campaign aims to eradicate the disease from the whole region.","sceneCN":"这里指把疾病从源头彻底清除（第 1 个义项：根除疾病）；句意为这场运动的目标是在全区根除这种病。图中可辨识物件：连根拔起的病草、拔出的根须、干净的土坑。","pos":[{"tag":"v.","zh":"根除；消灭；杜绝"}],"collocations":[{"phrase":"eradicate disease","zh":"根除疾病"},{"phrase":"eradicate poverty","zh":"消除贫困"},{"phrase":"eradicate corruption","zh":"杜绝腐败"},{"phrase":"eradicate pests","zh":"消灭害虫"},{"phrase":"eradicate a practice","zh":"废除某种做法"},{"phrase":"eradicate illiteracy","zh":"扫除文盲"},{"phrase":"eradicate the root cause","zh":"根除根源"}],"forms":[{"label":"动词原形","form":"eradicate"},{"label":"第三人称单数","form":"eradicates"},{"label":"过去式","form":"eradicated"},{"label":"过去分词","form":"eradicated"},{"label":"现在分词","form":"eradicating"},{"label":"名词","form":"eradication"},{"label":"形容词","form":"ineradicable"}],"derivatives":[{"word":"eradication","pos":"n.","zh":"由该动词加表示动作结果的名词尾构成，义为「根除；消灭」"},{"word":"eradicator","pos":"n.","zh":"由该动词加表示施动者的名词尾构成，义为「根除者；消灭者」"},{"word":"eradicable","pos":"adj.","zh":"由该动词加「可……的」形容词尾构成，义为「可根除的」"},{"word":"ineradicable","pos":"adj.","zh":"由否定前缀加「可根除的」构成，义为「无法根除的」"},{"word":"eradicated","pos":"adj.","zh":"由该动词加已然词尾构成，义为「已被根除的」"}],"senses":[{"no":"01","title":"To wipe out a disease","titleCN":"根除疾病","definition":"to bring a disease down to zero new cases over a wide area and keep it there","definitionCN":"使疾病在大范围内降到零新增并保持下去","example":"Vaccination helped eradicate smallpox worldwide.","exampleCN":"疫苗接种帮助在全世界根除了天花。","why":"The image is a plant pulled out by the root, and a disease is treated as something growing in a population.","whyCN":"画面是被连根拔起的植物，而疾病被当作在人群中生长之物。"},{"no":"02","title":"To destroy a pest","titleCN":"消灭害虫或杂草","definition":"to remove an insect, weed or other pest completely from an area","definitionCN":"把一个地区的昆虫、杂草或其他有害生物彻底清除","example":"The programme eradicated the beetle from the island.","exampleCN":"该项目把这个岛上的甲虫彻底消灭了。","why":"This is the literal agricultural scene: pull the weed out, root and all.","whyCN":"这是最字面的农事画面：连根把草拔掉。"},{"no":"03","title":"To eliminate poverty","titleCN":"消除贫困","definition":"to reduce material deprivation to a level defined as zero by a policy target","definitionCN":"把物质匮乏降到政策目标所定义的零水平","example":"No single programme can eradicate poverty in a decade.","exampleCN":"没有任何一个项目能在十年内消除贫困。","why":"Policy borrows the strong verb because it promises to remove the root, not just the visible part.","whyCN":"政策借用了这个强动词，因为它承诺拔掉根，而不只是割掉露出地面的部分。"},{"no":"04","title":"To stamp out corruption","titleCN":"杜绝腐败","definition":"to remove dishonest practices from an institution so that they no longer recur","definitionCN":"从机构中清除不诚实做法，使其不再反复出现","example":"The commission was set up to eradicate bribery in licensing.","exampleCN":"该委员会成立的目的是杜绝发证环节的贿赂。","why":"Corruption is pictured as a weed with deep roots in procedure, hence the word for rooting it out.","whyCN":"腐败被想象成在程序里扎根的杂草，于是用了「连根拔」这个词。"},{"no":"05","title":"To abolish a practice","titleCN":"彻底废除某种做法","definition":"to end a custom or method completely so that it is no longer taught or used","definitionCN":"彻底终止某种习俗或方法，使其不再被传授或使用","example":"The reform eradicated the practice of paying for referrals.","exampleCN":"这项改革废除了付费转介的做法。","why":"Practices spread like plants, and ending them fully means removing the conditions that reproduce them.","whyCN":"做法像植物一样蔓延，彻底终止意味着拆掉让它繁殖的条件。"},{"no":"06","title":"To remove a hidden risk","titleCN":"消除隐患","definition":"to find and remove the underlying cause of a danger rather than its symptoms","definitionCN":"找到并移除危险的深层原因，而不只是处理表象","example":"Inspectors eradicated the fault before the line reopened.","exampleCN":"检查人员在生产线重开前消除了这个隐患。","why":"The root is hidden underground, which is exactly why the word suits hidden causes.","whyCN":"根藏在地下，这正是这个词适合「隐藏原因」的原因。"},{"no":"07","title":"To uproot a plant","titleCN":"连根拔除植物","definition":"to pull a plant out of the ground with its roots intact","definitionCN":"把植物连根从土里拔出","example":"Workers eradicated the invasive reed along the canal.","exampleCN":"工人沿运河连根清除了入侵的芦苇。","why":"This is the etymological sense in the open: e-radix means out of the root.","whyCN":"这是词源义的明面：前缀加「根」就是「从根里出来」。"},{"no":"08","title":"To solve a problem at its root","titleCN":"从根本上解决问题","definition":"to deal with the cause of a problem so that it cannot return","definitionCN":"处理问题的成因，使它无法再回来","example":"The redesign eradicated the vibration instead of damping it.","exampleCN":"重新设计从根本上消除了振动，而不是把它压住。","why":"Damping treats the symptom, uprooting treats the cause, and the verb belongs to the second.","whyCN":"阻尼处理症状，拔根处理病因，这个词属于后者。"}],"etymology":{"intro":{"en":"Eradicate comes from Latin eradicare, to root out, from e-, out of, and radix, root. English took it in the sixteenth century for both plants and evils.","cn":"这个词来自拉丁语 eradicare「连根拔除」，由 e-「出」与 radix「根」构成；英语十六世纪引入，既用于植物，也用于祸害。"},"items":[{"era":"LATIN RADIX","en":"Radix meant root, and it also gave English radical, radish and the mathematical root.","cn":"这个词意为「根」，还给出「根本的」「萝卜」以及数学上的根等词。"},{"era":"LATIN E-","en":"The prefix e- is a form of ex, meaning out of, and it marks removal from the inside.","cn":"前缀 e- 是 ex 的一种形式，意为「出」，标出从内部取走。"},{"era":"LATIN ERADICARE","en":"The verb meant to pull up by the roots, and farmers used it of vines and trees before writers used it of vices.","cn":"这个动词意为连根拔起，农人先用它说藤与树，文人后来才用它说恶习。"},{"era":"ENGLISH, 16TH CENTURY","en":"English adopted the verb in the sixteenth century; the exact first date is uncertain and is usually given only as that century.","cn":"英语十六世纪采用这个动词，确切首见年代不确定，通常只给「十六世纪」。"},{"era":"MEDICAL AND SOCIAL EXTENSION","en":"Public health and reform movements extended the verb to disease, poverty and corruption.","cn":"公共卫生与改革运动把这个动词扩展到疾病、贫困与腐败。"},{"era":"THE ROOT FAMILY","en":"Radical, radish and eradicate all point back to the same Latin word for root, though each took a different road.","cn":"「根本的」「萝卜」与本词都回到同一个表示「根」的拉丁词，只是各走一条路。"}]},"similar":{"note":{"en":"The first group shares the root word or looks close; the second group names neighbouring ideas of complete removal.","cn":"第一组与「eradicate」共享「根」这个词或只是形近；第二组是与「彻底清除」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"eradication","ipa":"/ɪˌrædɪˈkeɪʃn/","tag":"same root","definition":"The noun for the act of removing something completely.","definitionCN":"指彻底清除这一行为的名词。"},{"word":"ineradicable","ipa":"/ˌɪnɪˈrædɪkəbl/","tag":"same root","definition":"An adjective for something that cannot be rooted out.","definitionCN":"形容词，指无法根除的。"},{"word":"radical","ipa":"/ˈrædɪkl/","tag":"same root","definition":"Going to the root, from the same Latin word for root.","definitionCN":"指根本的、激进的，同出「根」这个词。"},{"word":"radish","ipa":"/ˈrædɪʃ/","tag":"same root","definition":"The vegetable named from the same root word.","definitionCN":"这种蔬菜的名字同出「根」这个词。"},{"word":"radiate","ipa":"/ˈreɪdieɪt/","tag":"different root","definition":"To send out rays, from radius, a spoke; it looks close but is a different stem.","definitionCN":"指放射，出自「辐条」；形近但词干不同。"}]},{"heading":"NEAR MEANING","entries":[{"word":"eliminate","ipa":"/ɪˈlɪmɪneɪt/","tag":"near meaning","definition":"To remove something completely, often by taking it out of a set.","definitionCN":"指彻底去除，常指从一组中剔除。"},{"word":"exterminate","ipa":"/ɪkˈstɜːmɪneɪt/","tag":"near meaning","definition":"To destroy a group of living things entirely, usually pests.","definitionCN":"指彻底消灭一群生物，多指害虫。"},{"word":"abolish","ipa":"/əˈbɒlɪʃ/","tag":"near meaning","definition":"To end a law, system or practice officially.","definitionCN":"指正式废除法律、制度或做法。"},{"word":"wipe out","ipa":"/waɪp aʊt/","tag":"near meaning","definition":"To destroy something completely, in plainer speech.","definitionCN":"指彻底摧毁，口语色彩更强。"},{"word":"stamp out","ipa":"/stæmp aʊt/","tag":"near meaning","definition":"To end something bad by firm action, as if stepping on it.","definitionCN":"指以坚决行动扑灭坏事，像用脚踩灭。"},{"word":"remove","ipa":"/rɪˈmuːv/","tag":"near meaning","definition":"To take something away, without promising that it cannot return.","definitionCN":"指把某物拿走，不保证不会再来。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the root word inside the verb, its plant family and the public campaigns that made it famous.","cn":"正常联想使用动词内部那个「根」词、它的植物同族词，以及让它出名的公共卫生运动。"},"normal":[{"en":"Radix is root, so eradicate is literally to take something out by the root.","cn":"radix 是「根」，所以这个词字面就是连根取出。"},{"en":"Radical, radish and eradicate all trace back to the same root word.","cn":"radical、radish、eradicate 都回到同一个「根」词。"},{"en":"Public health speaks of eradicating a disease, never of merely controlling it.","cn":"公共卫生说根除疾病，而不只是控制它。"},{"en":"Ineradicable is the negative adjective: a habit that cannot be rooted out.","cn":"「无法根除的」是否定形容词：拔不掉的习惯。"},{"en":"A weed is eradicated, a symptom is treated, and the word insists on the difference.","cn":"杂草被根除，症状被治疗，这个词坚持这个区别。"}],"abstract":[{"en":"To eradicate is to refuse the compromise of cutting the stem and leaving the root.","cn":"根除，就是拒绝「割茎留根」这种妥协。"},{"en":"What grows back was never eradicated, only trimmed.","cn":"会再长出来的东西从来没有被根除，只是被修剪过。"},{"en":"The deepest causes are the ones no one can see, which is why the word begins underground.","cn":"最深的成因没人看得见，所以这个词从地下开始。"}]},"examples":[{"en":"The region eradicated malaria within a single generation.","cn":"该地区在一代人之内根除了疟疾。"},{"en":"Gardeners eradicated the knotweed before it reached the river.","cn":"园丁在节节草到达河边之前就把它连根清除了。"},{"en":"The reform did not eradicate the practice, but it made it rare.","cn":"改革没有杜绝这种做法，但让它变得少见。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「伊拉德凯特」——手一拽，根须完整出土：根除、消灭","word":"eradicate"},"root":"拉丁语 radix「根」→ eradicare「连根拔除」（e-「出」+ radicare「扎根」）；英语十六世纪引入。与 radius「辐条」不同源（radiate 属另一词干）。","sensesIntro":{"en":"Eight senses all pull something up by the root: disease, pests, poverty, corruption, a practice, a hidden fault, a plant and a cause.","cn":"八个义项都在把某物连根拔起：疾病、害虫、贫困、腐败、做法、隐患、植物与成因。"},"semanticMap":{"core":{"en":"CORE IMAGE: a diseased weed comes out with its full root, leaving a clean hole in the soil.","cn":"核心意象：病草带着完整的根被拔出，土里留下一个干净的坑。"},"chain":["ROOT","PLANT","PEST","DISEASE","SOCIAL ILL","CAUSE"],"branches":[{"senses":"01","en":"THE EPIDEMIC ENDS: new cases fall to zero and stay there.","cn":"流行病终结：新增病例降到零并保持。"},{"senses":"02 · 07","en":"THE PLANT IS PULLED: a pest or a weed leaves the ground with its roots intact.","cn":"植物被拔起：害虫或杂草带着完整的根离开土地。"},{"senses":"03 · 06","en":"THE HIDDEN ROOT: poverty and unseen faults are attacked below the surface.","cn":"隐藏的根：贫困与看不见的隐患在地表之下被处理。"},{"senses":"04","en":"THE INSTITUTION IS CLEANED: bribery stops reproducing itself inside procedure.","cn":"机构被清理：贿赂不再在程序内部自我繁殖。"},{"senses":"05 · 08","en":"THE SOURCE IS REMOVED: a custom or a problem loses the conditions that kept it alive.","cn":"源头被移除：习俗或问题失去让它存活的那些条件。"}]},"affixes":{"intro":{"en":"Eradicate is a Latin verb built on the word for root, and the same root appears in radical and radish.","cn":"这是一个建立在「根」这个词上的拉丁动词，同一词根也出现在 radical 与 radish 中。"},"latinIntro":{"en":"Latin supplies radix, radicari and eradicare; the family is well recorded, so no part of the word is marked uncertain.","cn":"拉丁语提供了 radix、radicari、eradicare；这一族有清楚记录，这个词没有哪一部分标为存疑。"},"items":[{"word":"radix","structure":"Latin noun","meaning":"root","meaningCN":"根","example":"The noun named the underground part of a plant.","exampleCN":"这个名词指植物的地下部分。"},{"word":"radicari","structure":"Latin verb from radix","meaning":"to take root","meaningCN":"扎根","example":"The verb named the plant's settling into soil.","exampleCN":"这个动词指植物在土里安身。"},{"word":"e-","structure":"form of Latin ex","meaning":"out of","meaningCN":"出；向外","example":"It marks removal from within.","exampleCN":"它标出从内部取出。"},{"word":"eradicare","structure":"Latin verb","meaning":"to root out","meaningCN":"连根拔除","example":"The verb combined removal with the root.","exampleCN":"这个动词把「取出」与「根」合在一起。"},{"word":"-ate","structure":"Latin verb ending","meaning":"to make or do","meaningCN":"做；使","example":"It marks the English verb.","exampleCN":"它标明英语动词。"},{"word":"-ion","structure":"action-result noun ending","meaning":"the act or result","meaningCN":"动作或结果","example":"It forms eradication.","exampleCN":"它构成 eradication。"},{"word":"-able","structure":"adjective ending","meaning":"capable of being","meaningCN":"可……的","example":"It forms eradicable.","exampleCN":"它构成 eradicable。"},{"word":"in-","structure":"Latin negative prefix","meaning":"not","meaningCN":"不；非","example":"It forms ineradicable.","exampleCN":"它构成 ineradicable。"},{"word":"-or","structure":"agent noun ending","meaning":"the one who acts","meaningCN":"施动者","example":"It forms eradicator.","exampleCN":"它构成 eradicator。"}],"latinEntries":[{"word":"radix","structure":"Latin noun","meaning":"root","meaningCN":"根"},{"word":"radicari","structure":"Latin verb","meaning":"to take root","meaningCN":"扎根"},{"word":"eradicare","structure":"Latin verb","meaning":"to root out","meaningCN":"连根拔除"},{"word":"radicatus","structure":"Latin participle","meaning":"rooted","meaningCN":"已扎根的"}],"derivatives":[{"word":"eradication","pos":"n.","zh":"由该动词加表示动作结果的名词尾构成，义为「根除；消灭」"},{"word":"eradicator","pos":"n.","zh":"由该动词加表示施动者的名词尾构成，义为「根除者」"},{"word":"eradicable","pos":"adj.","zh":"由该动词加「可……的」形容词尾构成，义为「可根除的」"},{"word":"ineradicable","pos":"adj.","zh":"由否定前缀加「可根除的」构成，义为「无法根除的」"}]}},{"word":"hinder","ipa_uk":"/ˈhɪndə/","ipa_us":"/ˈhɪndər/","definition_zh":"阻碍；妨碍；拖慢；阻挠","definition_en":"to make progress, movement or an effort slower or more difficult","core_image":"一条窄路中间横着一块落石，后面的人只能一点点侧身挪过去","scene":"材料迟迟不到，工人只能在半成品旁边等，工期一天天往后推。Late deliveries hindered progress on the upper floors.","sceneCN":"这里指拖慢工程的推进（第 1 个义项：阻碍进展）；句意为到货太晚妨碍了上层的施工进度。图中可辨识物件：横在路中的落石、侧身通过的人、堆着的半成品。","pos":[{"tag":"v.","zh":"阻碍；妨碍；拖慢"}],"collocations":[{"phrase":"hinder progress","zh":"阻碍进展"},{"phrase":"hinder development","zh":"妨碍发展"},{"phrase":"hinder growth","zh":"抑制增长"},{"phrase":"hinder efforts","zh":"妨碍努力"},{"phrase":"hinder performance","zh":"影响表现"},{"phrase":"be hindered by","zh":"受……妨碍"},{"phrase":"hinder the recovery","zh":"拖慢复苏"}],"forms":[{"label":"动词原形","form":"hinder"},{"label":"第三人称单数","form":"hinders"},{"label":"过去式","form":"hindered"},{"label":"过去分词","form":"hindered"},{"label":"现在分词","form":"hindering"},{"label":"名词","form":"hindrance"}],"derivatives":[{"word":"hindrance","pos":"n.","zh":"由该动词加表示性质或结果的名词尾构成，义为「阻碍；障碍物」"},{"word":"hindered","pos":"adj.","zh":"由该动词加已然词尾构成，义为「受妨碍的」"},{"word":"hindering","pos":"adj.","zh":"由该动词加形容词后缀构成，义为「起妨碍作用的」"},{"word":"hinderer","pos":"n.","zh":"由该动词加表示施动者的名词尾构成，义为「阻碍者」（少用）"},{"word":"hinderingly","pos":"adv.","zh":"由形容词加副词词尾构成，义为「以妨碍的方式」（少用）"}],"senses":[{"no":"01","title":"To slow a project","titleCN":"拖慢项目进展","definition":"to make a project or task take longer by creating obstacles","definitionCN":"通过制造障碍，让项目或任务花更长时间","example":"Missing permits hindered work on the site for weeks.","exampleCN":"缺少许可使工地施工拖了好几周。","why":"The core sense is being placed behind, and a delay puts a task behind schedule.","whyCN":"核心义是「被放在后面」，而延误就是把任务放到进度后面。"},{"no":"02","title":"To block movement","titleCN":"妨碍移动","definition":"to make it hard for someone or something to move forward","definitionCN":"使人或物难以前进","example":"Fallen trees hindered the rescue teams in the valley.","exampleCN":"倒下的树妨碍了山谷里的救援队。","why":"This is the physical picture at its simplest: something in the way, a body moving around it.","whyCN":"这是最朴素的物理画面：有东西挡路，身体绕着走。"},{"no":"03","title":"To restrain growth","titleCN":"抑制增长","definition":"to keep an economy, market or organism from expanding at its potential rate","definitionCN":"使经济、市场或生物体无法按潜在速度扩张","example":"Uncertain rules hindered investment in the region.","exampleCN":"规则不明朗抑制了该地区的投资。","why":"Growth is a forward motion, and hindering puts weight on it.","whyCN":"增长是向前运动，阻碍就是给它加上重量。"},{"no":"04","title":"To disrupt work or study","titleCN":"干扰工作或学习","definition":"to interrupt concentration or routine so that output falls","definitionCN":"打断专注或日常节奏，使产出下降","example":"Constant noise hindered her revision for the exam.","exampleCN":"持续的噪声干扰了她的备考复习。","why":"Attention is a narrow path, and any obstruction on it costs time.","whyCN":"注意力是一条窄路，路上任何阻碍都要花时间。"},{"no":"05","title":"To obstruct a plan","titleCN":"阻挠计划","definition":"to act so that a proposal or decision cannot proceed as intended","definitionCN":"采取行动，使提案或决定无法按计划推进","example":"Two members hindered the vote by raising procedural objections.","exampleCN":"两名成员提出程序异议，阻挠了表决。","why":"Institutions run on procedure, so blocking a step is enough to hold the whole thing back.","whyCN":"机构靠程序运转，卡住一步就足以拖住整件事。"},{"no":"06","title":"To stunt growth or recovery","titleCN":"抑制生长或恢复","definition":"to prevent a living thing or a recovery from reaching full development","definitionCN":"使生物体或恢复过程无法充分发展","example":"Poor light hindered the seedlings after transplanting.","exampleCN":"光照不足抑制了移栽后的幼苗生长。","why":"Biology uses the verb for anything that keeps a process below its natural curve.","whyCN":"生物学用这个动词指任何让过程低于其自然曲线的因素。"},{"no":"07","title":"To make a task harder","titleCN":"增加任务难度","definition":"to raise the effort or cost needed to complete something","definitionCN":"提高完成某事所需的努力或成本","example":"The outdated software hindered every update.","exampleCN":"过时的软件让每次更新都更难。","why":"Difficulty is friction, and the verb names the extra friction added.","whyCN":"难度就是摩擦，这个词指被加上去的那份额外摩擦。"},{"no":"08","title":"To impair communication","titleCN":"妨碍沟通协调","definition":"to make exchange of information or cooperation less effective","definitionCN":"使信息交换或合作效果变差","example":"Different reporting formats hindered coordination between teams.","exampleCN":"不同的报表格式妨碍了各团队之间的协调。","why":"Coordination needs a clear channel, and hinder narrows it.","whyCN":"协调需要畅通的通道，而这个词把它收窄。"}],"etymology":{"intro":{"en":"Hinder comes from Old English hindrian, to hold back, from hinder, meaning behind. The word is Germanic and has always kept the picture of being placed at the back.","cn":"这个词来自古英语 hindrian「拦在后面」，出自 hinder「在后面」；属日耳曼语，始终保留「被放到后面」的画面。"},"items":[{"era":"OLD ENGLISH HINDER","en":"The adverb meant behind or in the rear, and it is the same element seen in behind.","cn":"这个副词意为「在后面、在后部」，与 behind 中的成分相同。"},{"era":"OLD ENGLISH HINDRIAN","en":"The verb meant to keep back or delay, and it was used of people, animals and journeys.","cn":"这个动词意为拦阻、耽搁，用于人、牲畜与行程。"},{"era":"MIDDLE ENGLISH","en":"The spelling settled as hinder, and the noun hindrance grew beside it with the same vowel pattern.","cn":"拼写后来固定为 hinder，名词 hindrance 以相同的元音模式在旁边长成。"},{"era":"GERMANIC KIN","en":"German hinter and English behind belong to the same Germanic background of rear position.","cn":"德语 hinter 与英语 behind 属同一日耳曼语「后位」背景。"},{"era":"FALSE FRIENDS","en":"The noun hind, a female deer, is a different word and must not be read into the verb.","cn":"名词 hind 指雌鹿，是另一个词，不能读进这个动词里。"},{"era":"MODERN USE","en":"The verb now takes abstract objects such as progress, growth and coordination more often than physical ones.","cn":"今天这个动词更多接进展、增长、协调这类抽象宾语，而非具体物。"}]},"similar":{"note":{"en":"The first group looks close or shares the behind root; the second group names neighbouring ideas of obstruction.","cn":"第一组与「hinder」形近或共享「在后」词根；第二组是与「阻挡」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"hindrance","ipa":"/ˈhɪndrəns/","tag":"same root","definition":"The noun for an obstacle or the act of holding something back.","definitionCN":"指障碍物或拦截行为的名词。"},{"word":"hindered","ipa":"/ˈhɪndəd/","tag":"same root","definition":"The adjective for something that has been held back.","definitionCN":"形容词，指被拖住的。"},{"word":"behind","ipa":"/bɪˈhaɪnd/","tag":"same root","definition":"At the back of something, the spatial core of the verb.","definitionCN":"指在某物后面，正是这个动词的空间内核。"},{"word":"hind","ipa":"/haɪnd/","tag":"different root","definition":"A female deer, especially of red deer; a different word despite the spelling.","definitionCN":"指雌鹿，尤指红鹿；拼写近似但属另一个词。"},{"word":"hinterland","ipa":"/ˈhɪntəlænd/","tag":"Germanic kin","definition":"The land behind a coast or a settled area, from German hinter.","definitionCN":"指海岸或定居区后方的腹地，来自德语 hinter。"}]},{"heading":"NEAR MEANING","entries":[{"word":"impede","ipa":"/ɪmˈpiːd/","tag":"near meaning","definition":"To slow or block progress, often by an obstacle in the way.","definitionCN":"指拖慢或阻碍进展，常指路上有障碍。"},{"word":"obstruct","ipa":"/əbˈstrʌkt/","tag":"near meaning","definition":"To block a passage or a process deliberately.","definitionCN":"指故意堵塞通道或流程。"},{"word":"hamper","ipa":"/ˈhæmpə/","tag":"near meaning","definition":"To make movement or work awkward, as if by loose equipment.","definitionCN":"指使行动或工作别扭，像是被松散装备缠住。"},{"word":"restrict","ipa":"/rɪˈstrɪkt/","tag":"near meaning","definition":"To limit by rule rather than by obstacle.","definitionCN":"指用规则加以限制，而非用障碍。"},{"word":"delay","ipa":"/dɪˈleɪ/","tag":"near meaning","definition":"To make something happen later than planned.","definitionCN":"指使某事比计划更晚发生。"},{"word":"slow","ipa":"/sləʊ/","tag":"near meaning","definition":"To reduce speed without necessarily blocking the route.","definitionCN":"指降低速度，未必堵住路线。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the behind root, the old spelling pair behind and hinder, and the false friend hind.","cn":"正常联想使用「在后」词根、behind 与 hinder 这对古老拼写伙伴，以及易混的 hind。"},"normal":[{"en":"Hinder begins with the idea of behind, so it is to push something to the back of the queue.","cn":"这个词从「在后面」起步，也就是把某事推到队尾。"},{"en":"Behind and hinder share the same Germanic element of rear position.","cn":"behind 与 hinder 共享同一日耳曼语「后位」成分。"},{"en":"The noun is hindrance, not hinderance, and the vowel changes.","cn":"名词是 hindrance，不是 hinderance，元音有变化。"},{"en":"Projects are hindered by missing permits, not by enemies.","cn":"项目是被缺失的许可拖住的，而不是被敌人。"},{"en":"Hind, the female deer, is a different word and a common trap.","cn":"hind 指雌鹿，是另一个词，也是常见的陷阱。"}],"abstract":[{"en":"To hinder is to add distance between a person and the thing they were moving towards.","cn":"阻碍，就是在人和他要去的地方之间加上距离。"},{"en":"Most obstruction is not a wall but a small stone that makes every step cost more.","cn":"多数阻碍不是一堵墙，而是一块让每一步都更贵的小石头。"},{"en":"Whatever is put behind schedule was never stopped, only made late.","cn":"被放到进度后面的东西从未停止，只是被弄晚了。"}]},"examples":[{"en":"Heavy rain hindered the repair crews for two days.","cn":"大雨使维修队受阻两天。"},{"en":"Unclear ownership hindered the transfer of the land.","cn":"权属不清妨碍了这块土地的转让。"},{"en":"Lack of sleep hindered his concentration during the test.","cn":"睡眠不足妨碍了他在测试中的专注。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「辛德」——路中一块落石，后面的人侧身挪：阻碍、拖慢","word":"hinder"},"root":"古英语 hinder「在后面」→ hindrian「拦阻、耽搁」；属日耳曼语，与 behind 同出「后位」义。名词 hindrance 为同族派生。","sensesIntro":{"en":"Eight senses all put an obstacle in a path: a project, movement, growth, attention, a plan, a living thing, a task and coordination.","cn":"八个义项都在一条路径上放置障碍：项目、移动、增长、注意力、计划、生物体、任务与协调。"},"semanticMap":{"core":{"en":"CORE IMAGE: a stone sits in a narrow path and everyone behind it must edge past sideways.","cn":"核心意象：一块落石横在窄路上，后面的人只能侧身挪过去。"},"chain":["BEHIND","OBSTACLE","PROGRESS","SPEED","GROWTH","OUTCOME"],"branches":[{"senses":"01 · 03","en":"THE SCHEDULE SLIPS: a project or an economy loses its forward pace.","cn":"进度滑落：项目或经济失去向前的速度。"},{"senses":"02","en":"THE PATH IS BLOCKED: a body or a vehicle cannot move freely.","cn":"路径被堵：人或车辆无法自由移动。"},{"senses":"04","en":"THE ATTENTION IS CUT: noise or interruption breaks the narrow channel of focus.","cn":"注意力被截断：噪声或打断切断专注这条窄通道。"},{"senses":"05","en":"THE DECISION IS STALLED: procedure is used to hold a proposal where it stands.","cn":"决定被卡住：程序被用来把提案按在原处。"},{"senses":"06 · 07 · 08","en":"THE PROCESS UNDERPERFORMS: growth, a task or coordination finishes below its natural level.","cn":"过程发挥不足：生长、任务或协调低于其自然水平。"}]},"affixes":{"intro":{"en":"Hinder is a Germanic verb, so its affixes are English endings rather than Latin ones.","cn":"这是一个日耳曼语动词，其词缀是英语词尾而非拉丁词缀。"},"latinIntro":{"en":"There is no Latin source for this verb; the Latin column stays empty instead of borrowing unrelated forms.","cn":"这个动词没有拉丁语来源，拉丁部分留空，不借无关形式来填。"},"items":[{"word":"hinder","structure":"Old English adverb","meaning":"behind, in the rear","meaningCN":"在后面；向后","example":"The adverb is the spatial seed of the verb.","exampleCN":"这个副词是动词的空间种子。"},{"word":"-ian","structure":"Old English verb ending","meaning":"to make or do","meaningCN":"做；使","example":"It formed hindrian from the adverb.","exampleCN":"它由副词构成 hindrian。"},{"word":"behind","structure":"English adverb","meaning":"at the back of","meaningCN":"在……后面","example":"It keeps the same rear picture in modern English.","exampleCN":"它在现代英语里保留同一个「后位」画面。"},{"word":"-ance","structure":"noun ending","meaning":"state or result","meaningCN":"状态；结果","example":"It forms hindrance, the standard noun.","exampleCN":"它构成标准名词 hindrance。"},{"word":"-ed","structure":"past participle ending","meaning":"having undergone","meaningCN":"已……的","example":"It forms hindered.","exampleCN":"它构成 hindered。"},{"word":"-ing","structure":"adjective ending","meaning":"in the course of","meaningCN":"正在……的","example":"It forms hindering.","exampleCN":"它构成 hindering。"},{"word":"-er","structure":"agent noun ending","meaning":"the one who acts","meaningCN":"施动者","example":"It forms the rare hinderer.","exampleCN":"它构成少用的 hinderer。"},{"word":"-ly","structure":"adverb ending","meaning":"in a given manner","meaningCN":"以……方式","example":"It forms the rare hinderingly.","exampleCN":"它构成少用的 hinderingly。"}],"latinEntries":[],"derivatives":[{"word":"hindrance","pos":"n.","zh":"由该动词加表示性质或结果的名词尾构成，义为「阻碍；障碍物」"},{"word":"hindered","pos":"adj.","zh":"由该动词加已然词尾构成，义为「受妨碍的」"},{"word":"hinderer","pos":"n.","zh":"由该动词加表示施动者的名词尾构成，义为「阻碍者」（少用）"},{"word":"hinderingly","pos":"adv.","zh":"由形容词加副词词尾构成，义为「以妨碍的方式」（少用）"}]}},{"word":"intensify","ipa_uk":"/ɪnˈtensɪfaɪ/","ipa_us":"/ɪnˈtensəfaɪ/","definition_zh":"加强；加剧；强化；增强","definition_en":"to make something stronger, sharper or more concentrated, or to become so","core_image":"炉门被拉开，风箱越推越快，火苗从橙红窜成刺眼的白","scene":"谈判没有进展，双方反而把条件提得更高，气氛越来越紧。Both sides intensify pressure as the talks stall.","sceneCN":"这里指把压力加得更强（第 2 个义项：加剧冲突或压力）；句意为谈判停滞后双方都在加大压力。图中可辨识物件：被拉开的炉门、加速的风箱、窜高的火焰。","pos":[{"tag":"v.","zh":"加强；加剧；强化"}],"collocations":[{"phrase":"intensify efforts","zh":"加大力度"},{"phrase":"intensify pressure","zh":"加大压力"},{"phrase":"intensify competition","zh":"加剧竞争"},{"phrase":"intensify the conflict","zh":"加剧冲突"},{"phrase":"intensify cooperation","zh":"加强合作"},{"phrase":"intensify colours","zh":"使色彩更浓"},{"phrase":"intensify the search","zh":"加紧搜寻"}],"forms":[{"label":"动词原形","form":"intensify"},{"label":"第三人称单数","form":"intensifies"},{"label":"过去式","form":"intensified"},{"label":"过去分词","form":"intensified"},{"label":"现在分词","form":"intensifying"},{"label":"名词","form":"intensification"},{"label":"名词","form":"intensity"},{"label":"形容词","form":"intense"}],"derivatives":[{"word":"intensification","pos":"n.","zh":"由该动词加表示动作结果的名词尾构成，义为「加强；加剧」"},{"word":"intensifier","pos":"n.","zh":"由该动词加表示施动者或工具的名词尾构成，义为「加强成分；增强剂」"},{"word":"intensity","pos":"n.","zh":"由同一拉丁词干加表示性质的名词尾构成，义为「强度」"},{"word":"intense","pos":"adj.","zh":"由同一拉丁词干构成的形容词，义为「强烈的；紧张的」"},{"word":"intensive","pos":"adj.","zh":"由同一词干加表示倾向的形容词尾构成，义为「密集的；加强的」"}],"senses":[{"no":"01","title":"To increase strength","titleCN":"加强力度","definition":"to raise the strength, force or level of an action or quality","definitionCN":"提高某一行动或性质的强度、力度或水平","example":"The crew intensified the light before the final inspection.","exampleCN":"在最后检查前，班组把照明加强了。","why":"The root means stretched tight, and intensifying is pulling that tension higher.","whyCN":"词根意为「拉紧」，加强就是把那股张力再拉高。"},{"no":"02","title":"To sharpen a conflict","titleCN":"加剧冲突或压力","definition":"to make a dispute, pressure or hostility more acute","definitionCN":"使争端、压力或敌意更尖锐","example":"Sanctions intensified the dispute over the border.","exampleCN":"制裁加剧了边境争端。","why":"Conflict is tension between two sides, and the verb raises the tension.","whyCN":"冲突是两方之间的张力，这个动词把张力调高。"},{"no":"03","title":"To heighten a feeling","titleCN":"增强感受","definition":"to make an emotion or sensation more vivid or harder to ignore","definitionCN":"使情绪或感觉更鲜明、更难忽视","example":"The silence intensified the fear in the room.","exampleCN":"沉默让屋里的恐惧更强烈。","why":"Feelings are measured by how tightly they hold attention, so more tension means more feeling.","whyCN":"情绪以攥住注意力的松紧来衡量，张力越大，感受越强。"},{"no":"04","title":"To step up an effort","titleCN":"加大行动力度","definition":"to make work or a campaign more concentrated and frequent","definitionCN":"使工作或运动更集中、更频繁","example":"Volunteers intensified the search after nightfall.","exampleCN":"入夜后，志愿者加紧搜寻。","why":"Effort has a dial, and the verb turns it up rather than changing its direction.","whyCN":"努力有一个旋钮，这个动词把它拧大，而不是换方向。"},{"no":"05","title":"To raise scrutiny or attention","titleCN":"提高关注度","definition":"to make examination, attention or criticism closer and more constant","definitionCN":"使审视、关注或批评更贴近、更持续","example":"Regulators intensified checks on the export route.","exampleCN":"监管机构加强了对出口路线的检查。","why":"Scrutiny is pressure applied to a process, and the verb says the pressure rose.","whyCN":"审视是对流程施加的压力，这个动词说压力升高了。"},{"no":"06","title":"To strengthen an effect","titleCN":"强化效果","definition":"to make the visible or audible effect of something more pronounced","definitionCN":"使某物的视觉或听觉效果更明显","example":"The new coating intensified the contrast of the print.","exampleCN":"新涂层增强了印刷的对比度。","why":"Effects are read by the senses, and intensifying pushes the reading further from neutral.","whyCN":"效果由感官读取，加强就是把读数推得离中性更远。"},{"no":"07","title":"To concentrate a signal or colour","titleCN":"增强信号或色彩","definition":"to increase the concentration of light, sound or colour in a given area","definitionCN":"提高某一区域内光、声或颜色的浓度","example":"The filter intensified the red without changing the shape.","exampleCN":"滤镜让红色更浓，却没有改变形状。","why":"Technical optics use the verb for concentration, the same tightening applied to a beam.","whyCN":"技术光学用这个动词表示「集中」，即把同一股收紧作用用到光束上。"},{"no":"08","title":"To focus attention sharply","titleCN":"使注意力更集中","definition":"to make focus or concentration narrower and more forceful","definitionCN":"使专注或集中更窄、更有力","example":"A deadline intensified her focus on the last chapter.","exampleCN":"截止日期让她把注意力更集中在最后一章。","why":"A narrower beam is a stronger beam, which is why focus and intensity share a vocabulary.","whyCN":"光束越窄越强，所以「聚焦」与「强度」共用一套词。"}],"etymology":{"intro":{"en":"Intensify is formed in English from intense and the suffix -ify. Intense goes back to Latin intensus, stretched, the participle of intendere, to stretch toward.","cn":"这个词在英语里由 intense 加后缀 -ify 构成；intense 可追溯到拉丁语 intensus「拉紧」，即 intendere「朝……伸展」的分词。"},"items":[{"era":"LATIN TENDERE","en":"Tendere meant to stretch, and it supplies intend, tend, tension and intense alike.","cn":"这个词意为「伸展」，供应了 intend、tend、tension 与 intense。"},{"era":"LATIN INTENDERE","en":"Intendere meant to stretch toward or direct attention to, with the prefix marking direction.","cn":"这个词意为朝某处伸展或把注意力指向某处，前缀标出方向。"},{"era":"LATIN INTENSUS","en":"The participle meant stretched tight, and that physical tightness became the English sense of strong.","cn":"这个分词意为「拉得很紧」，而这种物理紧绷变成英语的「强烈」。"},{"era":"ENGLISH INTENSE","en":"English adopted intense through French, using it for heat, colour, feeling and attention.","cn":"英语经法语引入 intense，用于热度、颜色、情绪与注意力。"},{"era":"THE -IFY SUFFIX","en":"The suffix comes from Latin facere, to make, so intensify literally means to make intense.","cn":"后缀出自拉丁语 facere「做」，所以这个词字面就是「使强烈」。"},{"era":"ENGLISH, 18TH CENTURY","en":"The verb is recorded from the eighteenth century; the exact first date is uncertain in the sources.","cn":"这个动词自十八世纪有记录，确切首见年代在各家资料中不确定。"}]},"similar":{"note":{"en":"The first group shares the tense stem or looks close; the second group names neighbouring ideas of increase.","cn":"第一组与「intensify」共享「拉紧」词干或只是形近；第二组是与「增强」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"intensity","ipa":"/ɪnˈtensəti/","tag":"same root","definition":"The noun for the strength or force of something.","definitionCN":"指某物强度或力度的名词。"},{"word":"intensification","ipa":"/ɪnˌtensɪfɪˈkeɪʃn/","tag":"same root","definition":"The noun for the act of making something stronger.","definitionCN":"指加强这一行为的名词。"},{"word":"intense","ipa":"/ɪnˈtens/","tag":"same root","definition":"The adjective meaning very strong or very serious.","definitionCN":"形容词，指非常强烈或非常严肃的。"},{"word":"intent","ipa":"/ɪnˈtent/","tag":"same root","definition":"Purpose or determination, from the same stretching verb.","definitionCN":"指意图或决心，同出「伸展」动词。"},{"word":"intend","ipa":"/ɪnˈtend/","tag":"same root","definition":"To plan or mean to do, literally to stretch toward.","definitionCN":"指打算，字面是「朝……伸展」。"},{"word":"tension","ipa":"/ˈtenʃn/","tag":"same root","definition":"The state of being stretched, the physical source of the family.","definitionCN":"指被拉紧的状态，是这一族词的物理源头。"}]},{"heading":"NEAR MEANING","entries":[{"word":"strengthen","ipa":"/ˈstreŋθn/","tag":"near meaning","definition":"To make stronger, the broad neutral verb.","definitionCN":"指使更强，是宽泛中性的说法。"},{"word":"heighten","ipa":"/ˈhaɪtn/","tag":"near meaning","definition":"To raise the level of a feeling or effect.","definitionCN":"指提高情绪或效果的强度。"},{"word":"amplify","ipa":"/ˈæmplɪfaɪ/","tag":"near meaning","definition":"To make larger or louder, especially a signal.","definitionCN":"指放大或增强，尤指信号。"},{"word":"escalate","ipa":"/ˈeskəleɪt/","tag":"near meaning","definition":"To become or make more intense, often of conflict.","definitionCN":"指升级、加剧，多用于冲突。"},{"word":"deepen","ipa":"/ˈdiːpən/","tag":"near meaning","definition":"To make a feeling or problem more profound.","definitionCN":"指使情绪或问题更深。"},{"word":"compound","ipa":"/kəmˈpaʊnd/","tag":"near meaning","definition":"To add to something, often making it worse.","definitionCN":"指叠加，常使情况更糟。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the stretched-tight participle, the -ify suffix and the fixed objects that pair with the verb.","cn":"正常联想使用「拉紧」的分词、-ify 后缀，以及与这个动词固定的宾语。"},"normal":[{"en":"The participle meant stretched tight, so intensify is to tighten the string further.","cn":"分词意为「拉紧」，所以这个词就是把弦再绞紧一点。"},{"en":"Intense, intensity, tension and intend all come from the same stretching verb.","cn":"intense、intensity、tension、intend 都出自同一个「伸展」动词。"},{"en":"The -ify suffix means to make, so the verb means to make intense.","cn":"-ify 后缀意为「使」，所以动词就是「使强烈」。"},{"en":"Pressure, efforts, competition and scrutiny are its most common objects.","cn":"压力、努力、竞争、审视是它最常见的宾语。"},{"en":"It takes -ies, -ied and -ying, and the y never doubles.","cn":"第三人称、过去式、现在分词依次换词尾，词干的字母不双写。"}],"abstract":[{"en":"Intensity is not more of the same thing; it is the same thing held tighter.","cn":"强度不是更多同样的东西，而是同样的东西被攥得更紧。"},{"en":"A beam made narrower is a beam made stronger, and that is the whole word.","cn":"光束变窄就是变强，这就是这个词的全部。"},{"en":"Pressure intensified is not pressure doubled; it is pressure that no longer leaves room to breathe.","cn":"压力加大不是压力翻倍，而是不再留出喘息的余地。"}]},"examples":[{"en":"The company intensified training after the second accident.","cn":"第二次事故之后，公司加强了培训。"},{"en":"Wind intensified through the afternoon and closed the ferry route.","cn":"午后风力加大，渡轮航线因此关闭。"},{"en":"The debate intensified as new evidence appeared.","cn":"随着新证据出现，争论更加激烈。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「因坦西法伊」——风箱越推越快，火苗窜成白色：加强、加剧","word":"intensify"},"root":"拉丁语 tendere「伸展」→ intendere「朝……伸展」→ intensus「拉紧的」→ 法语 intense；英语十八世纪以 intense + -ify 构成动词，首见年代不确定。","sensesIntro":{"en":"Eight senses all tighten one tension: strength, conflict, feeling, effort, scrutiny, effect, signal and focus.","cn":"八个义项都在收紧同一股张力：力度、冲突、感受、努力、审视、效果、信号与专注。"},"semanticMap":{"core":{"en":"CORE IMAGE: the bellows speed up and the flame turns from orange to a blinding white.","cn":"核心意象：风箱越推越快，火苗从橙红变成刺眼的白。"},"chain":["TENSION","STRENGTH","CONFLICT","FEELING","EFFORT","EFFECT"],"branches":[{"senses":"01","en":"THE FORCE RISES: an action or quality is turned up on its own dial.","cn":"力量上升：某项行动或性质在自己的旋钮上被拧大。"},{"senses":"02 · 05","en":"THE PRESSURE TIGHTENS: a dispute or a system of checks is pressed harder.","cn":"压力收紧：争端或审查体系被压得更紧。"},{"senses":"03","en":"THE FEELING SHARPENS: emotion becomes too vivid to ignore.","cn":"感受变锐：情绪鲜明到无法忽视。"},{"senses":"04","en":"THE EFFORT THICKENS: work is made more frequent and more concentrated.","cn":"努力变密：工作变得更频繁、更集中。"},{"senses":"06 · 07 · 08","en":"THE EFFECT CONCENTRATES: contrast, colour or focus is brought to a narrower, stronger beam.","cn":"效果集中：对比、色彩或专注被收成一束更窄更强的光。"}]},"affixes":{"intro":{"en":"Intensify joins a Latin participle to an English suffix, so its affixes are the pieces of that joining.","cn":"这个词把一个拉丁分词接在一个英语后缀上，其词缀就是这次接合的两端。"},"latinIntro":{"en":"Latin supplies tendere, intendere and intensus; facere supplies the suffix, and every piece is well recorded.","cn":"拉丁语提供了 tendere、intendere、intensus；facere 提供后缀，每个部件都有清楚记录。"},"items":[{"word":"tendere","structure":"Latin verb","meaning":"to stretch","meaningCN":"伸展","example":"The verb is the physical source of tension.","exampleCN":"这个动词是「张力」的物理源头。"},{"word":"in-","structure":"Latin prefix","meaning":"toward, into","meaningCN":"向；入","example":"It marks direction in intendere.","exampleCN":"它在 intendere 中标出方向。"},{"word":"intensus","structure":"Latin participle","meaning":"stretched tight","meaningCN":"拉紧的","example":"The participle became the English adjective intense.","exampleCN":"这个分词变成英语形容词 intense。"},{"word":"-ify","structure":"verb suffix from facere","meaning":"to make","meaningCN":"使……","example":"It turns the adjective into a verb of increase.","exampleCN":"它把形容词变成表示增强的动词。"},{"word":"-fic-","structure":"Latin root in the suffix","meaning":"to make","meaningCN":"做；使","example":"It appears in words such as intensify and amplify.","exampleCN":"它出现在 intensify、amplify 这类词里。"},{"word":"-ation","structure":"action-result noun ending","meaning":"the act or result","meaningCN":"动作或结果","example":"It forms intensification.","exampleCN":"它构成 intensification。"},{"word":"-er","structure":"agent or instrument ending","meaning":"the one or the thing that acts","meaningCN":"施动者或工具","example":"It forms intensifier.","exampleCN":"它构成 intensifier。"},{"word":"-ity","structure":"quality noun ending","meaning":"state or quality","meaningCN":"性质；状态","example":"It forms intensity.","exampleCN":"它构成 intensity。"},{"word":"-ive","structure":"adjective ending","meaning":"tending toward","meaningCN":"倾向于……的","example":"It forms intensive.","exampleCN":"它构成 intensive。"},{"word":"-sion","structure":"noun ending","meaning":"state of being stretched","meaningCN":"被拉伸的状态","example":"It appears in tension, the oldest family member.","exampleCN":"它出现在 tension 这个最老的家族成员里。"}],"latinEntries":[{"word":"tendere","structure":"Latin verb","meaning":"to stretch","meaningCN":"伸展"},{"word":"intendere","structure":"Latin verb","meaning":"to stretch toward","meaningCN":"朝……伸展"},{"word":"intensus","structure":"Latin participle","meaning":"stretched tight","meaningCN":"拉紧的"},{"word":"facere","structure":"Latin verb","meaning":"to make","meaningCN":"做；使"}],"derivatives":[{"word":"intensification","pos":"n.","zh":"由该动词加表示动作结果的名词尾构成，义为「加强；加剧」"},{"word":"intensifier","pos":"n.","zh":"由该动词加表示施动者或工具的名词尾构成，义为「加强成分」"},{"word":"intensity","pos":"n.","zh":"由同一拉丁词干加表示性质的名词尾构成，义为「强度」"},{"word":"intensive","pos":"adj.","zh":"由同一词干加表示倾向的形容词尾构成，义为「密集的」"}]}},{"word":"mitigate","ipa_uk":"/ˈmɪtɪɡeɪt/","ipa_us":"/ˈmɪtəɡeɪt/","definition_zh":"减轻；缓和；缓解；使缓和","definition_en":"to make damage, risk or hardship less severe, especially by taking action in advance","core_image":"洪水到来前，人在堤脚铺开一层缓冲石，浪头拍到堤面时被卸掉一半的力","scene":"工程开工前先改设计，把可能出现的沉降控制在可接受范围内。Careful design can mitigate the risk of settlement.","sceneCN":"这里指提前降低风险程度（第 2 个义项：缓和冲击或风险）；句意为精心设计能缓和沉降风险。图中可辨识物件：堤脚铺开的缓冲石、拍上堤面的浪头、卸力后散开的水花。","pos":[{"tag":"v.","zh":"减轻；缓和；缓解"}],"collocations":[{"phrase":"mitigate the impact","zh":"减轻影响"},{"phrase":"mitigate risk","zh":"降低风险"},{"phrase":"mitigate climate change","zh":"减缓气候变化"},{"phrase":"mitigate damage","zh":"减轻损害"},{"phrase":"mitigate the effects","zh":"缓和后果"},{"phrase":"mitigate losses","zh":"减少损失"},{"phrase":"mitigate the pressure","zh":"缓解压力"}],"forms":[{"label":"动词原形","form":"mitigate"},{"label":"第三人称单数","form":"mitigates"},{"label":"过去式","form":"mitigated"},{"label":"过去分词","form":"mitigated"},{"label":"现在分词","form":"mitigating"},{"label":"名词","form":"mitigation"},{"label":"形容词","form":"mitigating"},{"label":"形容词","form":"unmitigated"}],"derivatives":[{"word":"mitigation","pos":"n.","zh":"由该动词加表示动作结果的名词尾构成，义为「减轻；缓解」"},{"word":"mitigating","pos":"adj.","zh":"由该动词加形容词后缀构成，义为「起缓和作用的」，法律中指减轻情节"},{"word":"mitigative","pos":"adj.","zh":"由该动词加表示倾向的形容词尾构成，义为「缓解性的」"},{"word":"mitigator","pos":"n.","zh":"由该动词加表示施动者的名词尾构成，义为「缓解者」（少用）"},{"word":"unmitigated","pos":"adj.","zh":"由否定前缀加已然词构成，义为「未减弱的；彻底的」"}],"senses":[{"no":"01","title":"To reduce harm","titleCN":"减轻损害","definition":"to lower the amount of harm that an event or action causes","definitionCN":"降低某一事件或行为造成的损害量","example":"Early warning mitigated the damage from the flood.","exampleCN":"提前预警减轻了洪水造成的损害。","why":"The root is mild, and making harm mild is the whole idea of the word.","whyCN":"词根是「温和」，把伤害化温和就是这个词的全部意思。"},{"no":"02","title":"To lower a risk","titleCN":"降低风险","definition":"to reduce the probability or severity of a future danger","definitionCN":"降低未来危险发生的可能或严重程度","example":"Regular inspection mitigates the risk of failure.","exampleCN":"定期检查降低了失效风险。","why":"Risk is a future weight, and mitigation is placed before it arrives.","whyCN":"风险是未来的重量，而缓解是在它到来之前先布置。"},{"no":"03","title":"To ease pressure or pain","titleCN":"缓解压力或痛苦","definition":"to make a burden or a sensation less severe for those experiencing it","definitionCN":"让承受者的负担或感受变得不那么严重","example":"Respite care mitigated the strain on the family.","exampleCN":"喘息照护缓解了这个家庭的负担。","why":"This is the everyday use, where the mild root meets a person's experience.","whyCN":"这是日常用法，温和的词根与人切身的感受相遇。"},{"no":"04","title":"To reduce a penalty","titleCN":"减轻处罚或责任","definition":"to lower the severity of a punishment or a legal liability","definitionCN":"降低处罚或法律责任的严厉程度","example":"The court mitigated the sentence because of his cooperation.","exampleCN":"考虑到他的配合，法院减轻了判决。","why":"Law treats a penalty as a weight that may be reduced, hence mitigation in sentencing.","whyCN":"法律把处罚当作可以减轻的重量，所以量刑中有「减轻」。"},{"no":"05","title":"To slow climate change","titleCN":"减缓气候变化","definition":"to reduce the rate or scale of a long-term environmental change","definitionCN":"降低长期环境变化的速度或规模","example":"Cutting emissions mitigates but does not reverse warming.","exampleCN":"减排能减缓变暖，却不能逆转它。","why":"Climate writing uses the verb for slowing a process, not for undoing it.","whyCN":"气候写作把这个动词用于「放慢过程」，而不是「撤回结果」。"},{"no":"06","title":"To cut a loss or cost","titleCN":"减少损失或成本","definition":"to make the financial or material cost of an event smaller","definitionCN":"降低某一事件在金钱或材料上的代价","example":"The reserve fund mitigated the loss from the cancelled order.","exampleCN":"储备金减少了订单取消带来的损失。","why":"Losses are counted, and to mitigate is to bring the count down.","whyCN":"损失是要计数的，而缓解就是把计数降下来。"},{"no":"07","title":"To soften a conflict","titleCN":"调和矛盾","definition":"to make a dispute or a disagreement less sharp without settling it","definitionCN":"使争端或分歧不那么尖锐，但不一定解决它","example":"A neutral chair mitigated the tension in the meeting.","exampleCN":"一位中立的主持人缓和了会上的紧张。","why":"Conflict is heat, and the word lowers it rather than putting it out.","whyCN":"冲突是热度，这个词是降温而非灭火。"},{"no":"08","title":"To relieve symptoms","titleCN":"减轻症状","definition":"to make the signs of an illness less troublesome while the cause remains","definitionCN":"在病因仍在的情况下，使疾病表现不那么难受","example":"The cream mitigates itching but does not treat the cause.","exampleCN":"这种药膏能减轻瘙痒，却不处理病因。","why":"Medicine separates relief from cure, and mitigation sits firmly on the relief side.","whyCN":"医学区分缓解与治愈，而缓解稳稳站在「缓解」这一边。"}],"etymology":{"intro":{"en":"Mitigate comes from Latin mitigare, to soften or make mild, from mitis, mild. The second element is generally taken to be agere, to do, though the exact formation is debated.","cn":"这个词来自拉丁语 mitigare「使软、使温和」，出自 mitis「温和」；第二部分一般认为是 agere「做」，但确切构词方式有争议。"},"items":[{"era":"LATIN MITIS","en":"Mitis meant mild, soft or ripe, and it described both weather and temperament.","cn":"这个词意为温和、柔软或成熟，既形容天气也形容性情。"},{"era":"LATIN MITIGARE","en":"The verb meant to soften, soothe or appease, and it was used of anger, pain and harsh measures.","cn":"这个动词意为使软、安抚、平息，用于怒气、疼痛与严厉措施。"},{"era":"THE SECOND ELEMENT","en":"The tail of mitigare is generally explained as agere, to do, but the exact formation is debated, so its source is uncertain.","cn":"词尾一般解释为 agere「做」，但确切构词有争议，宜标为来源不确定。"},{"era":"ENGLISH, 16TH CENTURY","en":"English adopted the verb in the sixteenth century, first for tempering harshness and later for reducing harm.","cn":"英语十六世纪采用这个动词，先指使严厉变缓，后指减少损害。"},{"era":"LEGAL AND CLIMATE USE","en":"Sentencing and climate policy both gave the verb fixed objects, penalty and emissions.","cn":"量刑与气候政策都给这个动词添了固定宾语：刑罚与排放。"},{"era":"FALSE TWIN","en":"The verb militate, to have force against, comes from miles, a soldier, and must not be confused with mitigate.","cn":"militate「产生不利作用」出自 miles「士兵」，不可与这个词混淆。"}]},"similar":{"note":{"en":"The first group shares the mild stem or looks close; the second group names neighbouring ideas of relief.","cn":"第一组与「mitigate」共享「温和」词干或只是形近；第二组是与「缓解」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"mitigation","ipa":"/ˌmɪtɪˈɡeɪʃn/","tag":"same root","definition":"The noun for the act of making something less severe.","definitionCN":"指减轻这一行为的名词。"},{"word":"mitigating","ipa":"/ˈmɪtɪɡeɪtɪŋ/","tag":"same root","definition":"The adjective for circumstances that reduce blame.","definitionCN":"形容词，指减轻责任的（情节）。"},{"word":"unmitigated","ipa":"/ʌnˈmɪtɪɡeɪtɪd/","tag":"same root","definition":"Not softened at all, hence complete or absolute.","definitionCN":"指完全未减弱的，引申为彻底的。"},{"word":"militate","ipa":"/ˈmɪlɪteɪt/","tag":"different root","definition":"To work against something, from miles, a soldier; a classic confusion.","definitionCN":"指产生不利作用，出自「士兵」，是经典的易混词。"},{"word":"mediate","ipa":"/ˈmiːdieɪt/","tag":"different root","definition":"To intervene between parties, from medius, middle.","definitionCN":"指居中调停，出自「中间」。"}]},{"heading":"NEAR MEANING","entries":[{"word":"alleviate","ipa":"/əˈliːvieɪt/","tag":"near meaning","definition":"To lighten pain or hardship, often after the fact.","definitionCN":"指减轻痛苦或困苦，多在事后。"},{"word":"reduce","ipa":"/rɪˈdjuːs/","tag":"near meaning","definition":"To bring down an amount, the broad neutral verb.","definitionCN":"指降低数量，是宽泛中性的说法。"},{"word":"lessen","ipa":"/ˈlesn/","tag":"near meaning","definition":"To make smaller in degree or amount.","definitionCN":"指在程度或数量上变小。"},{"word":"temper","ipa":"/ˈtempə/","tag":"near meaning","definition":"To soften the force of something by mixing or moderating.","definitionCN":"指通过掺和或节制削弱力度。"},{"word":"ease","ipa":"/iːz/","tag":"near meaning","definition":"To make something less difficult or painful.","definitionCN":"指使不那么困难或痛苦。"},{"word":"soften","ipa":"/ˈsɒfn/","tag":"near meaning","definition":"To make less hard or less severe, the literal root picture.","definitionCN":"指使变软或变缓，正是词根的字面画面。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the mild root, the legal phrase mitigating circumstances, and the false twin militate.","cn":"正常联想使用「温和」词根、法律短语「减轻情节」，以及易混的 militate。"},"normal":[{"en":"Mitis is mild, so mitigate is to take the edge off something harsh.","cn":"mitis 是「温和」，所以这个词就是把锋利的地方磨钝。"},{"en":"Mitigation is what you do before the flood, not after it.","cn":"缓解是在洪水到来之前做的，不是之后。"},{"en":"Law speaks of mitigating circumstances that lower a penalty.","cn":"法律说「减轻情节」，用来降低处罚。"},{"en":"Militate looks similar but comes from soldier and means to work against.","cn":"militate 形似，却出自「士兵」，意为产生不利作用。"},{"en":"Climate policy pairs mitigate with adapt: one slows the change, the other lives with it.","cn":"气候政策把「减缓」与「适应」配对：一个放慢变化，一个与之共存。"}],"abstract":[{"en":"To mitigate is to accept that the harm will arrive and decide how much of it to absorb.","cn":"缓解，就是承认伤害会来，然后决定吸收掉其中多少。"},{"en":"A cushion does not stop the blow; it lengthens the time over which the blow is felt.","cn":"缓冲垫并不挡住打击，它只是拉长感受这一击的时间。"},{"en":"Whatever cannot be removed can still be made mild, and the word lives in that remaining room.","cn":"去不掉的东西仍可变得温和，这个词就活在那点剩下的余地。"}]},"examples":[{"en":"Planting trees along the bank mitigated erosion after the floods.","cn":"沿河岸植树减轻了洪水后的侵蚀。"},{"en":"The team mitigated the risk by testing each joint twice.","cn":"团队把每个接缝测了两遍，以降低风险。"},{"en":"The ruling mitigated the fine because the firm reported early.","cn":"由于该公司主动报告，裁决减轻了罚款。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「米提盖特」——堤脚先铺缓冲石，浪头拍到就卸一半：减轻、缓和","word":"mitigate"},"root":"拉丁语 mitis「温和」→ mitigare「使软、使缓和」；第二成分一般认为是 agere「做」，但确切构词有争议，构成成分来源不确定。英语十六世纪引入。","sensesIntro":{"en":"Eight senses all take the edge off something: harm, risk, pressure, penalty, warming, loss, conflict and symptoms.","cn":"八个义项都在磨钝某个东西的锋边：损害、风险、压力、处罚、变暖、损失、冲突与症状。"},"semanticMap":{"core":{"en":"CORE IMAGE: buffer stones are laid before the flood, and the wave spends half its force on them.","cn":"核心意象：洪水到来前先铺缓冲石，浪头把一半的力耗在石上。"},"chain":["MILD","DAMAGE","RISK","PRESSURE","PENALTY","PROCESS"],"branches":[{"senses":"01 · 06","en":"THE HARM IS CUT: damage or financial loss is counted lower than it would have been.","cn":"损害被削：实际损害或金钱损失比原本更低。"},{"senses":"02","en":"THE FUTURE IS CUSHIONED: a danger is made less likely or less severe before it arrives.","cn":"未来被垫住：危险在到来之前就被降低可能或严重度。"},{"senses":"03 · 08","en":"THE BURDEN IS LIGHTENED: strain and symptoms are made easier to carry.","cn":"负担变轻：压力与症状变得较易承受。"},{"senses":"04","en":"THE PENALTY IS SOFTENED: a punishment or liability loses part of its weight.","cn":"处罚被软化：刑罚或责任卸去一部分重量。"},{"senses":"05 · 07","en":"THE PROCESS IS SLOWED: warming or a dispute loses heat without being extinguished.","cn":"过程被放慢：变暖或争端降了温，却没有被扑灭。"}]},"affixes":{"intro":{"en":"Mitigate is a Latin verb whose stem is short but whose endings have produced a whole English family.","cn":"这是一个拉丁动词，词干很短，但词尾在英语里长出了整族词。"},"latinIntro":{"en":"Latin supplies mitis and mitigare; the second element of the verb is debated, so it is described rather than asserted.","cn":"拉丁语提供了 mitis 与 mitigare；动词的第二成分有争议，因此只作描述，不作断言。"},"items":[{"word":"mitis","structure":"Latin adjective","meaning":"mild, soft, ripe","meaningCN":"温和的；软的","example":"The adjective covered weather, fruit and temperament.","exampleCN":"这个形容词涵盖天气、果实与性情。"},{"word":"mitigare","structure":"Latin verb from mitis","meaning":"to soften, soothe","meaningCN":"使软；安抚","example":"The verb was used of anger and pain.","exampleCN":"这个动词用于怒气与疼痛。"},{"word":"-ate","structure":"Latin verb ending","meaning":"to make or cause","meaningCN":"使……；做……","example":"It marks the English verb.","exampleCN":"它标明英语动词。"},{"word":"-ion","structure":"action-result noun ending","meaning":"the act or result","meaningCN":"动作或结果","example":"It forms mitigation.","exampleCN":"它构成 mitigation。"},{"word":"-ing","structure":"adjective ending","meaning":"in the course of","meaningCN":"正在……的","example":"It forms mitigating circumstances.","exampleCN":"它构成 mitigating circumstances。"},{"word":"-ive","structure":"adjective ending","meaning":"tending toward","meaningCN":"倾向于……的","example":"It forms mitigative.","exampleCN":"它构成 mitigative。"},{"word":"un-","structure":"negative prefix","meaning":"not","meaningCN":"不；未","example":"It forms unmitigated.","exampleCN":"它构成 unmitigated。"},{"word":"-or","structure":"agent noun ending","meaning":"the one who acts","meaningCN":"施动者","example":"It forms the rare mitigator.","exampleCN":"它构成少用的 mitigator。"},{"word":"militate","structure":"Latin-derived look-alike","meaning":"to work against","meaningCN":"产生不利作用","example":"It comes from soldier, not from mild.","exampleCN":"它出自「士兵」，而非「温和」。"}],"latinEntries":[{"word":"mitis","structure":"Latin adjective","meaning":"mild, soft","meaningCN":"温和的；软的"},{"word":"mitigare","structure":"Latin verb","meaning":"to soften, soothe","meaningCN":"使软；安抚"},{"word":"mitigatio","structure":"Latin noun","meaning":"a softening","meaningCN":"缓和"}],"derivatives":[{"word":"mitigation","pos":"n.","zh":"由该动词加表示动作结果的名词尾构成，义为「减轻；缓解」"},{"word":"mitigating","pos":"adj.","zh":"由该动词加形容词后缀构成，义为「起缓和作用的」"},{"word":"mitigative","pos":"adj.","zh":"由该动词加表示倾向的形容词尾构成，义为「缓解性的」"},{"word":"unmitigated","pos":"adj.","zh":"由否定前缀加已然词构成，义为「未减弱的；彻底的」"},{"word":"mitigator","pos":"n.","zh":"由该动词加表示施动者的名词尾构成，义为「缓解者」（少用）"}]}},{"word":"offset","ipa_uk":"/ˈɒfset/","ipa_us":"/ˈɑːfset/","definition_zh":"抵消；补偿；弥补；对冲；偏移；胶印","definition_en":"to balance one cost, effect or influence against another so that the net result is reduced","core_image":"天平一端压着涨价账单，另一端放上节省下来的硬币，横梁慢慢回到水平","scene":"运费涨了不少，但仓库搬到近郊后省下的租金正好填上这块。The savings offset the higher freight cost.","sceneCN":"这里指用省下的钱抵掉多出来的开支（第 1 个义项：抵消成本或开支）；句意为节省的费用抵消了上涨的运费。图中可辨识物件：天平、涨价的账单、一叠硬币。","pos":[{"tag":"v.","zh":"抵消；补偿；弥补；对冲"},{"tag":"n.","zh":"抵消；偏移；胶印"}],"collocations":[{"phrase":"offset the cost","zh":"抵消成本"},{"phrase":"offset the increase","zh":"抵消涨幅"},{"phrase":"offset losses","zh":"弥补损失"},{"phrase":"offset carbon emissions","zh":"抵消碳排放"},{"phrase":"offset against","zh":"与……相抵"},{"phrase":"offset the risk","zh":"对冲风险"},{"phrase":"offset printing","zh":"胶印"}],"forms":[{"label":"动词原形","form":"offset"},{"label":"第三人称单数","form":"offsets"},{"label":"过去式","form":"offset"},{"label":"过去分词","form":"offset"},{"label":"现在分词","form":"offsetting"},{"label":"名词复数","form":"offsets"}],"derivatives":[{"word":"offsetting","pos":"n./adj.","zh":"由该动词加表示进行或性质的后缀构成，义为「抵消；起抵消作用的」"},{"word":"offset","pos":"n.","zh":"由同一形式转作名词，义为「抵消量；偏移；胶印」"},{"word":"offsets","pos":"n.","zh":"名词复数，义为「各项抵消额；偏移量」"},{"word":"carbon offset","pos":"n.","zh":"由「碳」与「抵消额」合成的复合词，义为「碳抵消额度」"}],"senses":[{"no":"01","title":"To cancel a cost","titleCN":"抵消成本或开支","definition":"to balance an extra cost with a saving elsewhere so that the net charge falls","definitionCN":"用在别处省下的钱抵掉额外开支，使净支出下降","example":"The lower rent offset the rise in transport fees.","exampleCN":"更低的租金抵消了运费的上涨。","why":"The word pictures one item set against another on a scale, and money is the easiest thing to weigh that way.","whyCN":"这个词的画面是把一项放在天平上与另一项对着，而钱最容易被这样称量。"},{"no":"02","title":"To compensate for a loss","titleCN":"补偿损失","definition":"to make up for a loss or disadvantage with a gain in another area","definitionCN":"用另一方面的收益补上损失或劣势","example":"Higher output offset the loss of two machines.","exampleCN":"更高的产量补偿了两台机器的损失。","why":"Compensation is the accounting face of the same balance: what was lost is entered against what was gained.","whyCN":"补偿是同一平衡的会计面孔：失去的与得到的对着记账。"},{"no":"03","title":"To make up for a shortfall","titleCN":"弥补不足","definition":"to supply what is missing so that the total reaches the required level","definitionCN":"补上缺少的部分，使总量达到应有水平","example":"Extra tutoring offset the gap in her early schooling.","exampleCN":"额外的辅导弥补了她早期教育的缺口。","why":"A shortfall is an imbalance on one side, and the verb puts weight on the other side.","whyCN":"缺口是一侧的不平衡，这个动词往另一侧放上重量。"},{"no":"04","title":"To hedge a risk","titleCN":"对冲风险","definition":"to arrange a position that moves opposite to a risk so that losses are limited","definitionCN":"安排一个与风险反向的头寸，以限制损失","example":"The airline offset its fuel exposure with forward contracts.","exampleCN":"这家航空公司用远期合约对冲燃油敞口。","why":"Finance takes the scale literally: two positions are set against each other on purpose.","whyCN":"金融把这个天平照字面使用：两个头寸被有意对着摆。"},{"no":"05","title":"To shift a position","titleCN":"使位置偏移","definition":"to move an object or a line away from its original centre or alignment","definitionCN":"使物体或线条离开原来的中心或对齐位置","example":"The surveyor offset the foundation line by ten centimetres.","exampleCN":"测量员把基础线偏移了十厘米。","why":"Printing and engineering use offset for a displacement, the same side-by-side picture moved into space.","whyCN":"印刷与工程用这个词表示位移，即同一「错开摆放」的画面移入空间。"},{"no":"06","title":"To balance the books","titleCN":"使账目相抵","definition":"to enter one amount against another so that the accounts agree","definitionCN":"把一笔金额对着另一笔记账，使账目相符","example":"The auditor offset the advance against the final invoice.","exampleCN":"审计员把预付款与最终发票相抵。","why":"Accounting formalised the scale into two columns that must come to the same total.","whyCN":"会计把这个天平固定成两栏，两栏最后要合成同一个数。"},{"no":"07","title":"To print by offset","titleCN":"用胶印印刷","definition":"to print from a plate onto a rubber blanket and then onto paper","definitionCN":"先把印版上的图文转到橡皮布，再转到纸上","example":"The booklet was offset on coated stock.","exampleCN":"这本小册子用胶印印在铜版纸上。","why":"The printing sense grew from the idea of an indirect transfer, ink being set off onto another surface.","whyCN":"印刷义从「间接转移」长出，油墨被「转印」到另一表面。"},{"no":"08","title":"To neutralise emissions","titleCN":"抵消排放","definition":"to remove or balance an amount of carbon or pollution by an equivalent saving elsewhere","definitionCN":"用在别处等量的减排来抵消一定量的碳排放或污染","example":"The firm offset its flights by funding a forest project.","exampleCN":"这家公司通过资助一个森林项目来抵消其航班的排放。","why":"Climate policy borrowed the accounting verb and made the two pans visible as emissions and removals.","whyCN":"气候政策借用了这个会计动词，把天平两端的排放与移除摆到明面上。"}],"etymology":{"intro":{"en":"Offset is an English compound of off and set, first meaning to set out or start, later to place one thing against another. The printing sense arrived in the nineteenth century.","cn":"这是英语中由 off 与 set 构成的复合词，最初意为「出发、开始」，后来指「把一物对着另一物摆放」；印刷义在十九世纪出现。"},"items":[{"era":"OLD ENGLISH SETTAN","en":"Set goes back to Old English settan, to place or cause to sit, and it supplies the placing half of the compound.","cn":"set 可追溯到古英语 settan「放置、使坐」，提供这个复合词「摆放」的那一半。"},{"era":"THE PREFIX OFF","en":"Off marks separation or away, so offset began as a placing away from the main line.","cn":"off 标出分离或离开，所以这个词最初指「放在主线之外」。"},{"era":"EARLY VERBAL SENSE","en":"The early verb meant to set out on a journey, a sense now carried by set off rather than offset.","cn":"早期动词义为「出发上路」，这一义今天由「出发」那一短语承担，而不是本词。"},{"era":"THE BALANCE SENSE","en":"The accounting and balancing sense developed later; the exact date of that shift is uncertain and is usually given only as the early modern period.","cn":"会计与抵消义后来才发展出来；这一转变的确切年代不确定，通常只给近代早期这一约数。"},{"era":"PRINTING, 19TH CENTURY","en":"Offset printing named the transfer of ink from plate to blanket to paper, an indirect set-off.","cn":"胶印得名于油墨从印版转到橡皮布再到纸上的间接转印。"},{"era":"MODERN CLIMATE USE","en":"Carbon offset extended the accounting image to emissions, with one pan holding what is released and the other what is removed.","cn":"碳抵消把会计画面扩展到排放，一端放释放的量，另一端放移除的量。"}]},"similar":{"note":{"en":"The first group looks close or shares the set root; the second group names neighbouring ideas of compensation.","cn":"第一组与「offset」形近或共享 set 词根；第二组是与「补偿」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"offsetting","ipa":"/ˈɒfsetɪŋ/","tag":"same root","definition":"The present participle and noun for the act of balancing one item against another.","definitionCN":"现在分词与名词，指把一项对着另一项抵消。"},{"word":"set off","ipa":"/set ɒf/","tag":"same root","definition":"A phrasal verb meaning to start a journey or to trigger something.","definitionCN":"短语动词，指出发或触发。"},{"word":"outset","ipa":"/ˈaʊtset/","tag":"same root","definition":"The beginning of something, from the same set with a different prefix.","definitionCN":"指开端，由同一个表示「放置」的词根配不同前缀。"},{"word":"offset press","ipa":"/ˈɒfset pres/","tag":"same root","definition":"The machine used in offset printing.","definitionCN":"胶印所用的机器。"},{"word":"setback","ipa":"/ˈsetbæk/","tag":"same root","definition":"A reversal or delay, from set and back rather than set and off.","definitionCN":"指挫折或延误，由表示「放置」的词与表示「向后」的词构成。"}]},{"heading":"NEAR MEANING","entries":[{"word":"counterbalance","ipa":"/ˌkaʊntəˈbæləns/","tag":"near meaning","definition":"To weigh against something with equal force.","definitionCN":"指以相等的力量与之抗衡。"},{"word":"compensate","ipa":"/kəmˈpenseɪt/","tag":"near meaning","definition":"To make up for a loss or a disadvantage.","definitionCN":"指弥补损失或劣势。"},{"word":"balance","ipa":"/ˈbæləns/","tag":"near meaning","definition":"To bring two sides into equal weight.","definitionCN":"指使两边重量相等。"},{"word":"neutralise","ipa":"/ˈnjuːtrəlaɪz/","tag":"near meaning","definition":"To cancel the effect of something completely.","definitionCN":"指彻底取消某物的作用。"},{"word":"make up for","ipa":"/meɪk ʌp fɔː/","tag":"near meaning","definition":"To supply what is missing, in everyday wording.","definitionCN":"指补上缺少的部分，日常说法。"},{"word":"hedge","ipa":"/hedʒ/","tag":"near meaning","definition":"To protect against a financial risk by an opposite position.","definitionCN":"指用反向头寸防范金融风险。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the two halves off and set, the accounting image and the printing trade term.","cn":"正常联想使用 off 与 set 两个部分、会计的天平画面，以及印刷行业术语。"},"normal":[{"en":"Off means away and set means place, so offset is to place one thing against another.","cn":"off 是「离开」，set 是「放置」，所以这个词就是把一物对着另一物放。"},{"en":"The past tense does not change: offset, offset, offsetting.","cn":"过去式不变：offset、offset、offsetting。"},{"en":"Accounting says to offset an advance against an invoice.","cn":"会计说把预付款与发票相抵。"},{"en":"Printers speak of offset printing, where ink is transferred twice.","cn":"印刷行话说胶印，油墨要转印两次。"},{"en":"Carbon offset is the modern phrase for balancing emissions with removals.","cn":"碳抵消是用移除量平衡排放量的现代说法。"}],"abstract":[{"en":"To offset is to admit that a gain and a loss can sit on the same scale.","cn":"抵消，就是承认一份得与一份失可以放在同一架天平上。"},{"en":"Nothing is undone by offsetting; the scale simply returns to level.","cn":"抵消并没有撤销什么，只是让天平回到水平。"},{"en":"Every saving you find is a weight you may later place against a cost you cannot avoid.","cn":"你找到的每一笔节省，都是日后可以放到无法避免的开支对面的重量。"}]},"examples":[{"en":"Fuel savings offset the higher purchase price within three years.","cn":"燃油节省在三年内抵消了更高的购价。"},{"en":"The charity offsets its office emissions by planting trees.","cn":"这家慈善机构通过植树抵消办公排放。"},{"en":"The pipe was offset slightly to clear the beam.","cn":"为了避开梁，这根管子被略微偏移。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「奥夫塞特」——天平一端压账单，一端放硬币：抵消、补偿","word":"offset"},"root":"英语复合词，由表示「离开」的前缀与表示「放置」的古英语动词构成；先指出发，后指抵消与错开摆放；印刷义为十九世纪。抵消义的确切转变年代不确定。","sensesIntro":{"en":"Eight senses put two things on opposite pans: cost, loss, shortfall, risk, position, accounts, print and emissions.","cn":"八个义项把两样东西放到天平两端：成本、损失、缺口、风险、位置、账目、印刷与排放。"},"semanticMap":{"core":{"en":"CORE IMAGE: a bill sits on one pan and a stack of coins on the other until the beam levels.","cn":"核心意象：一端压着账单，另一端放上硬币，横梁慢慢回到水平。"},"chain":["SET AGAINST","COST","LOSS","SHORTFALL","RISK","POSITION"],"branches":[{"senses":"01 · 06","en":"THE TWO COLUMNS: an extra cost meets a saving, and the books are made to agree.","cn":"两栏相对：额外开支遇上节省，账目被做成相符。"},{"senses":"02 · 03","en":"THE GAP IS FILLED: a loss or a shortfall is covered from the other side.","cn":"缺口被填：损失或不足由另一端补上。"},{"senses":"04","en":"THE RISK IS HEDGED: a position is deliberately placed opposite to a threat.","cn":"风险被对冲：有意把一笔头寸摆在威胁的对面。"},{"senses":"05","en":"THE LINE IS SHIFTED: an object leaves its original alignment.","cn":"线条被挪开：物体离开原来的对齐位置。"},{"senses":"07 · 08","en":"THE INDIRECT TRANSFER: ink or emissions are set off onto another surface or account.","cn":"间接转印：油墨或排放被转到另一表面或另一本账上。"}]},"affixes":{"intro":{"en":"Offset is a native English compound, so its parts are ordinary English words and its endings are English endings.","cn":"这是一个英语本族复合词，其组成部分是普通英语词，词尾也是英语词尾。"},"latinIntro":{"en":"There is no Latin source for this compound; the Latin column stays empty rather than importing unrelated forms.","cn":"这个复合词没有拉丁语来源，拉丁部分留空，不引入无关形式。"},"items":[{"word":"off","structure":"English prefix","meaning":"away, apart","meaningCN":"离开；分开","example":"It marks the displacement in the compound.","exampleCN":"它标出这个复合词中的位移。"},{"word":"set","structure":"Old English verb","meaning":"to place, to cause to sit","meaningCN":"放置；使就位","example":"It supplies the placing half of the word.","exampleCN":"它提供这个词「摆放」的那一半。"},{"word":"settan","structure":"Old English verb","meaning":"to set, to place","meaningCN":"放置；安放","example":"The Old English form behind modern set.","exampleCN":"现代 set 背后的古英语形式。"},{"word":"offset","structure":"compound verb and noun","meaning":"to balance; a displacement","meaningCN":"抵消；偏移","example":"The same form serves as verb and noun.","exampleCN":"同一形式兼作动词与名词。"},{"word":"-ing","structure":"verbal noun ending","meaning":"the act of balancing","meaningCN":"抵消这一动作","example":"It forms offsetting.","exampleCN":"它构成 offsetting。"},{"word":"offset press","structure":"trade compound","meaning":"the machine for indirect printing","meaningCN":"胶印机","example":"The trade name preserves the transfer image.","exampleCN":"行业名称保留了转印画面。"},{"word":"carbon offset","structure":"modern compound","meaning":"a credit for removed emissions","meaningCN":"碳抵消额度","example":"It extends the accounting image to climate.","exampleCN":"它把会计画面扩展到气候。"},{"word":"outset","structure":"related compound","meaning":"the beginning","meaningCN":"开端","example":"It shows set with a different prefix.","exampleCN":"它展示 set 配另一个前缀。"}],"latinEntries":[],"derivatives":[{"word":"offsetting","pos":"n./adj.","zh":"由该动词加表示进行或性质的后缀构成，义为「抵消；起抵消作用的」"},{"word":"offsets","pos":"n.","zh":"名词复数，义为「各项抵消额；偏移量」"},{"word":"carbon offset","pos":"n.","zh":"由「碳」与「抵消额」合成的复合词，义为「碳抵消额度」"}]}},{"word":"provoke","ipa_uk":"/prəˈvəʊk/","ipa_us":"/prəˈvoʊk/","definition_zh":"激怒；挑衅；引发；引起；煽动","definition_en":"to stir someone into anger or action, or to cause a reaction or an event","core_image":"有人把一根长杆伸进静止的水面，圈圈波纹从杆尖向外荡开","scene":"这份提案把两边的旧账都翻了出来，会上争了两个小时。The proposal provoked a long debate in the council.","sceneCN":"这里指引起一场争论（第 3 个义项：引发反应或讨论）；句意为这份提案在议会引发了长时间辩论。图中可辨识物件：伸进水面的长杆、向外荡开的波纹、静止的水。","pos":[{"tag":"v.","zh":"激怒；挑衅；引发；引起"}],"collocations":[{"phrase":"provoke a reaction","zh":"引发反应"},{"phrase":"provoke criticism","zh":"招致批评"},{"phrase":"provoke anger","zh":"激起愤怒"},{"phrase":"provoke debate","zh":"引发辩论"},{"phrase":"provoke laughter","zh":"引起笑声"},{"phrase":"provoke a response","zh":"引出回应"},{"phrase":"provoke protests","zh":"引发抗议"}],"forms":[{"label":"动词原形","form":"provoke"},{"label":"第三人称单数","form":"provokes"},{"label":"过去式","form":"provoked"},{"label":"过去分词","form":"provoked"},{"label":"现在分词","form":"provoking"},{"label":"名词","form":"provocation"},{"label":"形容词","form":"provocative"}],"derivatives":[{"word":"provocation","pos":"n.","zh":"由该动词加表示动作结果的名词尾构成，义为「挑衅；激怒；诱因」"},{"word":"provocative","pos":"adj.","zh":"由该动词加表示倾向的形容词尾构成，义为「挑衅的；煽动的；引人深思的」"},{"word":"provocatively","pos":"adv.","zh":"由形容词加副词词尾构成，义为「挑衅地」"},{"word":"provoking","pos":"adj.","zh":"由该动词加形容词后缀构成，义为「气人的；惹人恼的」"},{"word":"provoker","pos":"n.","zh":"由该动词加表示施动者的名词尾构成，义为「挑衅者」（少用）"}],"senses":[{"no":"01","title":"To make someone angry","titleCN":"激怒某人","definition":"to stir a person into anger, often deliberately","definitionCN":"使某人动怒，常带故意成分","example":"His remarks provoked the crowd outside the hall.","exampleCN":"他的话激怒了厅外的人群。","why":"The Latin verb meant to call forth, and anger is one of the things called out of a person.","whyCN":"拉丁动词意为「唤出」，而怒气正是从人身上被唤出来的东西之一。"},{"no":"02","title":"To challenge deliberately","titleCN":"故意挑衅","definition":"to invite a fight or a strong reaction by confronting someone on purpose","definitionCN":"有意顶撞某人，以招来争斗或强烈反应","example":"The guard was provoked into opening the gate.","exampleCN":"门卫被激得打开了大门。","why":"Provocation is a call the other person is expected to answer, which is why it feels like an invitation.","whyCN":"挑衅是一声预期对方会回应的召唤，所以才像一份邀请。"},{"no":"03","title":"To give rise to a reaction","titleCN":"引发反应或讨论","definition":"to cause a response, discussion or public reaction without any intent to anger","definitionCN":"引起回应、讨论或公众反应，不含激怒意图","example":"The report provoked wide discussion in the press.","exampleCN":"这份报告在报界引发广泛讨论。","why":"The oldest neutral sense simply calls a response into being, with no emotional charge.","whyCN":"最古老的中性义只是把回应唤出来，不带情绪色彩。"},{"no":"04","title":"To arouse interest","titleCN":"引起兴趣或好奇","definition":"to make curiosity or interest appear in someone","definitionCN":"使某人产生好奇或兴趣","example":"The strange photograph provoked her curiosity.","exampleCN":"那张奇怪的照片引起了她的好奇。","why":"Curiosity is another response that is called forth rather than pushed in.","whyCN":"好奇也是被唤出的回应，而不是被塞进去的。"},{"no":"05","title":"To stir an emotion","titleCN":"激起某种情绪","definition":"to bring a strong feeling such as fear, pity or laughter to the surface","definitionCN":"使恐惧、怜悯或笑意等强烈情绪浮到表面","example":"The empty street provoked a sense of unease.","exampleCN":"空荡的街道激起一种不安。","why":"Emotions are treated as things that can be summoned, which is the core of the Latin verb.","whyCN":"情绪被当作可以召唤的东西，这正是拉丁动词的核心。"},{"no":"06","title":"To draw criticism","titleCN":"招致批评或抗议","definition":"to cause disapproval, complaint or public objection","definitionCN":"引起不满、投诉或公开反对","example":"The decision provoked protests from residents.","exampleCN":"这一决定招致居民的抗议。","why":"Criticism is a response with a negative charge, but the mechanism is still calling forth.","whyCN":"批评是一种带负电的回应，但机制仍是「唤出」。"},{"no":"07","title":"To trigger an attack or symptom","titleCN":"诱发疾病或发作","definition":"to set off a physical episode such as a cough, a fit or an allergic response","definitionCN":"触发咳嗽、发作或过敏反应等身体事件","example":"Cold air provoked a coughing fit.","exampleCN":"冷空气诱发了一阵咳嗽。","why":"Medicine uses the verb for anything that sets a latent condition going.","whyCN":"医学用这个动词指任何让潜伏状况启动的因素。"},{"no":"08","title":"To incite action","titleCN":"煽动行动","definition":"to urge a group towards collective action, often unrest","definitionCN":"鼓动一群人采取集体行动，常指骚动","example":" leaflets provoked a march the next morning.","exampleCN":"传单煽动了第二天早上的游行。","why":"A crowd is called into motion, and the verb keeps the image of a call rather than a push.","whyCN":"人群被唤起来行动，这个动词保留「召唤」而非「推动」的画面。"}],"etymology":{"intro":{"en":"Provoke comes from Latin provocare, to call forth or challenge, from pro-, forth, and vocare, to call, from vox, voice. English took it through French in the fourteenth century.","cn":"这个词来自拉丁语 provocare「唤出、挑战」，由 pro-「向前」与 vocare「呼叫」构成，而 vocare 出自 vox「声音」；英语十四世纪经法语引入。"},"items":[{"era":"LATIN VOX","en":"Vox meant voice, and it is the source of vocal, voice and the whole calling family.","cn":"这个词意为「声音」，是 vocal、voice 以及整个「呼叫」词族的来源。"},{"era":"LATIN VOCARE","en":"Vocare meant to call or summon, and it built verbs such as invoke, evoke and revoke.","cn":"这个词意为呼叫、召唤，构成了 invoke、evoke、revoke 等动词。"},{"era":"LATIN PRO-","en":"The prefix meant forward or forth, so provocare pictured a call sent out towards someone.","cn":"前缀意为向前、向外，所以这个词的画面是把呼唤朝某人发出去。"},{"era":"LATIN PROVOCARE","en":"The verb meant to call forth, to challenge, and in law to appeal against a decision.","cn":"这个动词意为唤出、挑战，在法律中指对裁决提出上诉。"},{"era":"ENGLISH, 14TH CENTURY","en":"English adopted the verb through French; the exact first date is uncertain and is usually given only as that century.","cn":"英语经法语采用这个动词；确切首见年代不确定，通常只给「十四世纪」。"},{"era":"THE ANGER SENSE","en":"The sense of stirring anger became dominant later, while the neutral sense of causing a response survives in formal writing.","cn":"「激起怒气」后来越来越占主导，而「引起回应」的中性义在正式写作中仍存活。"}]},"similar":{"note":{"en":"The first group shares the call root or looks close; the second group names neighbouring ideas of causing and stirring.","cn":"第一组与「provoke」共享「呼叫」词根或只是形近；第二组是与「引起、激起」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"provocation","ipa":"/ˌprəʊvəˈkeɪʃn/","tag":"same root","definition":"The noun for the act of stirring someone or something up.","definitionCN":"指激怒、挑起这一行为的名词。"},{"word":"provocative","ipa":"/prəˈvɒkətɪv/","tag":"same root","definition":"The adjective for something that stirs a reaction or desire.","definitionCN":"形容词，指挑衅的、引人反应的。"},{"word":"evoke","ipa":"/ɪˈvəʊk/","tag":"same root","definition":"To call out a memory or feeling, with the prefix meaning out.","definitionCN":"指唤出记忆或情感，前缀意为「向外」。"},{"word":"invoke","ipa":"/ɪnˈvəʊk/","tag":"same root","definition":"To call upon, as a law or a power, with the prefix meaning in.","definitionCN":"指援引法律或力量，前缀意为「向内」。"},{"word":"revoke","ipa":"/rɪˈvəʊk/","tag":"same root","definition":"To call back, hence to cancel a right or a rule.","definitionCN":"指唤回，因而指撤销权利或规定。"},{"word":"vocabulary","ipa":"/vəʊˈkæbjələri/","tag":"same root","definition":"The stock of words, from the same voice root.","definitionCN":"指词汇总量，同出「声音」词根。"}]},{"heading":"NEAR MEANING","entries":[{"word":"irritate","ipa":"/ˈɪrɪteɪt/","tag":"near meaning","definition":"To annoy mildly, with less drama than provoke.","definitionCN":"指轻度惹恼，戏剧性不如本词。"},{"word":"trigger","ipa":"/ˈtrɪɡə/","tag":"near meaning","definition":"To set off an event or reaction, often mechanically.","definitionCN":"指触发事件或反应，常带机械意味。"},{"word":"arouse","ipa":"/əˈraʊz/","tag":"near meaning","definition":"To wake a feeling or interest in someone.","definitionCN":"指唤起情感或兴趣。"},{"word":"incite","ipa":"/ɪnˈsaɪt/","tag":"near meaning","definition":"To urge people towards violent or unlawful action.","definitionCN":"指煽动人们采取暴力或违法行动。"},{"word":"elicit","ipa":"/ɪˈlɪsɪt/","tag":"near meaning","definition":"To draw out a response or information, usually without anger.","definitionCN":"指引出回应或信息，通常不含怒气。"},{"word":"annoy","ipa":"/əˈnɔɪ/","tag":"near meaning","definition":"To bother someone mildly and repeatedly.","definitionCN":"指反复轻度打扰某人。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the voice root, its four sibling verbs, and the neutral and angry branches of meaning.","cn":"正常联想使用「声音」词根、它的四个兄弟动词，以及中性义与激怒义两条分支。"},"normal":[{"en":"Vox is voice, so provoke is to send a call out and wait for an answer.","cn":"vox 是「声音」，所以这个词是发出一声召唤，等着回应。"},{"en":"Invoke, evoke and revoke share the same calling root with different prefixes.","cn":"invoke、evoke、revoke 与它共享同一「呼叫」词根，只是前缀不同。"},{"en":"Provoke a debate is neutral; provoke a crowd is not.","cn":"「引发辩论」是中性说法，「激怒人群」则不是。"},{"en":"Provocation and provocative are the noun and adjective of the same action.","cn":"它的名词与形容词形式分别表示「挑衅」与「挑衅的」。"},{"en":"Cold air can provoke a cough, which shows how wide the neutral sense reaches.","cn":"冷空气能诱发咳嗽，可见中性义覆盖面之广。"}],"abstract":[{"en":"To provoke is to open a door and refuse to say what is behind it.","cn":"激怒，就是打开一扇门却不说门后有什么。"},{"en":"Every provocation is a question the other person is expected to answer badly.","cn":"每一次挑衅，都是一个预期对方会答坏的问题。"},{"en":"A response called forth is not the same as a response forced in, and that difference is the word.","cn":"被唤出的回应与被塞进去的回应不同，这个差别就是这个词本身。"}]},"examples":[{"en":"The cartoon provoked angry letters from both sides.","cn":"这幅漫画招致双方愤怒的来信。"},{"en":"Her question provoked a thoughtful silence.","cn":"她的问题引来一阵沉思的沉默。"},{"en":"Dust can provoke an asthma attack in sensitive people.","cn":"粉尘可能诱发敏感人群的哮喘发作。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「普罗沃克」——长杆一伸，水面荡开圈圈波纹：引发、激怒","word":"provoke"},"root":"拉丁语 vox「声音」→ vocare「呼叫」→ provocare「唤出、挑战」（pro-「向前」+ vocare）；英语十四世纪经法语引入。与 evoke、invoke、revoke 同根不同前缀。","sensesIntro":{"en":"Eight senses all call something forth: anger, a challenge, a reaction, curiosity, emotion, criticism, a symptom and collective action.","cn":"八个义项都在把某物唤出：怒气、挑战、反应、好奇、情绪、批评、症状与集体行动。"},"semanticMap":{"core":{"en":"CORE IMAGE: a pole touches still water and rings spread outward from the point of contact.","cn":"核心意象：长杆触到静水，圈圈波纹从触点向外荡开。"},"chain":["CALL FORTH","CHALLENGE","ANGER","RESPONSE","INTEREST","OUTBREAK"],"branches":[{"senses":"01 · 02","en":"THE INVITATION TO ANGER: someone is deliberately stirred and expected to react.","cn":"向怒气发出邀请：某人被有意激起，并被期待作出反应。"},{"senses":"03 · 06","en":"THE PUBLIC ANSWER: a report or a decision draws discussion, criticism or protest.","cn":"公众的回应：报告或决定引出讨论、批评或抗议。"},{"senses":"04","en":"THE SPARK OF CURIOSITY: interest appears because something strange is placed in view.","cn":"好奇的火星：奇怪之物被摆在眼前，兴趣随之出现。"},{"senses":"05","en":"THE SURFACING FEELING: fear, pity or laughter is brought up from below.","cn":"浮上来的情绪：恐惧、怜悯或笑意从底下被带上来。"},{"senses":"07 · 08","en":"THE LATENT EPISODE: a symptom starts, or a crowd is moved into action.","cn":"潜伏的发作：症状启动，或人群被鼓动起来。"}]},"affixes":{"intro":{"en":"Provoke is a Latin verb of calling, and the prefix is the piece that decides which way the call goes.","cn":"这是一个表示「呼叫」的拉丁动词，前缀决定这声呼唤朝哪个方向去。"},"latinIntro":{"en":"Latin supplies vox, vocare and provocare; the pieces are well recorded, so no part of the word is marked uncertain.","cn":"拉丁语提供了 vox、vocare、provocare；这些部件有清楚记录，这个词没有哪一部分标为存疑。"},"items":[{"word":"vox","structure":"Latin noun","meaning":"voice","meaningCN":"声音；嗓音","example":"The noun is the source of the whole calling family.","exampleCN":"这个名词是整个「呼叫」词族的源头。"},{"word":"vocare","structure":"Latin verb from vox","meaning":"to call, to summon","meaningCN":"呼叫；召唤","example":"It built invoke, evoke and revoke.","exampleCN":"它构成了 invoke、evoke、revoke。"},{"word":"pro-","structure":"Latin prefix","meaning":"forward, forth","meaningCN":"向前；向外","example":"It sends the call out towards someone.","exampleCN":"它把呼唤朝某人发出去。"},{"word":"provocare","structure":"Latin verb","meaning":"to call forth, challenge","meaningCN":"唤出；挑战","example":"The verb carried both the neutral and the combative shades.","exampleCN":"这个动词兼有中性义与好斗色彩。"},{"word":"-ate","structure":"Latin verb ending","meaning":"to make or do","meaningCN":"做；使","example":"It marks the English verb.","exampleCN":"它标明英语动词。"},{"word":"-ation","structure":"action-result noun ending","meaning":"the act or result","meaningCN":"动作或结果","example":"It forms provocation.","exampleCN":"它构成 provocation。"},{"word":"-ative","structure":"adjective ending","meaning":"tending toward","meaningCN":"倾向于……的","example":"It forms provocative.","exampleCN":"它构成 provocative。"},{"word":"-ing","structure":"adjective ending","meaning":"causing the quality","meaningCN":"致使……的","example":"It forms provoking.","exampleCN":"它构成 provoking。"},{"word":"-er","structure":"agent noun ending","meaning":"the one who acts","meaningCN":"施动者","example":"It forms the rare provoker.","exampleCN":"它构成少用的 provoker。"}],"latinEntries":[{"word":"vox","structure":"Latin noun","meaning":"voice","meaningCN":"声音"},{"word":"vocare","structure":"Latin verb","meaning":"to call","meaningCN":"呼叫"},{"word":"provocare","structure":"Latin verb","meaning":"to call forth","meaningCN":"唤出"},{"word":"provocatio","structure":"Latin noun","meaning":"a calling forth, challenge","meaningCN":"唤出；挑战"}],"derivatives":[{"word":"provocation","pos":"n.","zh":"由该动词加表示动作结果的名词尾构成，义为「挑衅；激怒；诱因」"},{"word":"provocative","pos":"adj.","zh":"由该动词加表示倾向的形容词尾构成，义为「挑衅的；煽动的」"},{"word":"provoking","pos":"adj.","zh":"由该动词加形容词后缀构成，义为「气人的」"},{"word":"provocatively","pos":"adv.","zh":"由形容词加副词词尾构成，义为「挑衅地」"},{"word":"provoker","pos":"n.","zh":"由该动词加表示施动者的名词尾构成，义为「挑衅者」（少用）"}]}},{"word":"reconcile","ipa_uk":"/ˈrekənsaɪl/","ipa_us":"/ˈrekənsaɪl/","definition_zh":"和解；调和；使一致；对账；使顺从","definition_en":"to bring people, ideas or records back into agreement after a difference","core_image":"两本账簿摊在桌上，数字一格一格对上，最后一行终于写出同一个合计","scene":"交报表前，她把发票、银行流水和台账逐笔核对，找出差了的那两笔。She reconciled the two records before submitting the report.","sceneCN":"这里指把两套记录核对到一致（第 4 个义项：核对账目使相符）；句意为她在交报表前把两套记录对平了。图中可辨识物件：摊开的账簿、逐行核对的笔迹、写出同一合计的最后一行。","pos":[{"tag":"v.","zh":"和解；调和；使一致；对账"}],"collocations":[{"phrase":"reconcile differences","zh":"调和分歧"},{"phrase":"reconcile with","zh":"与……和解"},{"phrase":"reconcile accounts","zh":"对账"},{"phrase":"reconcile conflicting views","zh":"协调相互冲突的观点"},{"phrase":"reconcile oneself to","zh":"接受、安于"},{"phrase":"reconcile the two sides","zh":"使双方和解"},{"phrase":"reconcile theory and practice","zh":"使理论与实践一致"}],"forms":[{"label":"动词原形","form":"reconcile"},{"label":"第三人称单数","form":"reconciles"},{"label":"过去式","form":"reconciled"},{"label":"过去分词","form":"reconciled"},{"label":"现在分词","form":"reconciling"},{"label":"名词","form":"reconciliation"},{"label":"形容词","form":"irreconcilable"}],"derivatives":[{"word":"reconciliation","pos":"n.","zh":"由该动词加表示动作结果的名词尾构成，义为「和解；调和；对账」"},{"word":"reconciliatory","pos":"adj.","zh":"由该动词加表示倾向的形容词尾构成，义为「和解性的」"},{"word":"reconciler","pos":"n.","zh":"由该动词加表示施动者的名词尾构成，义为「调停者」"},{"word":"irreconcilable","pos":"adj.","zh":"由否定前缀加「可调和的」构成，义为「不可调和的」"},{"word":"reconciled","pos":"adj.","zh":"由该动词加已然词尾构成，义为「已和解的；已对平的」"}],"senses":[{"no":"01","title":"To restore a relationship","titleCN":"使人和解","definition":"to bring two people or groups back to friendly relations after a quarrel","definitionCN":"在争吵之后使人或群体重回友好关系","example":"The brothers reconciled after the funeral.","exampleCN":"兄弟俩在葬礼之后和解了。","why":"The Latin verb meant to bring back together into a council, and that is the human core of the word.","whyCN":"拉丁动词意为「重新召集到一处」，这正是这个词的人情内核。"},{"no":"02","title":"To harmonise ideas","titleCN":"调和观点","definition":"to show that two apparently opposed ideas can both be accepted","definitionCN":"说明两种看似对立的观点可以同时成立","example":"The essay reconciles scientific evidence with local belief.","exampleCN":"这篇文章把科学证据与当地信仰调和起来。","why":"Ideas are brought into one council too, and reconciliation is the seating of opponents at one table.","whyCN":"观点也被召进同一个议事厅，调和就是让对手坐到一张桌子旁。"},{"no":"03","title":"To make statements consistent","titleCN":"使说法与事实一致","definition":"to make an account agree with the evidence or with another account","definitionCN":"使一种说法与证据或另一种说法相符","example":"He could not reconcile his story with the time stamps.","exampleCN":"他无法让自己的说法与时间戳对上。","why":"When two accounts disagree, reconciling them means finding the version that satisfies both.","whyCN":"当两份叙述不一致，调和就是找出能同时满足两者的版本。"},{"no":"04","title":"To check financial records","titleCN":"核对账目","definition":"to compare two sets of records and adjust them until they agree","definitionCN":"比较两套记录并调整到相符","example":"The clerk reconciled the bank statement with the ledger.","exampleCN":"职员把银行对账单与台账对平了。","why":"Accounting turned the council image into two columns that must arrive at one total.","whyCN":"会计把「议事厅」的画面变成两栏必须合成一个总数的数字。"},{"no":"05","title":"To accept something reluctantly","titleCN":"使顺从、安于","definition":"to bring oneself to accept a difficult situation that cannot be changed","definitionCN":"使自己接受一个无法改变的困难处境","example":"She reconciled herself to the longer commute.","exampleCN":"她只好接受了更长的通勤。","why":"This reflexive use is a private council: the self is brought back into agreement with reality.","whyCN":"这个反身用法是一场私下的议事：自我被重新与现实达成一致。"},{"no":"06","title":"To mediate a dispute","titleCN":"调解争端","definition":"to act as a third party who brings two sides to an agreement","definitionCN":"作为第三方让两边达成一致","example":"A retired judge reconciled the neighbours over the boundary.","exampleCN":"一位退休法官就边界纠纷调解了两家邻居。","why":"Mediation is the verb performed on behalf of others rather than on oneself.","whyCN":"调解是替别人而不是替自己行使这个动词。"},{"no":"07","title":"To align two datasets","titleCN":"协调数据记录","definition":"to match two sets of data that use different formats or identifiers","definitionCN":"把格式或标识不同的两套数据匹配起来","example":"The team reconciled the sensor logs with the maintenance records.","exampleCN":"团队把传感器日志与维护记录对齐了。","why":"Data work inherited the accounting sense: two systems describe one reality and must be made to agree.","whyCN":"数据工作继承了会计义：两个系统描述同一现实，必须被弄成一致。"},{"no":"08","title":"To balance competing needs","titleCN":"兼顾相互冲突的需求","definition":"to find a practical arrangement that meets two demands at once","definitionCN":"找到同时满足两项要求的实际安排","example":"The plan reconciles housing demand with the need for open land.","exampleCN":"这个方案兼顾了住房需求与保留空地的需要。","why":"Planning is a council of demands, and reconciling them is what a plan is for.","whyCN":"规划就是各种需求的议事厅，而调和它们正是方案存在的理由。"}],"etymology":{"intro":{"en":"Reconcile comes from Latin reconciliare, to bring together again, from re-, again, and conciliare, to unite, from concilium, an assembly. English took it through French.","cn":"这个词来自拉丁语 reconciliare「重新聚到一起」，由 re-「再」与 conciliare「使联合」构成，而 conciliare 出自 concilium「集会」；英语经法语引入。"},"items":[{"era":"LATIN CONCILIUM","en":"Concilium meant an assembly or council, the gathering of people into one body.","cn":"这个词意为集会或议事会，即把人聚成一个整体。"},{"era":"LATIN CONCILIARE","en":"Conciliare meant to unite or to win over, and it could also mean to procure or to cause.","cn":"这个词意为使联合、争取过来，也可指取得或促成。"},{"era":"LATIN RE-","en":"The prefix meant again or back, so reconciliare pictured a second gathering after a break.","cn":"前缀意为「再、回」，所以这个词的画面是破裂之后的第二次聚集。"},{"era":"LATIN RECONCILIARE","en":"The verb meant to restore to friendship or to bring back into agreement.","cn":"这个动词意为恢复友好或使重新一致。"},{"era":"ENGLISH, 14TH CENTURY","en":"English adopted the verb through French; the exact first date is uncertain and is usually given only as that century.","cn":"英语经法语采用这个动词；确切首见年代不确定，通常只给「十四世纪」。"},{"era":"THE ACCOUNTING BRANCH","en":"Bookkeeping gave the verb its ledger sense, in which the two parties are two sets of figures.","cn":"记账给这个动词添了账簿义，其中的「两方」变成了两套数字。"}]},"similar":{"note":{"en":"The first group shares the council stem or looks close; the second group names neighbouring ideas of agreement and settlement.","cn":"第一组与「reconcile」共享「集会」词干或只是形近；第二组是与「一致、解决」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"reconciliation","ipa":"/ˌrekənˌsɪliˈeɪʃn/","tag":"same root","definition":"The noun for the act of restoring agreement.","definitionCN":"指恢复一致这一行为的名词。"},{"word":"irreconcilable","ipa":"/ɪˌrekənˈsaɪləbl/","tag":"same root","definition":"An adjective for differences that cannot be settled.","definitionCN":"形容词，指无法调和的分歧。"},{"word":"conciliate","ipa":"/kənˈsɪlieɪt/","tag":"same root","definition":"To win over or pacify, from the same council verb without the re-.","definitionCN":"指安抚、争取，同出「集会」动词，只是没有表示「再」的前缀。"},{"word":"council","ipa":"/ˈkaʊnsl/","tag":"same root","definition":"A governing assembly, from the same Latin noun but a different spelling path.","definitionCN":"指议事机构，同出同一拉丁名词，但拼写路径不同。"},{"word":"counsel","ipa":"/ˈkaʊnsl/","tag":"different word","definition":"Advice or a legal adviser, from a different Latin verb meaning to consult.","definitionCN":"指建议或法律顾问，出自另一个表示「商议」的拉丁动词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"settle","ipa":"/ˈsetl/","tag":"near meaning","definition":"To end a dispute by agreement, the plainest verb.","definitionCN":"指以协议结束争端，最朴素的说法。"},{"word":"resolve","ipa":"/rɪˈzɒlv/","tag":"near meaning","definition":"To fix a problem or decide firmly.","definitionCN":"指解决问题或下定决心。"},{"word":"harmonise","ipa":"/ˈhɑːmənaɪz/","tag":"near meaning","definition":"To make parts fit together without conflict.","definitionCN":"指使各部分协调不冲突。"},{"word":"mediate","ipa":"/ˈmiːdieɪt/","tag":"near meaning","definition":"To stand between two sides and help them agree.","definitionCN":"指居于两方之间帮助他们达成一致。"},{"word":"align","ipa":"/əˈlaɪn/","tag":"near meaning","definition":"To bring things into the same line, often used of data.","definitionCN":"指把事物排到同一条线上，常用于数据。"},{"word":"patch up","ipa":"/pætʃ ʌp/","tag":"near meaning","definition":"To repair a relationship roughly and quickly.","definitionCN":"指粗略快速地修复关系。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the council inside the word, the accountant's ledger, and the spelling trap with counsel.","cn":"正常联想使用词里的「集会」、会计的账簿，以及 counsel 这个拼写陷阱。"},"normal":[{"en":"Concilium is a council, so reconcile is to call everyone back to one table.","cn":"concilium 是议事会，所以这个词就是把人都叫回一张桌子。"},{"en":"The re- means again, so the word always implies a break that came first.","cn":"re- 意为「再」，所以这个词总暗含先前的一次破裂。"},{"en":"Accountants reconcile two sets of figures until they agree.","cn":"会计把两套数字对到相符为止。"},{"en":"Reconcile oneself to a hard fact is a private version of the same table.","cn":"让自己接受一个硬事实，是同一张桌子的私下版本。"},{"en":"Council is the assembly, counsel is advice, and only council belongs here.","cn":"council 是议事机构，counsel 是建议，只有前者与这个词相关。"}],"abstract":[{"en":"To reconcile is not to prove one side right; it is to build a table both can sit at.","cn":"调和不是证明某一方正确，而是造一张双方都能坐下的桌子。"},{"en":"Two true accounts can still disagree, and the work is to find why.","cn":"两份真实的叙述仍可能对不上，而工作就是找出为什么。"},{"en":"The hardest reconciliation is the one a person performs with a fact that will not move.","cn":"最难的和解，是一个人跟一个不会改变的事实之间达成的那个。"}]},"examples":[{"en":"The two countries reconciled after years of frozen relations.","cn":"多年关系冻结之后，两国和解了。"},{"en":"It is hard to reconcile such a claim with the published data.","cn":"这样的说法很难与已发表的数据相符。"},{"en":"Please reconcile the invoice total with the purchase order.","cn":"请把发票总额与采购订单核对一致。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「瑞康赛尔」——两本账簿摊开，末行写出同一个数：调和、对账","word":"reconcile"},"root":"拉丁语 concilium「集会」→ conciliare「使联合」→ reconciliare「重新聚到一起」（re-「再」）；英语十四世纪经法语引入。与 counsel「建议」不同源。","sensesIntro":{"en":"Eight senses all seat two parties at one table: people, ideas, statements, records, the self, a dispute, datasets and competing needs.","cn":"八个义项都在把两方请到同一张桌子：人、观点、说法、账目、自我、争端、数据集与冲突的需求。"},"semanticMap":{"core":{"en":"CORE IMAGE: two ledgers lie open, line by line is matched, and one total finally appears at the bottom.","cn":"核心意象：两本账簿摊开，逐行对上，最后一行终于写出同一个合计。"},"chain":["COUNCIL","TOGETHER AGAIN","DISPUTE","AGREEMENT","RECORD","ACCEPTANCE"],"branches":[{"senses":"01 · 06","en":"THE TABLE IS RESET: two people or two groups are brought back to one table, sometimes by a third party.","cn":"桌子被重摆：两个人或两个群体被带回同一桌，有时由第三方促成。"},{"senses":"02 · 08","en":"THE IDEAS SHARE A ROOM: opposed views or competing needs are arranged so both can stand.","cn":"观点共用一室：对立观点或冲突需求被安排到可以并存。"},{"senses":"03","en":"THE STORY IS TESTED: a claim is checked until it fits the evidence.","cn":"说法被检验：一种叙述被核到与证据相符。"},{"senses":"04 · 07","en":"THE FIGURES MEET: ledgers or datasets are matched until one total appears.","cn":"数字对上：账簿或数据集被匹配到一个总数。"},{"senses":"05","en":"THE SELF YIELDS: a person comes to terms with what cannot be changed.","cn":"自我让步：人与无法改变的事达成妥协。"}]},"affixes":{"intro":{"en":"Reconcile is a Latin verb of gathering, and its pieces are the prefix of return and the noun for an assembly.","cn":"这是一个表示「聚拢」的拉丁动词，其部件是「返回」的前缀与表示「集会」的名词。"},"latinIntro":{"en":"Latin supplies concilium, conciliare and reconciliare; the family is well recorded, so no part is marked uncertain.","cn":"拉丁语提供了 concilium、conciliare、reconciliare；这一族有清楚记录，没有哪一部分标为存疑。"},"items":[{"word":"concilium","structure":"Latin noun","meaning":"assembly, council","meaningCN":"集会；议事会","example":"The noun is the room where the parties meet.","exampleCN":"这个名词是各方会面的那个房间。"},{"word":"conciliare","structure":"Latin verb from concilium","meaning":"to unite, to win over","meaningCN":"使联合；争取","example":"The verb names the act of bringing together.","exampleCN":"这个动词指把人聚到一起的动作。"},{"word":"re-","structure":"Latin prefix","meaning":"again, back","meaningCN":"再；回","example":"It marks the second gathering after a break.","exampleCN":"它标出破裂后的第二次聚集。"},{"word":"reconciliare","structure":"Latin verb","meaning":"to restore to friendship","meaningCN":"使重归友好","example":"The verb carried both the human and the agreement senses.","exampleCN":"这个动词兼有人际与一致两种意义。"},{"word":"reconciliatio","structure":"Latin noun","meaning":"a restoring, reconciliation","meaningCN":"恢复；和解","example":"The noun supplied the English word for the process.","exampleCN":"这个名词提供了英语中表示过程的名词。"},{"word":"-ation","structure":"action-result noun ending","meaning":"the act or result","meaningCN":"动作或结果","example":"It forms reconciliation.","exampleCN":"它构成 reconciliation。"},{"word":"-ory","structure":"adjective ending","meaning":"tending toward","meaningCN":"倾向于……的","example":"It forms reconciliatory.","exampleCN":"它构成 reconciliatory。"},{"word":"in-","structure":"negative prefix","meaning":"not","meaningCN":"不；非","example":"It forms irreconcilable with an assimilated r.","exampleCN":"它与同化的 r 一起构成 irreconcilable。"},{"word":"-able","structure":"adjective ending","meaning":"capable of being","meaningCN":"可……的","example":"It forms the adjective for what can be settled.","exampleCN":"它构成表示「可调和的」形容词。"}],"latinEntries":[{"word":"concilium","structure":"Latin noun","meaning":"assembly, council","meaningCN":"集会；议事会"},{"word":"conciliare","structure":"Latin verb","meaning":"to unite","meaningCN":"使联合"},{"word":"reconciliare","structure":"Latin verb","meaning":"to bring together again","meaningCN":"重新聚到一起"},{"word":"reconciliatio","structure":"Latin noun","meaning":"a restoring","meaningCN":"恢复；和解"}],"derivatives":[{"word":"reconciliation","pos":"n.","zh":"由该动词加表示动作结果的名词尾构成，义为「和解；调和；对账」"},{"word":"reconciliatory","pos":"adj.","zh":"由该动词加表示倾向的形容词尾构成，义为「和解性的」"},{"word":"irreconcilable","pos":"adj.","zh":"由否定前缀加「可调和的」构成，义为「不可调和的」"},{"word":"reconciler","pos":"n.","zh":"由该动词加表示施动者的名词尾构成，义为「调停者」"}]}},{"word":"surpass","ipa_uk":"/səˈpɑːs/","ipa_us":"/sərˈpæs/","definition_zh":"超过；胜过；超越","definition_en":"to go beyond a limit, record or standard, or to be better than someone or something else","core_image":"终点线旁的数字牌被人越过，上一年的纪录还挂在牌上，新数字已经翻过去","scene":"年底还没到，出口额就已经比去年全年更多。Exports are expected to surpass last year's total.","sceneCN":"这里指在数量上超过原有水平（第 1 个义项：数量或数字超过）；句意为出口额预计会超过去年全年总量。图中可辨识物件：终点线、翻过去的数字牌、旧纪录。","pos":[{"tag":"v.","zh":"超过；胜过；超越"}],"collocations":[{"phrase":"surpass expectations","zh":"超出预期"},{"phrase":"surpass a record","zh":"打破纪录"},{"phrase":"surpass the competition","zh":"胜过竞争对手"},{"phrase":"far surpass","zh":"远远超过"},{"phrase":"surpass in quality","zh":"在质量上胜过"},{"phrase":"surpass oneself","zh":"超越自我"}],"forms":[{"label":"动词原形","form":"surpass"},{"label":"第三人称单数","form":"surpasses"},{"label":"过去式","form":"surpassed"},{"label":"过去分词","form":"surpassed"},{"label":"现在分词","form":"surpassing"},{"label":"形容词","form":"unsurpassed"},{"label":"形容词","form":"surpassing"}],"derivatives":[{"word":"surpassing","pos":"adj.","zh":"由该动词加形容词后缀构成，义为「非凡的；超越的」"},{"word":"unsurpassed","pos":"adj.","zh":"由否定前缀加已然词构成，义为「无可匹敌的」"},{"word":"surpassable","pos":"adj.","zh":"由该动词加「可……的」形容词尾构成，义为「可超越的」（少用）"},{"word":"surpassed","pos":"adj.","zh":"由该动词加已然词尾构成，义为「已被超越的」"}],"senses":[{"no":"01","title":"To exceed a number","titleCN":"在数量上超过","definition":"to be greater than a stated figure, total or level","definitionCN":"大于某个给定的数字、总量或水平","example":"Sales surpassed ten million units this year.","exampleCN":"今年销量超过了一千万台。","why":"The Old French verb meant to pass over, and a figure is something you can pass.","whyCN":"古法语动词意为「越过」，而数字正是可以越过去的东西。"},{"no":"02","title":"To outperform a rival","titleCN":"胜过对手","definition":"to do better than a competitor in a contest or market","definitionCN":"在竞赛或市场中表现得比对手更好","example":"The small team surpassed three larger firms in the trial.","exampleCN":"这支小团队在测试中胜过了三家更大的公司。","why":"A race is the original scene: one runner passes another and is now ahead.","whyCN":"赛跑是最初的场景：一名跑者越过另一名，就跑到前面了。"},{"no":"03","title":"To exceed expectations","titleCN":"超出预期","definition":"to be better or larger than people had predicted","definitionCN":"比人们此前预料的更好或更大","example":"The response to the appeal surpassed every forecast.","exampleCN":"这次呼吁得到的响应超出了所有预测。","why":"Expectations set a line in advance, and surpassing is crossing that line.","whyCN":"预期提前画了一条线，超过就是越过那条线。"},{"no":"04","title":"To break a record","titleCN":"打破纪录","definition":"to go beyond the best result previously achieved","definitionCN":"超过此前取得的最好成绩","example":"She surpassed the national record by two hundredths of a second.","exampleCN":"她以百分之二秒打破了全国纪录。","why":"A record is the highest mark on the board, and the verb names the moment it falls.","whyCN":"纪录是板上最高的刻度，这个词命名它被刷下的那一刻。"},{"no":"05","title":"To go beyond a limit of ability","titleCN":"超出能力或理解范围","definition":"to be more than a person or system can reach or handle","definitionCN":"超过人或系统所能达到或处理的范围","example":"The noise surpassed the level the equipment could measure.","exampleCN":"噪声超过了设备能够测量的水平。","why":"A limit is a wall, and surpassing passes over it rather than around it.","whyCN":"极限是一堵墙，而超过是从上方越过去，不是绕过去。"},{"no":"06","title":"To be superior in quality","titleCN":"在质量上优于","definition":"to be of better quality than another thing of the same kind","definitionCN":"在同类的另一事物之上","example":"The finish surpassed every sample we had tested.","exampleCN":"这层表面处理胜过我们测过的所有样品。","why":"Quality can be ranked, and the higher rank simply sits beyond the lower one.","whyCN":"质量可以排位，较高的位次就落在较低位次之外。"},{"no":"07","title":"To outdo one's earlier self","titleCN":"超越从前的自己","definition":"to do better than one's own previous performance","definitionCN":"比自己以往的表现做得更好","example":"He surpassed his own best time in the final heat.","exampleCN":"他在最后一组超过了自己的最好成绩。","why":"The rival can be oneself, which is why the word often appears with the reflexive form.","whyCN":"对手可以就是自己，所以这个词常与反身形式同现。"},{"no":"08","title":"To go over a set ceiling","titleCN":"超过上限","definition":"to rise above a ceiling set by policy, safety or design","definitionCN":"上升到由政策、安全或设计设定的上限之上","example":"Demand surpassed the capacity of the old substation.","exampleCN":"需求超过了旧变电站的容量。","why":"Every design has a ceiling, and surpassing it is the point where a plan stops being safe.","whyCN":"每个设计都有上限，超过它就是方案不再安全的那个点。"}],"etymology":{"intro":{"en":"Surpass comes from Old French surpasser, to go beyond, from sur-, over, and passer, to pass, which goes back to Latin passus, a step. English adopted it in the sixteenth century.","cn":"这个词来自古法语 surpasser「越过」，由 sur-「在上、超过」与 passer「经过」构成，而 passer 可追溯到拉丁语 passus「一步」；英语十六世纪引入。"},"items":[{"era":"LATIN PASSUS","en":"Passus meant a step or a pace, and it is the source of pass, passage and surpass alike.","cn":"这个词意为一步或一步的距离，是 pass、passage、surpass 共同的来源。"},{"era":"LATIN SUPER","en":"The prefix behind sur- meant above or over, and it survives in super, supreme and surface.","cn":"sur- 背后的前缀意为在上、越过，仍见于 super、supreme、surface。"},{"era":"OLD FRENCH SURPASSER","en":"The French verb meant to go beyond or to exceed, and it was used of limits, rivals and expectations.","cn":"这个法语动词意为越过、超过，用于界限、对手与预期。"},{"era":"ENGLISH, 16TH CENTURY","en":"English adopted the verb in the sixteenth century; the exact first date is uncertain and is usually given only as that century.","cn":"英语十六世纪采用这个动词，确切首见年代不确定，通常只给「十六世纪」。"},{"era":"THE SUR- FAMILY","en":"Surplus, survive and surrender share the same over- prefix with different roots behind it.","cn":"surplus、survive、surrender 共享同一「在上」前缀，背后的词根各不相同。"},{"era":"MODERN SPORTING USE","en":"Sport gave the verb its fixed objects record and rival, which keep the race image alive.","cn":"体育给这个动词添了纪录与对手这两个固定宾语，让赛跑画面延续至今。"}]},"similar":{"note":{"en":"The first group shares the pass root or looks close; the second group names neighbouring ideas of excelling.","cn":"第一组与「surpass」共享 pass 词根或只是形近；第二组是与「胜过」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"surpassing","ipa":"/səˈpɑːsɪŋ/","tag":"same root","definition":"An adjective meaning exceptional, literally going beyond others.","definitionCN":"形容词，指非凡的，字面是「越过他人」。"},{"word":"unsurpassed","ipa":"/ˌʌnsəˈpɑːst/","tag":"same root","definition":"Not exceeded by anything, the negative adjective of the verb.","definitionCN":"指无人超过的，是这个动词的否定形容词。"},{"word":"surpassable","ipa":"/səˈpɑːsəbl/","tag":"same root","definition":"Capable of being exceeded, a rare but regular form.","definitionCN":"指可被超过的，少用但构词规则。"},{"word":"pass","ipa":"/pɑːs/","tag":"same root","definition":"To go by or beyond, the base verb inside surpass.","definitionCN":"指经过或越过，是这个词内部的基础动词。"},{"word":"surplus","ipa":"/ˈsɜːpləs/","tag":"same prefix","definition":"An amount over what is needed; the prefix matches but the root is to be more.","definitionCN":"指超出所需的数量；前缀相同，词根是「更多」。"},{"word":"surface","ipa":"/ˈsɜːfɪs/","tag":"same prefix","definition":"The top layer, from sur- and face; the prefix matches, the root does not.","definitionCN":"指表层，由「在上」前缀与「面」构成；前缀相同，词根不同。"}]},{"heading":"NEAR MEANING","entries":[{"word":"exceed","ipa":"/ɪkˈsiːd/","tag":"near meaning","definition":"To go beyond a number or a limit, the neutral technical verb.","definitionCN":"指超出数量或限度，是中性技术说法。"},{"word":"outdo","ipa":"/ˌaʊtˈduː/","tag":"near meaning","definition":"To do better than someone in the same activity.","definitionCN":"指在同一活动中做得比某人更好。"},{"word":"outperform","ipa":"/ˌaʊtpəˈfɔːm/","tag":"near meaning","definition":"To perform better than a rival, common in business.","definitionCN":"指表现优于对手，商务常用。"},{"word":"beat","ipa":"/biːt/","tag":"near meaning","definition":"To defeat or do better than, in plain speech.","definitionCN":"指击败或胜过，口语说法。"},{"word":"transcend","ipa":"/trænˈsend/","tag":"near meaning","definition":"To go beyond a category or limit altogether, often in a philosophical sense.","definitionCN":"指整体上超越某个范畴或限度，常带哲学意味。"},{"word":"top","ipa":"/tɒp/","tag":"near meaning","definition":"To be higher than a previous figure, used of charts and lists.","definitionCN":"指高于先前数字，多用于榜单。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the step root, the over prefix, and the sporting phrases that keep the race image alive.","cn":"正常联想使用「一步」词根、「在上」前缀，以及让赛跑画面延续的体育搭配。"},"normal":[{"en":"Passus is a step, and surpass is to step over the line that was there.","cn":"passus 是「一步」，而这个词就是跨过原先那条线。"},{"en":"Sur- means over, the same prefix seen in surplus and surface.","cn":"sur- 意为「在上」，与 surplus、surface 同一前缀。"},{"en":"Athletes surpass a record; firms surpass expectations and rivals.","cn":"运动员打破纪录，企业超出预期、胜过对手。"},{"en":"Unsurpassed is the negative adjective: nobody has gone past it.","cn":"「无可匹敌的」是否定形容词：没人越过去过。"},{"en":"Unlike transcend, surpass is measurable: a number, a time or a rank moves past another.","cn":"与 transcend 不同，surpass 是可测量的：数字、时间或名次越到另一个前面。"}],"abstract":[{"en":"To surpass is to make yesterday's ceiling today's floor.","cn":"超越，就是把昨天的天花板变成今天的地板。"},{"en":"Every record is only a place where someone stopped being measured.","cn":"每一项纪录都只是有人停止被测量的那个位置。"},{"en":"Transcend changes the scale; surpass merely moves along it, and knowing which one you need is the real skill.","cn":"超越范畴是换一把尺，胜过只是在同一把尺上往前挪，分得清两者才是真本事。"}]},"examples":[{"en":"Demand for the service surpassed all earlier estimates.","cn":"这项服务的需求超出了此前所有估计。"},{"en":"Her second novel surpassed the first in every review.","cn":"她的第二部小说在每一篇评论中都胜过了第一部。"},{"en":"The river surpassed its danger level after two days of rain.","cn":"两天降雨之后，这条河超过了警戒水位。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「瑟帕斯」——终点牌被翻过去，旧纪录留在上面：超过、胜过","word":"surpass"},"root":"拉丁语 passus「一步」→ 古法语 surpasser「越过」（sur-「在上」+ passer「经过」）；英语十六世纪引入。与 transcend 不同，本词强调可测量的越线。","sensesIntro":{"en":"Eight senses all cross a line: a number, a rival, a forecast, a record, a limit, a quality, one's own best and a ceiling.","cn":"八个义项都在越过一条线：数字、对手、预测、纪录、极限、质量、自己的最好成绩与上限。"},"semanticMap":{"core":{"en":"CORE IMAGE: a runner crosses the line and the board turns past last year's figure.","cn":"核心意象：跑者冲过终点线，数字牌翻过去年的数字。"},"chain":["OVER","PASS","NUMBER","RIVAL","EXPECTATION","LIMIT"],"branches":[{"senses":"01 · 08","en":"THE FIGURE IS PASSED: a total or a ceiling is left below the new reading.","cn":"数字被越过：总量或上限被留在新读数之下。"},{"senses":"02 · 06","en":"THE RIVAL IS BEHIND: a competitor or a sample now ranks lower.","cn":"对手落到后面：竞争者或样品的名次更低。"},{"senses":"03","en":"THE FORECAST IS BEATEN: what people expected turns out to be too small.","cn":"预测被打破：人们预想的原来偏小。"},{"senses":"04 · 07","en":"THE MARK FALLS: a record or one's own previous best is replaced.","cn":"刻度被刷下：纪录或自己从前的最好成绩被取代。"},{"senses":"05","en":"THE ABILITY IS OUTRUN: a limit of reach, handling or understanding is passed.","cn":"能力被跑过：触及、处理或理解的极限被越过。"}]},"affixes":{"intro":{"en":"Surpass joins an over-prefix to a verb of stepping, and both pieces are Latin in origin though the compound is French.","cn":"这个词把「在上」的前缀接到表示「迈步」的动词上，两部分都源自拉丁语，但复合发生在法语。"},"latinIntro":{"en":"Latin supplies passus and super; the French compound surpasser then supplied English, and every piece is well recorded.","cn":"拉丁语提供了 passus 与 super；法语复合词 surpasser 再提供英语，每个部件都有清楚记录。"},"items":[{"word":"passus","structure":"Latin noun","meaning":"a step, a pace","meaningCN":"一步；步幅","example":"The noun is the source of pass and surpass.","exampleCN":"这个名词是 pass 与 surpass 的来源。"},{"word":"passer","structure":"French verb from passus","meaning":"to pass, to go by","meaningCN":"经过；越过","example":"The French verb supplied the moving half.","exampleCN":"这个法语动词提供「移动」的那一半。"},{"word":"sur-","structure":"French prefix from Latin super","meaning":"over, above","meaningCN":"在上；超过","example":"It marks the line being crossed.","exampleCN":"它标出被越过的那条线。"},{"word":"super","structure":"Latin preposition","meaning":"above, beyond","meaningCN":"在上；超出","example":"The Latin form behind the French prefix.","exampleCN":"法语前缀背后的拉丁形式。"},{"word":"surpasser","structure":"Old French verb","meaning":"to go beyond, exceed","meaningCN":"越过；超过","example":"The compound entered English almost unchanged.","exampleCN":"这个复合词几乎原样进入英语。"},{"word":"-ing","structure":"adjective ending","meaning":"in the course of, or to a high degree","meaningCN":"正在……的；达到高程度的","example":"It forms surpassing.","exampleCN":"它构成 surpassing。"},{"word":"un-","structure":"negative prefix","meaning":"not","meaningCN":"不；非","example":"It forms unsurpassed.","exampleCN":"它构成 unsurpassed。"},{"word":"-able","structure":"adjective ending","meaning":"capable of being","meaningCN":"可……的","example":"It forms the rare surpassable.","exampleCN":"它构成少用的 surpassable。"},{"word":"-ed","structure":"past participle ending","meaning":"having undergone","meaningCN":"已……的","example":"It forms surpassed.","exampleCN":"它构成 surpassed。"}],"latinEntries":[{"word":"passus","structure":"Latin noun","meaning":"step, pace","meaningCN":"一步；步幅"},{"word":"super","structure":"Latin preposition","meaning":"above, beyond","meaningCN":"在上；超出"},{"word":"passare","structure":"Late Latin verb","meaning":"to pass","meaningCN":"经过"},{"word":"superpassare","structure":"Medieval Latin verb","meaning":"to pass over","meaningCN":"越过"}],"derivatives":[{"word":"surpassing","pos":"adj.","zh":"由该动词加形容词后缀构成，义为「非凡的；超越的」"},{"word":"unsurpassed","pos":"adj.","zh":"由否定前缀加已然词构成，义为「无可匹敌的」"},{"word":"surpassable","pos":"adj.","zh":"由该动词加「可……的」形容词尾构成，义为「可超越的」（少用）"},{"word":"surpassed","pos":"adj.","zh":"由该动词加已然词尾构成，义为「已被超越的」"}]}},{"word":"ecological balance","ipa_uk":"/ɪˌkɒləˈdʒɪkl ˈbæləns/","ipa_us":"/ɪˌkɑːləˈdʒɪkl ˈbæləns/","definition_zh":"生态平衡；生态系统内部各要素之间的稳定协调状态","definition_en":"a stable condition in which the living and non-living parts of an ecosystem keep one another in check","core_image":"一片水塘里，水草、小鱼与捕食的鸟各自维持在差不多的数量，水面既不清瘦也不浑浊","scene":"这片海湾限制捕捞量，鱼群、海草和捕食者都维持在原来的规模。Fishing quotas help keep an ecological balance in the bay.","sceneCN":"这里指生态系统各要素之间维持稳定协调（第 1 个义项：生态平衡的总体状态）；句意为捕捞配额有助于维持湾内的生态平衡。图中可辨识物件：水塘、水草、小鱼、捕食的鸟。","pos":[{"tag":"n.","zh":"生态平衡；生态系统各要素间的稳定协调"}],"collocations":[{"phrase":"maintain ecological balance","zh":"维持生态平衡"},{"phrase":"keep an ecological balance","zh":"保持生态平衡"},{"phrase":"disturb the ecological balance","zh":"扰乱生态平衡"},{"phrase":"restore ecological balance","zh":"恢复生态平衡"},{"phrase":"break the ecological balance","zh":"破坏生态平衡"},{"phrase":"a fragile ecological balance","zh":"脆弱的生态平衡"}],"forms":[{"label":"单数","form":"ecological balance"},{"label":"复数","form":"ecological balances"},{"label":"形容词","form":"ecologically balanced"},{"label":"名词","form":"ecology"},{"label":"名词","form":"ecologist"}],"derivatives":[{"word":"ecology","pos":"n.","zh":"由希腊语「住所」与「学问」合成，义为「生态学」"},{"word":"ecological","pos":"adj.","zh":"由「生态学」加形容词词尾构成，义为「生态的；生态学的」"},{"word":"ecologically","pos":"adv.","zh":"由形容词加副词词尾构成，义为「在生态方面」"},{"word":"ecologist","pos":"n.","zh":"由「生态学」加表示从事者的名词尾构成，义为「生态学家」"},{"word":"imbalance","pos":"n.","zh":"由否定前缀加「平衡」构成，义为「失衡」，与本词构成反义对照"}],"senses":[{"no":"01","title":"The overall stable state","titleCN":"生态平衡的总体状态","definition":"the general condition in which an ecosystem stays stable over time","definitionCN":"生态系统在较长时期内保持稳定的总体状况","example":"The wetland still shows a remarkable ecological balance after the restoration.","exampleCN":"修复之后的湿地仍呈现出显著的生态平衡。","why":"The compound joins the study of the household to the image of a two-pan scale, and the whole is the state where both pans hold.","whyCN":"这个复合词把「家园的学问」接到两盘天平的画面上，整体就是两盘都端住的状态。"},{"no":"02","title":"Balance among species numbers","titleCN":"物种数量间的平衡","definition":"a condition in which the populations of different species stay within ranges that support one another","definitionCN":"不同物种的种群数量各自保持在互相支撑的范围内","example":"Predators and prey kept an ecological balance on the island for centuries.","exampleCN":"捕食者与猎物在这个岛上维持了数百年的生态平衡。","why":"Species are the weights on the scale, and balance means no single one runs away with the total.","whyCN":"物种是天平上的重量，平衡意味着没有哪一个把总量带走。"},{"no":"03","title":"Stability of the food web","titleCN":"食物链的稳定","definition":"a condition in which energy passes through the food chain without any link being exhausted","definitionCN":"能量沿食物链传递，而没有哪一环被耗尽","example":"Removing one link in the chain upset the ecological balance of the lake.","exampleCN":"去掉链上的一环，打乱了这片湖的生态平衡。","why":"A chain is stable when each link can feed the next, which is the balance seen as flow rather than as weight.","whyCN":"链条稳定在于每一环都喂得饱下一环，这是把平衡看作流动而非重量。"},{"no":"04","title":"Balance between resources and consumption","titleCN":"资源与消耗的平衡","definition":"a condition in which what an area produces is matched by what its inhabitants take","definitionCN":"一个地区生产的东西与居民取用的东西大体相抵","example":"Grazing levels were cut to restore an ecological balance between grass and cattle.","exampleCN":"放牧量被削减，以恢复草与牛之间的生态平衡。","why":"This is the accounting face of the compound: what grows is entered against what is eaten.","whyCN":"这是这个复合词的会计面孔：长出来的与吃掉的对着记账。"},{"no":"05","title":"Balance between human activity and nature","titleCN":"人类活动与自然的平衡","definition":"a condition in which human use of land and water does not overwhelm natural renewal","definitionCN":"人类对土地与水的使用没有压过自然更新的能力","example":"The plan tries to hold an ecological balance between tourism and the reef.","exampleCN":"这个方案试图在旅游与珊瑚礁之间维持生态平衡。","why":"Modern usage puts people on one pan, which is why the phrase appears so often in planning disputes.","whyCN":"现代用法把人放上天平的一端，所以这个短语常出现在规划争议里。"},{"no":"06","title":"Self-regulation of an ecosystem","titleCN":"生态系统的自我调节","definition":"the capacity of an ecosystem to correct small disturbances through its own feedback","definitionCN":"生态系统通过自身反馈修正小扰动的能力","example":"The forest recovered because its ecological balance still had room to adjust.","exampleCN":"森林得以恢复，是因为它的生态平衡还有调整的余地。","why":"Feedback is the mechanism behind the metaphor: a change triggers a counter-change.","whyCN":"反馈是这一比喻背后的机制：一个变化引出反向的变化。"},{"no":"07","title":"Balance between load and carrying capacity","titleCN":"环境承载力与压力的平衡","definition":"a condition in which pressure on a habitat stays within the limit it can absorb","definitionCN":"对栖息地的压力保持在其可承受的限度之内","example":"Nutrient runoff pushed the river past its ecological balance.","exampleCN":"营养物径流把这条河推过了它的生态平衡。","why":"Carrying capacity is a ceiling, and balance is living under it without touching it.","whyCN":"承载力是一个上限，而平衡是在它下面生活而不去顶到它。"},{"no":"08","title":"A conservation goal","titleCN":"保护工作的目标","definition":"a target that environmental policy tries to maintain or restore through management","definitionCN":"环境政策试图通过管理来维持或恢复的目标","example":"The reserve was created to protect the ecological balance of the delta.","exampleCN":"设立这个保护区，是为了保护三角洲的生态平衡。","why":"Policy turns a description into an aim, and the phrase becomes something to keep rather than merely to observe.","whyCN":"政策把描述变成目标，于是这个短语成了要去维持而不只是去观察的东西。"}],"etymology":{"intro":{"en":"Ecological balance joins ecology, coined by Haeckel in the nineteenth century from Greek oikos, house, and logia, study, to balance, from Late Latin bilanx, having two scales. The compound itself is modern and its first date is uncertain.","cn":"这个复合词把「生态学」与「平衡」接在一起：前者由海克尔在十九世纪用希腊语 oikos「住所」与 logia「学问」合成，后者来自晚期拉丁语 bilanx「有两副秤盘」。复合词本身属现代，首见年代不确定。"},"items":[{"era":"GREEK OIKOS","en":"Oikos meant house or dwelling, and ecology began as the study of the household of nature.","cn":"这个词意为住所、家宅，生态学最初就是研究自然这个「家」的学问。"},{"era":"GREEK LOGIA","en":"Logia meant the study or account of something, and it supplies the second half of ecology.","cn":"这个词意为对某事的学问或论述，提供「生态学」的后半部分。"},{"era":"HAECKEL, 1866","en":"Haeckel coined the German term for ecology in the nineteenth century, and English adopted it soon after.","cn":"海克尔在十九世纪造出德语的生态学术语，英语随后采用。"},{"era":"LATIN BILANX","en":"Balance came from bilanx, having two pans, from bi-, two, and lanx, a pan or scale.","cn":"「平衡」来自 bilanx「有两副秤盘」，由 bi-「二」与 lanx「盘、秤」构成。"},{"era":"THE MODERN COMPOUND","en":"The phrase ecological balance belongs to twentieth-century environmental writing; the exact first date is uncertain.","cn":"这个短语属二十世纪的环境写作，确切首见年代不确定。"},{"era":"POLICY EXTENSION","en":"Conservation law turned the phrase into a management target, so it now names something to be kept, not merely described.","cn":"保护法规把这个短语变成管理目标，于是它现在指要维持的东西，而不只是被描述的状态。"}]},"similar":{"note":{"en":"The first group shares the balance or ecology element but means something else; the second group names neighbouring environmental ideas.","cn":"第一组共享「平衡」或「生态」这一成分但意思不同；第二组是与「环境稳定」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"ecology","ipa":"/ɪˈkɒlədʒi/","tag":"same root","definition":"The study of relationships between organisms and their surroundings.","definitionCN":"指研究生物与其环境之间关系的学科。"},{"word":"ecological","ipa":"/ɪˌkɒləˈdʒɪkl/","tag":"same root","definition":"The adjective meaning relating to ecology.","definitionCN":"形容词，指与生态学相关的。"},{"word":"balance","ipa":"/ˈbæləns/","tag":"same element","definition":"A state of equal weight, used far beyond ecology.","definitionCN":"指重量相等的状态，用法远超生态领域。"},{"word":"imbalance","ipa":"/ɪmˈbæləns/","tag":"opposite","definition":"A state of unequal weight, the direct negation.","definitionCN":"指重量不均的状态，是本词的直接否定。"},{"word":"equilibrium","ipa":"/ˌiːkwɪˈlɪbriəm/","tag":"near look","definition":"A state of balance, usually in physics or chemistry.","definitionCN":"指平衡状态，多用于物理或化学。"}]},{"heading":"NEAR MEANING","entries":[{"word":"sustainability","ipa":"/ˌsjuːstəˈnæbələti/","tag":"near meaning","definition":"The capacity to keep going without exhausting resources.","definitionCN":"指不耗尽资源而持续下去的能力。"},{"word":"biodiversity","ipa":"/ˌbaɪəʊdaɪˈvɜːsəti/","tag":"near meaning","definition":"The variety of living things in a place.","definitionCN":"指一个地方生物的多样性。"},{"word":"equilibrium","ipa":"/ˌiːkwɪˈlɪbriəm/","tag":"near meaning","definition":"A balanced state in a system, often measured.","definitionCN":"指系统中的平衡状态，常可测量。"},{"word":"homeostasis","ipa":"/ˌhəʊmiˈsteɪsɪs/","tag":"near meaning","definition":"The self-correcting stability of an organism.","definitionCN":"指生物体自我修正的稳定状态。"},{"word":"carrying capacity","ipa":"/ˈkæriɪŋ kəˈpæsəti/","tag":"near meaning","definition":"The largest load an environment can support.","definitionCN":"指环境能支撑的最大负荷。"},{"word":"conservation","ipa":"/ˌkɒnsəˈveɪʃn/","tag":"near meaning","definition":"The protection of nature from damage.","definitionCN":"指对自然的保护，使之不受损害。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the household at the root of ecology, the two pans at the root of balance, and the policy phrases that keep the compound in use.","cn":"正常联想使用生态学词根里的「家宅」、平衡词根里的「两副秤盘」，以及让这个复合词保持活跃的政策搭配。"},"normal":[{"en":"Oikos is house, so ecology is the study of nature as one household.","cn":"oikos 是「家宅」，所以生态学是把自然当作一个家来研究。"},{"en":"Balance comes from two pans, and an ecosystem balances when no single pan runs away.","cn":"平衡来自两副秤盘，生态系统平衡就是没有哪一盘跑掉。"},{"en":"The phrase is a noun, so it takes maintain, keep, disturb, restore and break as its verbs.","cn":"这个短语是名词，常与维持、保持、扰乱、恢复、破坏这些动词搭配。"},{"en":"Imbalance is the direct opposite and is far more common in headlines.","cn":"失衡是直接反义词，在新闻标题里更常见。"},{"en":"Carrying capacity is the ceiling; balance is what keeps a population under it.","cn":"承载力是天花板，平衡就是让种群待在天花板下面。"}],"abstract":[{"en":"An ecological balance is not a frozen picture but a set of corrections that never stop.","cn":"生态平衡不是一张冻结的图画，而是一组永不停止的修正。"},{"en":"Every pan that rises pulls the other down, which is why the system looks still while moving.","cn":"一端上升必然拉低另一端，所以系统看着不动，其实一直在动。"},{"en":"To protect a balance is to accept that human beings are also one of the weights.","cn":"保护一种平衡，就是承认人类自己也是天平上的一份重量。"}]},"examples":[{"en":"The national park was enlarged to protect the ecological balance of the valley.","cn":"国家公园被扩大，以保护山谷的生态平衡。"},{"en":"Draining the marsh broke the ecological balance that had held for generations.","cn":"排干沼泽破坏了维持数代的生态平衡。"},{"en":"Farmers and biologists worked together to restore an ecological balance in the lake.","cn":"农民与生物学家合作，恢复湖里的生态平衡。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「伊扣勒吉扣 巴伦斯」——水塘里草、鱼、鸟各守其量：生态平衡","word":"ecological balance"},"root":"希腊语 oikos「住所」+ logia「学问」合成 ecology（海克尔，十九世纪）；balance 来自晚期拉丁语 bilanx「有两副秤盘」（bi-「二」+ lanx「盘」）。复合词属现代，首见年代不确定。","sensesIntro":{"en":"Eight senses all describe a system holding steady: the general state, species numbers, the food web, resources, human use, self-correction, carrying capacity and a policy goal.","cn":"八个义项都在描述系统保持稳定：总体状态、物种数量、食物链、资源、人类使用、自我调节、承载力与政策目标。"},"semanticMap":{"core":{"en":"CORE IMAGE: pondweed, small fish and hunting birds each keep their share, so the water is neither bare nor cloudy.","cn":"核心意象：水草、小鱼与捕食的鸟各守其量，水面既不清瘦也不浑浊。"},"chain":["HOUSEHOLD","SPECIES","FOOD WEB","RESOURCES","HUMAN USE","CAPACITY"],"branches":[{"senses":"01","en":"THE WHOLE HOLDS: the ecosystem as a single household stays within its range.","cn":"整体端住：生态系统作为一个家，保持在它的范围内。"},{"senses":"02 · 03","en":"THE WEIGHTS AND THE FLOW: species numbers and the links of the food chain keep one another fed.","cn":"重量与流动：物种数量与食物链各环互相喂饱。"},{"senses":"04 · 07","en":"THE ACCOUNT AND THE CEILING: what grows is matched by what is taken, and pressure stays under capacity.","cn":"账目与上限：长出的与取用的相抵，压力待在承载力之下。"},{"senses":"05","en":"THE HUMAN PAN: people are placed on one side of the scale and must not sink it.","cn":"人的那一盘：人被放上天平一端，不能把它压沉。"},{"senses":"06 · 08","en":"THE CORRECTION AND THE AIM: feedback fixes small shocks, and policy turns the state into a target.","cn":"修正与目标：反馈修正小冲击，政策把状态变成目标。"}]},"affixes":{"intro":{"en":"The compound draws one half from Greek through modern science and the other from Latin through French, which is why its pieces look so different.","cn":"这个复合词一半经现代科学取自希腊语，另一半经法语取自拉丁语，所以部件看起来差别很大。"},"latinIntro":{"en":"Greek supplies oikos and logia, Latin supplies bilanx, bi- and lanx; the modern compound itself has no single classical source.","cn":"希腊语提供 oikos 与 logia，拉丁语提供 bilanx、bi- 与 lanx；现代复合词本身没有单一的古典来源。"},"items":[{"word":"oikos","structure":"Greek noun","meaning":"house, dwelling","meaningCN":"住所；家宅","example":"It supplies the first element of ecology.","exampleCN":"它提供「生态学」的第一个成分。"},{"word":"logia","structure":"Greek noun","meaning":"study, account","meaningCN":"学问；论述","example":"It supplies the second element of ecology.","exampleCN":"它提供「生态学」的第二个成分。"},{"word":"eco-","structure":"modern prefix from oikos","meaning":"household, environment","meaningCN":"家宅；环境","example":"It appears in ecology, ecosystem and ecotourism.","exampleCN":"它出现在 ecology、ecosystem、ecotourism 中。"},{"word":"bilanx","structure":"Late Latin adjective","meaning":"having two pans","meaningCN":"有两副秤盘的","example":"It is the source of balance.","exampleCN":"它是 balance 的来源。"},{"word":"bi-","structure":"Latin prefix","meaning":"two","meaningCN":"二；双","example":"It marks the two pans of the scale.","exampleCN":"它标出天平的两副秤盘。"},{"word":"lanx","structure":"Latin noun","meaning":"pan, scale","meaningCN":"盘；秤","example":"It supplies the pan half of balance.","exampleCN":"它提供 balance 中「盘」的那一半。"},{"word":"-ical","structure":"adjective ending","meaning":"relating to","meaningCN":"与……相关的","example":"It forms ecological from ecology.","exampleCN":"它由 ecology 构成 ecological。"},{"word":"-ist","structure":"agent noun ending","meaning":"one who practices","meaningCN":"从事者","example":"It forms ecologist.","exampleCN":"它构成 ecologist。"},{"word":"-logy","structure":"study suffix","meaning":"the study of","meaningCN":"……学","example":"It forms ecology itself.","exampleCN":"它构成 ecology 本身。"},{"word":"balance","structure":"English noun","meaning":"equal weight","meaningCN":"等重；平衡","example":"The second half of the compound is an everyday noun.","exampleCN":"这个复合词的后半是日常名词。"}],"latinEntries":[{"word":"bilanx","structure":"Late Latin adjective","meaning":"having two pans","meaningCN":"有两副秤盘的"},{"word":"bi-","structure":"Latin prefix","meaning":"two","meaningCN":"二；双"},{"word":"lanx","structure":"Latin noun","meaning":"pan, scale","meaningCN":"盘；秤"},{"word":"oecologia","structure":"Modern Latin noun","meaning":"the study of the household of nature","meaningCN":"研究自然之家宅的学问"}],"derivatives":[{"word":"ecology","pos":"n.","zh":"由希腊语「住所」与「学问」合成，义为「生态学」"},{"word":"ecological","pos":"adj.","zh":"由「生态学」加形容词词尾构成，义为「生态的」"},{"word":"ecologically","pos":"adv.","zh":"由形容词加副词词尾构成，义为「在生态方面」"},{"word":"ecologist","pos":"n.","zh":"由「生态学」加表示从事者的名词尾构成，义为「生态学家」"},{"word":"imbalance","pos":"n.","zh":"由否定前缀加「平衡」构成，义为「失衡」"}]}}]);
